window.CHAPTER17_DATA = {"sections":[{"id":"c17-w01","number":1,"title":"계약 일반","formIds":[],"faqCategories":[],"contentBlocks":[{"id":"c17-w01-b1","title":"세부내용 1. 계약의 의의","body":""},{"id":"c17-w01-b2","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률」 제2조, 제6조"},{"id":"c17-w01-b3","title":"","body":"구분 내용\n계약의 의의 지방자치단체가 공공사업 등을 위해 민간과 맺는 법적 행위\n계약의 원칙 ◦신의성실의 원칙 ◦부당한 특약 금지 ◦상호 대등한 당사자의 합의\n지방자치단체 계약의 법적 근거 ◦지방계약법 ◦지방계약법 시행령 ◦지방계약법 시행규칙 ◦지방자치단체 입찰 및 계약 집행기준 ◦지방자치단체 입찰 시 낙찰자 결정기준 등\n지방계약법 적용대상 기관 시·군·구 및 특별지방자치단체, 계약 사무를 위임·위탁받은 기관·법인 - 공립학교 : 지방계약법 적용(전북특별자치도 공립학교 회계규칙 제35조) - 사립학교 : 지방계약법 적용(사학기관 재무·회계규칙 제40조의 2)","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"계약의 의의","colSpan":1,"rowSpan":1,"column":0},{"text":"지방자치단체가 공공사업 등을 위해 민간과 맺는 법적 행위","colSpan":1,"rowSpan":1,"column":1}],[{"text":"계약의 원칙","colSpan":1,"rowSpan":1,"column":0},{"text":"◦신의성실의 원칙\n◦부당한 특약 금지\n◦상호 대등한 당사자의 합의","colSpan":1,"rowSpan":1,"column":1}],[{"text":"지방자치단체 계약의 법적 근거","colSpan":1,"rowSpan":1,"column":0},{"text":"◦지방계약법\n◦지방계약법 시행령\n◦지방계약법 시행규칙\n◦지방자치단체 입찰 및 계약 집행기준\n◦지방자치단체 입찰 시 낙찰자 결정기준 등","colSpan":1,"rowSpan":1,"column":1}],[{"text":"지방계약법\n적용대상 기관","colSpan":1,"rowSpan":1,"column":0},{"text":"시·군·구 및 특별지방자치단체, 계약 사무를 위임·위탁받은 기관·법인\n- 공립학교 : 지방계약법 적용(전북특별자치도 공립학교 회계규칙 제35조)\n- 사립학교 : 지방계약법 적용(사학기관 재무·회계규칙 제40조의 2)","colSpan":1,"rowSpan":1,"column":1}]],"widths":[18.07,81.93],"lineStart":0,"lineCount":5}]},{"id":"c17-w01-b4","title":"TIP","body":"▪ 계약 법령 구성체계\n구분 / 법령 명칭\n법률 / 지방자치단체를 당사자로 하는 계약에 관한 법률(지방계약법)\n명령 / 〃 시행령(지방계약법 시행령)\n〃 시행규칙(지방계약법 시행규칙)\n행정규칙 (예고‧고시) / 지방자치단체 입찰 및 계약집행기준\n지방자치단체 입찰 시 낙찰자 결정기준"},{"id":"c17-w01-b5","title":"세부내용 2. 계약용어 정리","body":""},{"id":"c17-w01-b6","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」\n• 「같은 법 시행규칙」\n• 「지방자치단체 입찰 및 계약 집행기준」"},{"id":"c17-w01-b7","title":"","body":"용어 내용\n1인견적 수의계약 발주자가 특정 계약상대자 직접 지정하는 계약 ※ 지정된 자와 계약 체결\n2인이상 견적 수의계약 공고를 통해 2인 이상의 견적 참여자로부터 견적을 제출받아 계약상대자를 결정하는 계약 ※ 제출된 견적 중 계약 상대자 선정\n입찰 계약내용을 공고하여 일정한 자격을 갖춘 불특정 다수로부터 입찰서를 제출받아, 경쟁을 통해 최적의 계약상대자를 선정하는 계약\n특수조건 일반조건으로 충족하기 어려운 사항을 보완하기 위해 계약에 특별히 추가되는 조건\n과업지시서 물품·용역·공사 계약 시 구체적인 과업 내용을 명시한 문서\n기초금액 예정가격 산출의 기준이 되는 금액으로, 산출내역서, 거래실례가격, 감정가격, 견적가격 등을 반영한 금액\n산출내역서 계약 또는 입찰에 필요한 금액을 산정하기 위해 각 항목별 비용과 근거를 구체적으로 정리한 문서 ※ 기초금액 산출 근거자료로 활용\n거래실례가격 조달청장 또는 전문기관이 공표한 가격 또는 계약담당공무원이 조사한 실제 거래가격\n감정가격 감정평가법인 또는 감정평가사가 산정한 가격\n견적가격 계약상대자 또는 제3자로부터 제출받은 가격\n추정가격 기초금액에서 부가가치세를 제외한 금액\n예정가격 입찰 전 낙찰자 결정 기준 가격\n추정금액 추정가격+부가세+도급자설치 관급자재비\n관급자재 공공기관이 직접 공급하는 자재(품질, 수급, 현장여건 등을 고려해 결정)\n사급자재 계약상대자가 직접 구매해 시공하는 자재\n도급자 설치 관급자재 발주처에서 구매하는 자재(계약상대자가 설치)\n관급자 설치 관급자재 발주처에서 구매하는 자재(발추처에서 설치)\n도급계약 발주자의 요구에 따라 계약내용 정해지는 계약\n지정정보처리장치 입찰·계약 사무를 전자처리하는 시스템(행정안전부장관이 지정·고시)","tables":[{"headers":[{"text":"용어","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"1인견적\n수의계약","colSpan":1,"rowSpan":1,"column":0},{"text":"발주자가 특정 계약상대자 직접 지정하는 계약\n※ 지정된 자와 계약 체결","colSpan":1,"rowSpan":1,"column":1}],[{"text":"2인이상 견적 수의계약","colSpan":1,"rowSpan":1,"column":0},{"text":"공고를 통해 2인 이상의 견적 참여자로부터 견적을 제출받아 계약상대자를 결정하는 계약\n※ 제출된 견적 중 계약 상대자 선정","colSpan":1,"rowSpan":1,"column":1}],[{"text":"입찰","colSpan":1,"rowSpan":1,"column":0},{"text":"계약내용을 공고하여 일정한 자격을 갖춘 불특정 다수로부터 입찰서를 제출받아, 경쟁을 통해 최적의 계약상대자를 선정하는 계약","colSpan":1,"rowSpan":1,"column":1}],[{"text":"특수조건","colSpan":1,"rowSpan":1,"column":0},{"text":"일반조건으로 충족하기 어려운 사항을 보완하기 위해 계약에 특별히 추가되는 조건","colSpan":1,"rowSpan":1,"column":1}],[{"text":"과업지시서","colSpan":1,"rowSpan":1,"column":0},{"text":"물품·용역·공사 계약 시 구체적인 과업 내용을 명시한 문서","colSpan":1,"rowSpan":1,"column":1}],[{"text":"기초금액","colSpan":1,"rowSpan":1,"column":0},{"text":"예정가격 산출의 기준이 되는 금액으로, 산출내역서, 거래실례가격, 감정가격, 견적가격 등을 반영한 금액","colSpan":1,"rowSpan":1,"column":1}],[{"text":"산출내역서","colSpan":1,"rowSpan":1,"column":0},{"text":"계약 또는 입찰에 필요한 금액을 산정하기 위해 각 항목별 비용과 근거를 구체적으로 정리한 문서\n※ 기초금액 산출 근거자료로 활용","colSpan":1,"rowSpan":1,"column":1}],[{"text":"거래실례가격","colSpan":1,"rowSpan":1,"column":0},{"text":"조달청장 또는 전문기관이 공표한 가격 또는 계약담당공무원이 조사한 실제 거래가격","colSpan":1,"rowSpan":1,"column":1}],[{"text":"감정가격","colSpan":1,"rowSpan":1,"column":0},{"text":"감정평가법인 또는 감정평가사가 산정한 가격","colSpan":1,"rowSpan":1,"column":1}],[{"text":"견적가격","colSpan":1,"rowSpan":1,"column":0},{"text":"계약상대자 또는 제3자로부터 제출받은 가격","colSpan":1,"rowSpan":1,"column":1}],[{"text":"추정가격","colSpan":1,"rowSpan":1,"column":0},{"text":"기초금액에서 부가가치세를 제외한 금액","colSpan":1,"rowSpan":1,"column":1}],[{"text":"예정가격","colSpan":1,"rowSpan":1,"column":0},{"text":"입찰 전 낙찰자 결정 기준 가격","colSpan":1,"rowSpan":1,"column":1}],[{"text":"추정금액","colSpan":1,"rowSpan":1,"column":0},{"text":"추정가격+부가세+도급자설치 관급자재비","colSpan":1,"rowSpan":1,"column":1}],[{"text":"관급자재","colSpan":1,"rowSpan":1,"column":0},{"text":"공공기관이 직접 공급하는 자재(품질, 수급, 현장여건 등을 고려해 결정)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"사급자재","colSpan":1,"rowSpan":1,"column":0},{"text":"계약상대자가 직접 구매해 시공하는 자재","colSpan":1,"rowSpan":1,"column":1}],[{"text":"도급자 설치 관급자재","colSpan":1,"rowSpan":1,"column":0},{"text":"발주처에서 구매하는 자재(계약상대자가 설치)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"관급자 설치 관급자재","colSpan":1,"rowSpan":1,"column":0},{"text":"발주처에서 구매하는 자재(발추처에서 설치)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"도급계약","colSpan":1,"rowSpan":1,"column":0},{"text":"발주자의 요구에 따라 계약내용 정해지는 계약","colSpan":1,"rowSpan":1,"column":1}],[{"text":"지정정보처리장치","colSpan":1,"rowSpan":1,"column":0},{"text":"입찰·계약 사무를 전자처리하는 시스템(행정안전부장관이 지정·고시)","colSpan":1,"rowSpan":1,"column":1}]],"widths":[20.71,79.29],"lineStart":0,"lineCount":20}]},{"id":"c17-w01-b8","title":"TIP","body":"▪ 지정정보처리장치 종류\n순 / 지정정보처리장치 / 세부내용\n1 / 국가종합 전자조달시스템 (www.g2b.go.kr) / 지방자치단체조달(공사 · 용역 및 물품의 제조 · 구매)을 위한 입찰\n2 / 교육기관 전자조달시스템 (www.s2b.kr) / ◦추정가격 1억 원 이하의 물품 제조·구매 및 용역에 대한 수의계약·입찰 ◦종합공사 4억 원 이하, 전문공사 2억 원 이하, 기타공사 1억 6천만 원 이하의 수의계약 ◦추정가격 2천만 원 이하의 모든 공사 입찰 시 이용 ※ 다만, 「출판문화산업 진흥법」제22조에 해당하는 간행물을 구매하는 경우에는 금액 한도를 두지 아니함\n3 / 공공급식 전자조달시스템 (ns.eat.co.kr) / 단체급식 식재료 입찰\n4 / 전자자산처분시스템 (www.onbid.co.kr) / 공유재산 및 물품의 관리·처분을 위한 입찰\n5 / 순환자원정보센터 전자입찰시스템 (www.re.or.kr) / 폐기물 · 순환자원 · 재활용 가능 자원 · 재활용제품의 처리용역, 제조 · 구매 및 매각의 입찰 및 계약"},{"id":"c17-w01-b9","title":"세부내용 3. 계약체결요건 및 금지 대상","body":""},{"id":"c17-w01-b10","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률」 제31조, 제33조 제1항, 2항\n• 「같은 법 시행령」 제13조"},{"id":"c17-w01-b11","title":"1. 계약체결 자격요건","body":"요건 법령 및 예시\n계약 이행에 필요한 법정 인·허가, 면허, 등록, 신고 등 자격 보유자 ◦수도법 제34조: 저수조 청소업자 ◦경비업법 제4조: 경비업체 ◦엔지니어링산업진흥법 제21조: 엔지니어링 활동주체 ◦건설산업기본법 제9조: 토목 또는 토목건축공사업자\n보안 측정 등 조사가 필요한 경우, 관계기관으로부터 적합 판정을 받은 자 예: 정보보안, 시설보안 등 관련 평가 통과\n사업자 등록 또는 고유번호를 부여받은 자 ◦소득세법 제168조 ◦법인세법 제111조 ◦부가가치세법 제8조 ◦지방계약법 시행규칙 제14조","tables":[{"headers":[{"text":"요건","colSpan":1,"rowSpan":1,"column":0},{"text":"법령 및 예시","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"계약 이행에 필요한 법정 인·허가, 면허, 등록, 신고 등 자격 보유자","colSpan":1,"rowSpan":1,"column":0},{"text":"◦수도법 제34조: 저수조 청소업자\n◦경비업법 제4조: 경비업체\n◦엔지니어링산업진흥법 제21조: 엔지니어링 활동주체\n◦건설산업기본법 제9조: 토목 또는 토목건축공사업자","colSpan":1,"rowSpan":1,"column":1}],[{"text":"보안 측정 등 조사가 필요한 경우, 관계기관으로부터 적합 판정을 받은 자","colSpan":1,"rowSpan":1,"column":0},{"text":"예: 정보보안, 시설보안 등 관련 평가 통과","colSpan":1,"rowSpan":1,"column":1}],[{"text":"사업자 등록 또는 고유번호를 부여받은 자","colSpan":1,"rowSpan":1,"column":0},{"text":"◦소득세법 제168조 ◦법인세법 제111조\n◦부가가치세법 제8조 ◦지방계약법 시행규칙 제14조","colSpan":1,"rowSpan":1,"column":1}]],"widths":[44.74,55.26],"lineStart":0,"lineCount":4}]},{"id":"c17-w01-b12","title":"2. 계약체결 금지대상","body":"금지대상 법령\n해당 지방자치단체장 또는 지방의회의원이 사업자인 경우 지방계약법 제33조 제1항\n해당 지방자치단체장 또는 지방의회의원의 직계 존·비속, 배우자, 계열회사 지방계약법 제33조 제2항\n다음에 해당하는 자는 계약 체결 불가 ◦부정당업자 제재로 입찰참가자격 제한 중인 자 ◦영업 정지 중이거나, 다른 법령에 따라 영업 또는 사업행위가 일시 정지된 자 지방계약법 제31조","tables":[{"headers":[{"text":"금지대상","colSpan":1,"rowSpan":1,"column":0},{"text":"법령","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"해당 지방자치단체장 또는 지방의회의원이 사업자인 경우","colSpan":1,"rowSpan":1,"column":0},{"text":"지방계약법 제33조 제1항","colSpan":1,"rowSpan":1,"column":1}],[{"text":"해당 지방자치단체장 또는 지방의회의원의 직계 존·비속, 배우자, 계열회사","colSpan":1,"rowSpan":1,"column":0},{"text":"지방계약법 제33조 제2항","colSpan":1,"rowSpan":1,"column":1}],[{"text":"다음에 해당하는 자는 계약 체결 불가\n◦부정당업자 제재로 입찰참가자격 제한 중인 자\n◦영업 정지 중이거나, 다른 법령에 따라 영업 또는 사업행위가 일시 정지된 자","colSpan":1,"rowSpan":1,"column":0},{"text":"지방계약법 제31조","colSpan":1,"rowSpan":1,"column":1}]],"widths":[72.76,27.24],"lineStart":0,"lineCount":4}]},{"id":"c17-w01-b13","title":"세부내용 4. 계약 업무 절차","body":"계약 절차 주 요 내 용\n계약심사 [예시 1] ◦원가심사대상: 공사 추정금액 5억원(종합공사가 아닌 공사의 경우 3억원 이상), 추정금액 용역 7천만원이상, 물품 추정금액 2천만원 이상 ※ 사립학교 공사계약은 계약심사 대신 일상감사로 대체함 ◦설계변경심사대상: 계약금액 10% 이상 증가 시\n일상감사 [예시 2] ◦계약 일상감사대상 - 물품 제조·구매: 추정금액 5천만원 이상 ※ 도교육청 각 부서의 경우 추정금액 1억원 이상, 교육지원청의 경우 추정금액 5천만원 이상의 신·이설학교 물품 구매시일상감사 대상 - 공사계약: 추정금액 5천만원 이상 ※ 도교육청 각 부서와 교육지원청의 경우 추정금액 1억원 이상의 수의계약 건, 직속기관의 경우 추정금액 1억원 이상일 경우 일상감사 대상 ◦설계변경에 따른 일상감사 대상 - 설계변경 등으로 공사비가 당초보다 10% 이상 증액된 공사(설계용역) 중 시설공사의 경우 증액 1억이상, 설계용역의 경우 증액 3천만원 이상일 시 일상감사 대상\n품의서 작성 유의사항 - 집행내용이 예산편성 목적과 부합되는 지 - 예산은 배정되어 있는지 여부 - 집행예정금액은 법령 또는 기준 내의 단가에 의한 산출인지 여부 - 산출내역(원가계산)이 관련 법령에 따라 올바르게 작성 되어있는지 확인 - 견적서를 제출 받은 경우 견적 금액이 적절한지 확인\n계약방법 결정 [예시 3] ◦계약 목적물별: 공사 계약 / 물품제조·구매 등 계약 / 용역 계약 등 ◦경쟁 형태별: 일반 입찰 / 제한 입찰 / 지명 입찰 / 수의 계약 등 ◦계약체결 형태별: 총액 / 단가 계약, 확정 / 개산 계약, 단독 / 공동 계약 등 ◦입찰 시 낙찰자 선정 방법별: 적격 심사 / 2단계 입찰 / 협상에 의한 계약 등\n입찰 공고 또는 수의견적 제출 안내 공고 [예시 4] ◦입찰 및 수의견적 제출 공고 장소: 지정정보처리장치 ◦수의견적 제출 안내 공고 금액 기준(지방계약법 시행령 제25조 1항 5호) - 물품, 용역 계약: 추정가격 2천만원 초과 1억원이하 - 공사 계약: 종합공사(추정가격 2천만원 초과 4억원이하), 전문공사(추정가격 2천만원 초과 2억원 이하), 그 외 공사(전기,통신,소방등)(추정가격 2천만원 이상 1억 6천만원 미만) ◦수의견적 제출 안내 공고 기간(지방자치단체 입찰 및 계약집행기준 제5장 수의계약 운영 요령) - 공고: 공고일 + 3일 + 개찰일(총 5일) ※ 토요일,공휴일은 수의견적 제출 안내 공고 기간에 포함되지 않음 ◦입찰 공고 기간(지방계약법 시행령 제35조) - 공고: 공고일 + 7일 + 개찰일(총 9일) - 긴급공고: 공고일 + 5일 + 개찰일(총 7일) - 재공고: 공고일 + 5일 + 개찰일(총 7일)","tables":[{"headers":[{"text":"계약 절차","colSpan":1,"rowSpan":1,"column":0},{"text":"주 요 내 용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"계약심사\n[예시 1]","colSpan":1,"rowSpan":1,"column":0},{"text":"◦원가심사대상: 공사 추정금액 5억원(종합공사가 아닌 공사의 경우 3억원 이상), 추정금액 용역 7천만원이상, 물품 추정금액 2천만원 이상\n※ 사립학교 공사계약은 계약심사 대신 일상감사로 대체함\n◦설계변경심사대상: 계약금액 10% 이상 증가 시","colSpan":1,"rowSpan":1,"column":1}],[{"text":"일상감사\n[예시 2]","colSpan":1,"rowSpan":1,"column":0},{"text":"◦계약 일상감사대상\n- 물품 제조·구매: 추정금액 5천만원 이상\n※ 도교육청 각 부서의 경우 추정금액 1억원 이상, 교육지원청의 경우 추정금액 5천만원 이상의 신·이설학교 물품 구매시일상감사 대상\n- 공사계약: 추정금액 5천만원 이상\n※ 도교육청 각 부서와 교육지원청의 경우 추정금액 1억원 이상의 수의계약 건, 직속기관의 경우 추정금액 1억원 이상일 경우 일상감사 대상\n◦설계변경에 따른 일상감사 대상\n- 설계변경 등으로 공사비가 당초보다 10% 이상 증액된 공사(설계용역) 중 시설공사의 경우 증액 1억이상, 설계용역의 경우 증액 3천만원 이상일 시 일상감사 대상","colSpan":1,"rowSpan":1,"column":1}],[{"text":"품의서 작성","colSpan":1,"rowSpan":1,"column":0},{"text":"유의사항\n- 집행내용이 예산편성 목적과 부합되는 지\n- 예산은 배정되어 있는지 여부\n- 집행예정금액은 법령 또는 기준 내의 단가에 의한 산출인지 여부\n- 산출내역(원가계산)이 관련 법령에 따라 올바르게 작성 되어있는지 확인\n- 견적서를 제출 받은 경우 견적 금액이 적절한지 확인","colSpan":1,"rowSpan":1,"column":1}],[{"text":"계약방법\n결정\n[예시 3]","colSpan":1,"rowSpan":1,"column":0},{"text":"◦계약 목적물별: 공사 계약 / 물품제조·구매 등 계약 / 용역 계약 등\n◦경쟁 형태별: 일반 입찰 / 제한 입찰 / 지명 입찰 / 수의 계약 등\n◦계약체결 형태별: 총액 / 단가 계약, 확정 / 개산 계약, 단독 / 공동 계약 등\n◦입찰 시 낙찰자 선정 방법별: 적격 심사 / 2단계 입찰 / 협상에 의한 계약 등","colSpan":1,"rowSpan":1,"column":1}],[{"text":"입찰 공고\n또는\n수의견적 제출\n안내 공고\n[예시 4]","colSpan":1,"rowSpan":1,"column":0},{"text":"◦입찰 및 수의견적 제출 공고 장소: 지정정보처리장치\n◦수의견적 제출 안내 공고 금액 기준(지방계약법 시행령 제25조 1항 5호)\n- 물품, 용역 계약: 추정가격 2천만원 초과 1억원이하\n- 공사 계약: 종합공사(추정가격 2천만원 초과 4억원이하), 전문공사(추정가격 2천만원 초과 2억원 이하), 그 외 공사(전기,통신,소방등)(추정가격 2천만원 이상 1억 6천만원 미만)\n◦수의견적 제출 안내 공고 기간(지방자치단체 입찰 및 계약집행기준 제5장 수의계약 운영 요령)\n- 공고: 공고일 + 3일 + 개찰일(총 5일)\n※ 토요일,공휴일은 수의견적 제출 안내 공고 기간에 포함되지 않음\n◦입찰 공고 기간(지방계약법 시행령 제35조)\n- 공고: 공고일 + 7일 + 개찰일(총 9일)\n- 긴급공고: 공고일 + 5일 + 개찰일(총 7일)\n- 재공고: 공고일 + 5일 + 개찰일(총 7일)","colSpan":1,"rowSpan":1,"column":1}]],"widths":[16.53,83.47],"lineStart":0,"lineCount":6}]},{"id":"c17-w01-b14","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률」, 「같은 법 시행령」"},{"id":"c17-w01-b15","title":"","body":"계약 절차 주 요 내 용\n- 2단계 경쟁입찰(추정가격 1억미만): 공고일 + 10일 + 규격제안서 제출 마감일 - 2단계 경쟁입찰(추정가격 1억~10억미만): 공고일 + 20일 + 규격제안서 제출 마감일 - 2단계 경쟁입찰(추정가격 10억이상): 공고일 + 40일 + 규격제안서 제출 마감일 - 2단계 경쟁입찰(긴급): 공고일 + 10일 + 규격제안서 제출 마감일 - 공사계약(추정가격 10억원 미만): 공고일 + 7일 + 입찰서 제출 마감일(총9일) ◦수의견적 제출 안내공고 시 업무순서 - G2B: 발주계획 입력 → 공고 입력 → 공고문 게시 → 기초금액 입력 → 개찰 - S2B: 공고 입력(공고문 입력 시 기초금액 입력) → 공고문 게시 → 복수예가 작성 → 개찰 ◦입찰 공고 시 업무순서 - G2B: 발주계획 입력 → 사전규격 공개 입력(수의계약이나 5천만원 미만 입찰, 공사계약시 생략 가능, 공개기간은 5일, 긴급시 3일, 초일 불산입) → 공고 입력 → 공고문 게시 → 기초금액 입력 → 개찰 ◦특이사항 - 경쟁입찰 시 입찰자가 1인뿐인 경우 재공고 입찰을 실시하지 않고 수의계약 가능 ※ 지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시(2025.12.31.까지)\n현장설명 및 설계서 열람 필요 시 현장설명 및 설계서 열람 - 추정가격 300억원 이상 공사의 경우 현장설명 및 청취 의무(지방계약법 시행령 제15조)\n입찰서 제출 (계약희망업체) 입찰서의 제출(지방계약법 시행령 제39조) - 입찰공고 시 표시된 장소와 일시에 입찰서 제출\n개찰 [예시 5] 개찰(지방계약법 시행령 제40조)\n적격심사 [예시 6] ◦적격심사 실시(낙찰하한율, 적격통과점수 확인) - 예정가격 이하 최저가 입찰자 순으로 계약이행능력 심사 후 결정 ◦적격심사 서류 접수: 적격심사 낙찰자 결정 기준에 따라 변동 ※ 지방자치단체 입찰 시 낙찰자 결정기준: 7일 이내, 조달청 일반용역 적격심사 세부기준: 5일 이내 등\n계약상대자결정 및 계약체결 [예시 7] ◦낙찰자 통보 후 10일이내 계약체결 완료 ◦표준계약서 작성(계약체결·이행·대가지급 참고)\n계약이행 과업지시서 예정공정표, 산출내역서, 설계서 등 발주자가 명시한 내역 이행 여부 확인 실시\n선금지급 [예시 8] 업체 요청 시 선금 지급\n검사검수 ◦기한: 계약의 이행을 완료한 사실을 통지받은 날로부터 14일 이내 ※ 현행: 지방자치단체를 당사자로 하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시에 따라 7일로 단축(2025.12.31.까지) ◦검사조서 생략이 가능한 경우: 계약금액 3천만 원 이하의 계약, 매각계약의 경우, 전기·가스·수도의 공급 계약 등 그 성질상 조서 작성이 필요하지 아니한 계약(지방계약법 17조 제3항)\n대가 지급 기한: 청구일로부터 5일 이내(공휴일 및 토요일 제외) ※ 현행: 지방자치단체를 당사자로 하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시에 따라 3일로 단축(2025.12.31.까지)\n대장 등재 및 하자보수관리 관련대장정리: 통합자산(시설,물품 등), 연혁지, 시설배치도","tables":[{"headers":[{"text":"계약 절차","colSpan":1,"rowSpan":1,"column":0},{"text":"주 요 내 용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"","colSpan":1,"rowSpan":1,"column":0},{"text":"- 2단계 경쟁입찰(추정가격 1억미만): 공고일 + 10일 + 규격제안서 제출 마감일\n- 2단계 경쟁입찰(추정가격 1억~10억미만): 공고일 + 20일 + 규격제안서 제출 마감일\n- 2단계 경쟁입찰(추정가격 10억이상): 공고일 + 40일 + 규격제안서 제출 마감일\n- 2단계 경쟁입찰(긴급): 공고일 + 10일 + 규격제안서 제출 마감일\n- 공사계약(추정가격 10억원 미만): 공고일 + 7일 + 입찰서 제출 마감일(총9일)\n◦수의견적 제출 안내공고 시 업무순서\n- G2B: 발주계획 입력 → 공고 입력 → 공고문 게시 → 기초금액 입력 → 개찰\n- S2B: 공고 입력(공고문 입력 시 기초금액 입력) → 공고문 게시 → 복수예가 작성 → 개찰\n◦입찰 공고 시 업무순서\n- G2B: 발주계획 입력 → 사전규격 공개 입력(수의계약이나 5천만원 미만 입찰, 공사계약시 생략 가능, 공개기간은 5일, 긴급시 3일, 초일 불산입) → 공고 입력 → 공고문 게시 → 기초금액 입력 → 개찰\n◦특이사항\n- 경쟁입찰 시 입찰자가 1인뿐인 경우 재공고 입찰을 실시하지 않고 수의계약 가능\n※ 지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시(2025.12.31.까지)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"현장설명 및\n설계서 열람","colSpan":1,"rowSpan":1,"column":0},{"text":"필요 시 현장설명 및 설계서 열람\n- 추정가격 300억원 이상 공사의 경우 현장설명 및 청취 의무(지방계약법 시행령 제15조)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"입찰서 제출\n(계약희망업체)","colSpan":1,"rowSpan":1,"column":0},{"text":"입찰서의 제출(지방계약법 시행령 제39조)\n- 입찰공고 시 표시된 장소와 일시에 입찰서 제출","colSpan":1,"rowSpan":1,"column":1}],[{"text":"개찰\n[예시 5]","colSpan":1,"rowSpan":1,"column":0},{"text":"개찰(지방계약법 시행령 제40조)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"적격심사\n[예시 6]","colSpan":1,"rowSpan":1,"column":0},{"text":"◦적격심사 실시(낙찰하한율, 적격통과점수 확인)\n- 예정가격 이하 최저가 입찰자 순으로 계약이행능력 심사 후 결정\n◦적격심사 서류 접수: 적격심사 낙찰자 결정 기준에 따라 변동\n※ 지방자치단체 입찰 시 낙찰자 결정기준: 7일 이내, 조달청 일반용역 적격심사 세부기준: 5일 이내 등","colSpan":1,"rowSpan":1,"column":1}],[{"text":"계약상대자결정\n및 계약체결\n[예시 7]","colSpan":1,"rowSpan":1,"column":0},{"text":"◦낙찰자 통보 후 10일이내 계약체결 완료\n◦표준계약서 작성(계약체결·이행·대가지급 참고)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"계약이행","colSpan":1,"rowSpan":1,"column":0},{"text":"과업지시서 예정공정표, 산출내역서, 설계서 등 발주자가 명시한 내역 이행 여부 확인 실시","colSpan":1,"rowSpan":1,"column":1}],[{"text":"선금지급\n[예시 8]","colSpan":1,"rowSpan":1,"column":0},{"text":"업체 요청 시 선금 지급","colSpan":1,"rowSpan":1,"column":1}],[{"text":"검사검수","colSpan":1,"rowSpan":1,"column":0},{"text":"◦기한: 계약의 이행을 완료한 사실을 통지받은 날로부터 14일 이내\n※ 현행: 지방자치단체를 당사자로 하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시에 따라 7일로 단축(2025.12.31.까지)\n◦검사조서 생략이 가능한 경우: 계약금액 3천만 원 이하의 계약, 매각계약의 경우, 전기·가스·수도의 공급 계약 등 그 성질상 조서 작성이 필요하지 아니한 계약(지방계약법 17조 제3항)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"대가 지급","colSpan":1,"rowSpan":1,"column":0},{"text":"기한: 청구일로부터 5일 이내(공휴일 및 토요일 제외)\n※ 현행: 지방자치단체를 당사자로 하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시에 따라 3일로 단축(2025.12.31.까지)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"대장 등재 및 하자보수관리","colSpan":1,"rowSpan":1,"column":0},{"text":"관련대장정리: 통합자산(시설,물품 등), 연혁지, 시설배치도","colSpan":1,"rowSpan":1,"column":1}]],"widths":[16.43,83.57],"lineStart":0,"lineCount":12}]},{"id":"c17-w01-b16","title":"TIP","body":"▪ 도급, 용역, 위탁 등 계약 시 종사자 안전 및 보건 확보 조치(산업안전보건)\n1. 업체 선정 시: 수급인의 산업재해 예방 조치 능력을 평가하기 위해 “수급업체 안전보건 수준 평가기준” 제시 및 평가 항목별 안전관리 활동이 반영된 “안전보건관리계획서[서식 1]” 제출 요구\n2. A / S 등 단순 1회성의 작업인 경우: “1회성 공사(용역) 자율안전 점검표 제출 요구[서식 2]”\n3. 입찰 시 공고 단계에 “안전보건수준 평가 기준[서식 3]” 제시 및 “안전보건관리계획서” 제출 요구,계약 시 선정된 업체에 대해 “안전보건수준 평가[서식 4]”\n※ “안전보건 이행 서약서” 등으로 “안전보건 수준 평가”를 갈음할 수 없음\n4. 서류보존기한: 사업 수행 시 수급인이 작성한 평가 결과에서 확인·서명 후, 위험성 평가 대상의 유해 ·위험요인, 위험성 결정내용, 위험성 결정에 따른 조치 내용 등에 대한 자료를 5년간 보존"},{"id":"c17-w01-b17","title":"세부내용 5. 예정가격의 정의 및 작성 절차","body":""},{"id":"c17-w01-b18","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률」 제11조\n• 「같은 법 시행령」 제8조, 제10조\n• 「지방자치단체 입찰 및 계약집행기준」 제2장 예정가격 작성요령"},{"id":"c17-w01-b19","title":"1. 예정가격의 정의","body":"‣계약담당자가 계약을 체결함에 있어 낙찰자(계약상대자) 또는 계약금액을 결정하는 기준 등으로 삼기 위하여 입찰 또는 계약 체결 전에 미리 작성 비치해 두는 가격"},{"id":"c17-w01-b20","title":"2. 예정가격의 결정기준","body":"결정기준 요 건 내 용\n거래 실례 가격 시중에 적정한 거래가 형성된 경우 ◦조달청이 조사하여 통보한 가격(가격정보) ◦기획재정부에 등록한 전문가격조사기관이 조사하여 공표한 가격(거래가격, 물가자료, 유통물가, 물가정보 등) ◦지방자치단체의 장이나 계약담당자가 둘 이상의 사업자에 대하여 직접 조사하여 확인한 가격 ◦법령에 가격이 결정된 경우 그 결정가격 범위에서 거래실례가격\n원가계산에 의한 가격 계약의 특수성으로 인하여 적정한 거래실례가격이 없는 경우 제조·공사·용역 원가계산으로 구분 ※ 계약 목적물의 내용, 성질 등이 특수하여 직접 원가계산을 하기 곤란한 경우 원가 계산 용역 기관에 원가계산 의뢰하여 작성(연구기관, 연구소, 회계법인, 민법·다른 법령에 따라 주무관청의 허가를 받아 설립된 법인)","tables":[{"headers":[{"text":"결정기준","colSpan":1,"rowSpan":1,"column":0},{"text":"요 건","colSpan":1,"rowSpan":1,"column":1},{"text":"내 용","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"거래 실례 가격","colSpan":1,"rowSpan":1,"column":0},{"text":"시중에 적정한 거래가 형성된 경우","colSpan":1,"rowSpan":1,"column":1},{"text":"◦조달청이 조사하여 통보한 가격(가격정보)\n◦기획재정부에 등록한 전문가격조사기관이 조사하여 공표한 가격(거래가격, 물가자료, 유통물가, 물가정보 등)\n◦지방자치단체의 장이나 계약담당자가 둘 이상의 사업자에 대하여 직접 조사하여 확인한 가격\n◦법령에 가격이 결정된 경우 그 결정가격 범위에서 거래실례가격","colSpan":1,"rowSpan":1,"column":2}],[{"text":"원가계산에 의한 가격","colSpan":1,"rowSpan":1,"column":0},{"text":"계약의 특수성으로 인하여 적정한 거래실례가격이 없는 경우","colSpan":1,"rowSpan":1,"column":1},{"text":"제조·공사·용역 원가계산으로 구분\n※ 계약 목적물의 내용, 성질 등이 특수하여 직접 원가계산을 하기 곤란한 경우 원가 계산 용역 기관에 원가계산 의뢰하여 작성(연구기관, 연구소, 회계법인, 민법·다른 법령에 따라 주무관청의 허가를 받아 설립된 법인)","colSpan":1,"rowSpan":1,"column":2}]],"widths":[11.26,20.67,68.07],"lineStart":0,"lineCount":3}]},{"id":"c17-w01-b21","title":"3. 예정가격의 작성 절차","body":"구분 내용\n예정가격 작성 순서 추정가격 작성 → 설계가격 또는 조사가격 작성 → 기초금액 작성 → (복수예비가격 작성) → 예정가격조서[서식 5] 작성(지정정보처리장치를 통한 입찰 및 수의계약 안내공고시 시스템상 자동 작성되며 지방계약법 시행령 제26조제2항에 따라 수의계약하는 경우 지정정보처리장치를 통해 수의시담을 해야 하며 이때 예정가격조서를 수기 작성함) → 예정가격 결정 ※ 재료비, 노무비, 경비 등의 물량 또는 가격이 해당 비목의 반영기준에 비해 과다‧과소 반영되어 있는 경우 이를 가감조정한 후 부가가치세액 등을 합산하여 확정","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"예정가격\n작성 순서","colSpan":1,"rowSpan":1,"column":0},{"text":"추정가격 작성 → 설계가격 또는 조사가격 작성 → 기초금액 작성 → (복수예비가격 작성) → 예정가격조서[서식 5] 작성(지정정보처리장치를 통한 입찰 및 수의계약 안내공고시 시스템상 자동 작성되며 지방계약법 시행령 제26조제2항에 따라 수의계약하는 경우 지정정보처리장치를 통해 수의시담을 해야 하며 이때 예정가격조서를 수기 작성함) → 예정가격 결정\n※ 재료비, 노무비, 경비 등의 물량 또는 가격이 해당 비목의 반영기준에 비해 과다‧과소 반영되어 있는 경우 이를 가감조정한 후 부가가치세액 등을 합산하여 확정","colSpan":1,"rowSpan":1,"column":1}]],"widths":[12.02,87.98],"lineStart":0,"lineCount":2}]},{"id":"c17-w01-b22","title":"4. 예정가격의 비치 및 입력","body":"‣서면에 의한 입찰이나 수의계약의 경우\n- 작성된 예정가격을 밀봉하여 미리 개찰 장소나 가격 협상장소 등에 비치\n‣지정정보처리장치(G2B)를 통한 입찰이나 수의계약의 경우\n- 시스템을 통해 예정가격이 자동 산출\n단, [지방계약법 시행령 제26조제2항에 따른 수의시담의 경우 예정가격조서를 수기로 작성하여 예정가격을 확정 한 뒤 직접 지정정보처리장치(G2B)에 입력]"},{"id":"c17-w01-b23","title":"TIP","body":"▪ 예정가격 작성 예외\n순 / 예정가격 작성 예외 사유 / 근거\n1 / 협상에 의한 계약 / 지방자치단체 입찰 및 계약집행기준 제2장 제2절\n2 / 경쟁적 대화에 의한 계약\n3 / 개산계약\n4 / 일괄입찰 및 기본설계 기술제안 입찰\n5 / 국가기관 또는 다른 지방자치단체와 수의계약 하는 경우\n6 / 거래실례가격이 없어 예정가격을 작성하기 곤란한 경우로 국제입찰 적용 대상인 물품・용역(상세 사유는 지방자치단체 입찰 및 계약집행기준 제2장 2절에 명시)\n7 / 추정가격 4억원 이하 종합공사 중 수의계약 단, [시행령 제30조 제2항에 따라 지정정보처리장치를 이용하여 견적서를 제출하게 하는 경우에는 예정가격을 작성]\n8 / 추정가격 2억원 이하 전문공사 중 수의계약 단, [시행령 제30조 제2항에 따라 지정정보처리장치를 이용하여 견적서를 제출하게 하는 경우에는 예정가격을 작성]\n9 / 추정가격 1.6억원 이하 전기・통신・소방・기타공사 중 수의계약 단, [시행령 제30조 제2항에 따라 지정정보처리장치를 이용하여 견적서를 제출하게 하는 경우에는 예정가격을 작성]\n10 / 추정가격 1억원 이하 물품제조・구매・용역 중 수의계약 단, [시행령 제30조 제2항에 따라 지정정보처리장치를 이용하여 견적서를 제출하게 하는 경우에는 예정가격을 작성]\n11 / 추정가격 5천만원 이하인 임대차계약 등 그밖의 계약의 경우로 수의계약을 체결하려는 경우단, [시행령 제30조 제2항에 따라 지정정보처리장치를 이용하여 견적서를 제출하게 하는 경우(수의계약 안내공고, 시행령 제26조제2항에 따른 수의계약) 에는 예정가격을 작성]"},{"id":"c17-w01-b24","title":"세부내용 6. 계약체결·이행·대가지급","body":""},{"id":"c17-w01-b25","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제49조, 제51조, 제53조, 제54조, 제56조, 제64조, 제66조, 제67조\n• 「지방자치단체 입찰 및 계약집행기준」\n• 「국민건강보험법」 제81조의4\n• 「국민연금법」 제95조의2\n• 「고용보험 및 산업재해보상보험의 보험료징수 등에 관한 법률」 제29조의4\n• 「국세징수법」 제107조\n• 「지방세징수법」 제5조"},{"id":"c17-w01-b26","title":"1. 계약체결","body":"‣계약담당공무원과 계약상대자의 기명 ․ 날인(학교장 직인)으로 확정\n구 분 내 용\n계약체결일 낙찰통지를 받은 후 10일 이내\n공사계약 체결 시 징구 서류 목록 공사도급표준계약서, 계약보증서 등(2024. 계약실무편람 156p 참고)\n물품계약 체결 시 징구 서류 목록 물품표준계약서, 계약보증서 등(2024. 계약실무편람 473p 참고)\n용역계약 체결 시 징구 서류 목록 용역표준계악서, 계약보증서 등(2024. 계약실무편람 328p 참고)","tables":[{"headers":[{"text":"구 분","colSpan":1,"rowSpan":1,"column":0},{"text":"내 용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"계약체결일","colSpan":1,"rowSpan":1,"column":0},{"text":"낙찰통지를 받은 후 10일 이내","colSpan":1,"rowSpan":1,"column":1}],[{"text":"공사계약 체결 시 징구 서류 목록","colSpan":1,"rowSpan":1,"column":0},{"text":"공사도급표준계약서, 계약보증서 등(2024. 계약실무편람 156p 참고)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"물품계약 체결 시 징구 서류 목록","colSpan":1,"rowSpan":1,"column":0},{"text":"물품표준계약서, 계약보증서 등(2024. 계약실무편람 473p 참고)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"용역계약 체결 시 징구 서류 목록","colSpan":1,"rowSpan":1,"column":0},{"text":"용역표준계악서, 계약보증서 등(2024. 계약실무편람 328p 참고)","colSpan":1,"rowSpan":1,"column":1}]],"widths":[22,78],"lineStart":1,"lineCount":5}]},{"id":"c17-w01-b27","title":"TIP","body":"▪ 계약체결 시 계약 서 작성 생략 가능 사유\n계약서 생략이 가능한 경우 / 근거\n계약금액이 5천만원 이하인 계약을 체결하는 경우 / 지방계약법 시행령 제50조\n경매에 부치는 경우\n물품을 매각할 때 매수인이 즉시 대금을 내고 그 물품을 인수하는 경우\n국가기관과 계약을 체결하거나 다른 지방자치단체와 계약을 체결하는 경우\n전기・가스・수도의 공급계약 등 그 계약의 성질상 계약서를 작성할 필요가 없는 경우\n천재지변・전잔장애 또는 그밖의 부득이한 사유로 정보처리장치를 이용할 수 없는 경우\n※ 단, 계약서의 작성을 생략하는 경우 계약상대자로부터 청구서, 각서, 협정서, 승낙사항 등 계약 성립의 증거가 될 수 있는 서류를 제출받아 갖춰 둬야 함(지방계약법 시행규칙 제48조)"},{"id":"c17-w01-b28","title":"2. 계약이행보증(지방계약법 시행령 제51조)","body":"보증 유형 내용\n계약보증금(보증서) ◦물품‧용역 보증 요율: 계약금액의 10% 이상 ◦한시적 특례에 따른 보증 요율: 계약금액의 5% 이상 ※ 관련 특례 고시: 지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시 ※ 단가 계약 시 계약 보증금 산식: 이행예정량 중 최대량 × 계약단가 × 10%\n보증 유형 내용\n공사이행보증서 다음 중 하나에 해당할 경우, 계약보증금(보증서) 대신 공사이행보증서 발급 ◦추정가격 300억 원 이상 공사계약 ◦실시설계 기술제안 입찰 ◦공사 특성상 필요 인정되는 경우 - 보증 요율: 계약금액의 40% 이상 ※ 단, 예정가격의 70% 미만으로 낙찰된 경우 50% 이상 ◦한시적 특례(지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시, 2025. 12. 31.까지)에 따른 보증 요율 - 계약금액의 20% 이상 - 예정가격의 70% 미만 낙찰 공사: 30% 이상","tables":[{"headers":[{"text":"보증 유형","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"계약보증금(보증서)","colSpan":1,"rowSpan":1,"column":0},{"text":"◦물품‧용역 보증 요율: 계약금액의 10% 이상\n◦한시적 특례에 따른 보증 요율: 계약금액의 5% 이상\n※ 관련 특례 고시: 지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시\n※ 단가 계약 시 계약 보증금 산식: 이행예정량 중 최대량 × 계약단가 × 10%","colSpan":1,"rowSpan":1,"column":1}]],"widths":[20.75,79.25],"lineStart":0,"lineCount":2},{"headers":[{"text":"보증 유형","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"공사이행보증서","colSpan":1,"rowSpan":1,"column":0},{"text":"다음 중 하나에 해당할 경우, 계약보증금(보증서) 대신 공사이행보증서 발급\n◦추정가격 300억 원 이상 공사계약\n◦실시설계 기술제안 입찰\n◦공사 특성상 필요 인정되는 경우\n- 보증 요율: 계약금액의 40% 이상\n※ 단, 예정가격의 70% 미만으로 낙찰된 경우 50% 이상\n◦한시적 특례(지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시, 2025. 12. 31.까지)에 따른 보증 요율\n- 계약금액의 20% 이상\n- 예정가격의 70% 미만 낙찰 공사: 30% 이상","colSpan":1,"rowSpan":1,"column":1}]],"widths":[20.75,79.25],"lineStart":2,"lineCount":2}]},{"id":"c17-w01-b29","title":"TIP","body":"▪ 계약보증금(보증서) 면제 대상\n면제대상 / 비고\n계약금액 5천만 원 이하 계약 / 면제 시에도 계약보증금 세입조치 사유 발생 시 해당 금액 납부를 보장하는 지급확약서[서식 6] 제출 필수\n지방계약법 시행령 제37조 제3항 제1호~5호 및 제6호의2에 해당하는 자와 계약 체결 시\n일반적 계약 관행상 계약보증금 징수가 부적절한 경우 (예: 신용카드 구매 등)"},{"id":"c17-w01-b30","title":"3. 계약인지세","body":"과세문서 계약금액 인지세액\n도급 또는 위임에 관한 증서 (지방계약법 제14조에 따라 작성한 계약서) ~ 1천만 원 이하 면제\n1천만 원 초과 ~ 3천만 원 이하 2만원\n3천만 원 초과 ~ 5천만 원 이하 4만원\n5천만 원 초과 ~ 1억 원 이하 7만원\n1억 원 초과 ~ 10억 원 이하 15만원\n10억 원 초과 ~ 35만원","tables":[{"headers":[{"text":"과세문서","colSpan":1,"rowSpan":1,"column":0},{"text":"계약금액","colSpan":1,"rowSpan":1,"column":1},{"text":"인지세액","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"도급 또는 위임에 관한 증서\n(지방계약법 제14조에 따라 작성한 계약서)","colSpan":1,"rowSpan":6,"column":0},{"text":"~ 1천만 원 이하","colSpan":1,"rowSpan":1,"column":1},{"text":"면제","colSpan":1,"rowSpan":1,"column":2}],[{"text":"1천만 원 초과 ~ 3천만 원 이하","colSpan":1,"rowSpan":1,"column":1},{"text":"2만원","colSpan":1,"rowSpan":1,"column":2}],[{"text":"3천만 원 초과 ~ 5천만 원 이하","colSpan":1,"rowSpan":1,"column":1},{"text":"4만원","colSpan":1,"rowSpan":1,"column":2}],[{"text":"5천만 원 초과 ~ 1억 원 이하","colSpan":1,"rowSpan":1,"column":1},{"text":"7만원","colSpan":1,"rowSpan":1,"column":2}],[{"text":"1억 원 초과 ~ 10억 원 이하","colSpan":1,"rowSpan":1,"column":1},{"text":"15만원","colSpan":1,"rowSpan":1,"column":2}],[{"text":"10억 원 초과 ~","colSpan":1,"rowSpan":1,"column":1},{"text":"35만원","colSpan":1,"rowSpan":1,"column":2}]],"widths":[20.86,59.59,19.55],"lineStart":0,"lineCount":7}]},{"id":"c17-w01-b31","title":"TIP","body":"▪ 인지세 과세, 과세비대상 비교\n과세대상 / 과세비대상\n시중에 있는 볼펜에 학교명을 인쇄해서 구입 하는 경우(과업지시O) / 시중에 있는 볼펜을 구입하는 경우 (과업지시X)"},{"id":"c17-w01-b32","title":"4. 국민 주택 채권(주택도시기금법 제8조, 동법 시행령 8조) 징구","body":"구분 내용\n채권 징구 대상 국가, 지방자치단체 또는 주택도시기금법 제8조 제1항에 따른 공공기관과의 건설공사 도급계약\n채권 징구 기준 도급계약금액 5억원 이상\n채권 요율 계약금액의 1 / 1,000\n채권 단위 조정 1만 원 미만 금액 - 5천 원 이상 1만 원 미만 → 1만 원으로 올림 - 5천 원 미만 → 절사(반영하지 않음)\n유의사항 도급 계약 체결 당시 5억원 미만이었으나 설계 변경 등으로 5억원 이상 증액된 경우 변경사항 반영하여 징구","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"채권 징구 대상","colSpan":1,"rowSpan":1,"column":0},{"text":"국가, 지방자치단체 또는 주택도시기금법 제8조 제1항에 따른 공공기관과의 건설공사 도급계약","colSpan":1,"rowSpan":1,"column":1}],[{"text":"채권 징구 기준","colSpan":1,"rowSpan":1,"column":0},{"text":"도급계약금액 5억원 이상","colSpan":1,"rowSpan":1,"column":1}],[{"text":"채권 요율","colSpan":1,"rowSpan":1,"column":0},{"text":"계약금액의 1 / 1,000","colSpan":1,"rowSpan":1,"column":1}],[{"text":"채권 단위 조정","colSpan":1,"rowSpan":1,"column":0},{"text":"1만 원 미만 금액\n- 5천 원 이상 1만 원 미만 → 1만 원으로 올림\n- 5천 원 미만 → 절사(반영하지 않음)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"유의사항","colSpan":1,"rowSpan":1,"column":0},{"text":"도급 계약 체결 당시 5억원 미만이었으나 설계 변경 등으로 5억원 이상 증액된 경우 변경사항 반영하여 징구","colSpan":1,"rowSpan":1,"column":1}]],"widths":[20.75,79.25],"lineStart":0,"lineCount":6}]},{"id":"c17-w01-b33","title":"5. 계약 이행","body":"구분 내용\n물품 납품, 용역 이행, 공사 감독 ◦계약서, 설계서 등에 따라 감독 ◦필요 시 전문 기관에 감독 대행 가능\n계약 변경 ◦계약기간 및 내용 조정 시: 변경계약 합의서[서식 7] 작성 후 변경계약 - 변경 사유: 공사 중지, 기상악화로 인한 계약기간 연장 등 - 변경 시 추가 서류: 재착공계(공사예정공정표), 계약보증증권(기간 연장) ◦계약금액 조정 시: 변경계약 합의서[서식 7] 작성 후 변경계약 - 변경 사유: 물가변경, 설계변경, 기타 계약 내용 변경 - 변경시 추가 서류: 재착공계(공사공정예정표), 계약보증증권(기간 연장), 변경산출내역서 및 도면, 인지세, 국민주택채권(추가 징수분 발생 시)\n착수 시 징구 서류 목록(용역) 착수계, 산출내역서 등(2024. 계약실무편람 328p 참고)\n착공 시 징구 서류 목록(공사) 착공계, 산출내역서 등(2024. 계약실무편람 156p 참고)","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"물품 납품, 용역 이행, 공사 감독","colSpan":1,"rowSpan":1,"column":0},{"text":"◦계약서, 설계서 등에 따라 감독\n◦필요 시 전문 기관에 감독 대행 가능","colSpan":1,"rowSpan":1,"column":1}],[{"text":"계약 변경","colSpan":1,"rowSpan":1,"column":0},{"text":"◦계약기간 및 내용 조정 시: 변경계약 합의서[서식 7] 작성 후 변경계약\n- 변경 사유: 공사 중지, 기상악화로 인한 계약기간 연장 등\n- 변경 시 추가 서류: 재착공계(공사예정공정표), 계약보증증권(기간 연장)\n◦계약금액 조정 시: 변경계약 합의서[서식 7] 작성 후 변경계약\n- 변경 사유: 물가변경, 설계변경, 기타 계약 내용 변경\n- 변경시 추가 서류: 재착공계(공사공정예정표), 계약보증증권(기간 연장), 변경산출내역서 및 도면, 인지세, 국민주택채권(추가 징수분 발생 시)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"착수 시 징구\n서류 목록(용역)","colSpan":1,"rowSpan":1,"column":0},{"text":"착수계, 산출내역서 등(2024. 계약실무편람 328p 참고)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"착공 시 징구\n서류 목록(공사)","colSpan":1,"rowSpan":1,"column":0},{"text":"착공계, 산출내역서 등(2024. 계약실무편람 156p 참고)","colSpan":1,"rowSpan":1,"column":1}]],"widths":[20.75,79.25],"lineStart":0,"lineCount":5}]},{"id":"c17-w01-b34","title":"6. 선금 지급 및 선금 정산","body":"구분 내용\n선금의 목적 계약의 노임, 자재구입비, 보험료 등에 우선 충당할 목적\n선금 하한율 선금 지급 시 30% 이상 의무 지급 (30% 이하 신청 시 신청 금액 지급)\n선금 상한율 선금은 계약금액의 70% 초과 불가, 다만 필요시 재무건전성 고려하여 계약금액 범위 내 지급 가능\n선금 지급 절차 ◦계약상대자의 선금 신청 ◦선금 지급결정 내부기안 ◦선금 지급결정 알림 및 선금청구서류 징구 ◦계약상대자의 선금 청구서류 제출 ◦선금 지급 ◦(기성시) 매월 선금 정산\n선금 징구 서류 선금 신청서, 선금사용계획서 등(2024. 계약실무편람 123p ~ 139p 참고)\n선금의 정산 선금정산액 = 선금액 × [기성(기납)부분의대가상당액 ÷ 계약금액]","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"선금의 목적","colSpan":1,"rowSpan":1,"column":0},{"text":"계약의 노임, 자재구입비, 보험료 등에 우선 충당할 목적","colSpan":1,"rowSpan":1,"column":1}],[{"text":"선금 하한율","colSpan":1,"rowSpan":1,"column":0},{"text":"선금 지급 시 30% 이상 의무 지급 (30% 이하 신청 시 신청 금액 지급)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"선금 상한율","colSpan":1,"rowSpan":1,"column":0},{"text":"선금은 계약금액의 70% 초과 불가, 다만 필요시 재무건전성 고려하여 계약금액 범위 내 지급 가능","colSpan":1,"rowSpan":1,"column":1}],[{"text":"선금 지급 절차","colSpan":1,"rowSpan":1,"column":0},{"text":"◦계약상대자의 선금 신청\n◦선금 지급결정 내부기안\n◦선금 지급결정 알림 및 선금청구서류 징구\n◦계약상대자의 선금 청구서류 제출\n◦선금 지급\n◦(기성시) 매월 선금 정산","colSpan":1,"rowSpan":1,"column":1}],[{"text":"선금 징구 서류","colSpan":1,"rowSpan":1,"column":0},{"text":"선금 신청서, 선금사용계획서 등(2024. 계약실무편람 123p ~ 139p 참고)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"선금의 정산","colSpan":1,"rowSpan":1,"column":0},{"text":"선금정산액 = 선금액 × [기성(기납)부분의대가상당액 ÷ 계약금액]","colSpan":1,"rowSpan":1,"column":1}]],"widths":[21.01,78.99],"lineStart":0,"lineCount":7}]},{"id":"c17-w01-b35","title":"TIP","body":"▪ 선금 정산 예\n(단위: 천원)\n계약 금액 (A) / 선금 지급액 (B) / 월별 / 기성금 청구(E) / 기성율 (C / A) / 기성부분 대가상당액 (C) / 선금정산액 (D) / 실지급액 누적 (C-D) / 월별실 기성금 지급액\n120,000 / 84,000 / 1 / 10,000 / 8% / 10,000 / 7,000 / 3,000 / 3,000\n2 / 10,000 / 17% / 20,000 / 14,000 / 6,000 / 3,000\n3 / 10,000 / 25% / 30,000 / 21,000 / 9,000 / 3,000\n4 / 10,000 / 33% / 40,000 / 28,000 / 12,000 / 3,000\n5 / 10,000 / 42% / 50,000 / 35,000 / 15,000 / 3,000\n6 / 10,000 / 50% / 60,000 / 42,000 / 18,000 / 3,000\n7 / 10,000 / 58% / 70,000 / 49,000 / 21,000 / 3,000\n8 / 10,000 / 67% / 80,000 / 56,000 / 24,000 / 3,000\n9 / 10,000 / 75% / 90,000 / 63,000 / 27,000 / 3,000\n10 / 10,000 / 83% / 100,000 / 70,000 / 30,000 / 3,000\n11 / 10,000 / 92% / 110,000 / 77,000 / 33,000 / 3,000\n12 / 10,000 / 100% / 120,000 / 84,000 / 36,000 / 3,000\n※ 기성금 청구액: 업체에서 기성부분 청구 한 금액\n※ 기성부분대가 상당액: 이번달 기성금 청구액 + 전달 기성부분대가상당액\n※ 선금 정산액: 선금지급액 * 기성부분대가상당액 / 계약금액\n※ 실지급액 누적: 실지급액 누적 해당월 기성부분대가상당액 – 해당월 선금 정산액\n※ 월별실기성금 지급액: 해당월 실지급액 누적 – 전달 실지급액 누적"},{"id":"c17-w01-b36","title":"7. 검사 및 정산","body":"구분 내용\n검사·검수 시기 계약상대자로부터 이행 완료 통지 후 14일 이내 검사·검수 실시 ※ 단, 지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시(2025.12.31.까지)에 따라 한시적으로 7일 이내\n물품제조·용역 계약 정산 항목 국민건강보험료, 노인장기요양보험료, 국민연금보험료, 퇴직급여충당금 (원가계산서에 계상된 항목만 정산) ※ 사회보험: 납입 확인서 검토, 원가계산서에 계상된 금액보다 납입액이 부족 할 경우 감액, 과다 납입의 경우 증액 없음 ※ 퇴직급여충당금: 1년 이상 근로자 대상, 실제 퇴직금 지급액이 원가계산 금액보다 적을경우 감액, 과다 지급 시 증액 없음\n공사 계약 정산 항목 국민건강보험료, 산업안전보건관리비 등(2024. 계약실무편람 148p ~ 153p 참고)\n준공 시 징구 서류 목록(공사) 준공계, 준공사진 등(2024. 계약실무편람 158p 참고)\n완수 시 징구 서류 목록(용역) 완수계, 결과보고서 등(2024. 계약실무편람 330p 참고)","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"검사·검수 시기","colSpan":1,"rowSpan":1,"column":0},{"text":"계약상대자로부터 이행 완료 통지 후 14일 이내 검사·검수 실시\n※ 단, 지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시(2025.12.31.까지)에 따라 한시적으로 7일 이내","colSpan":1,"rowSpan":1,"column":1}],[{"text":"물품제조·용역 계약 정산 항목","colSpan":1,"rowSpan":1,"column":0},{"text":"국민건강보험료, 노인장기요양보험료, 국민연금보험료, 퇴직급여충당금 (원가계산서에 계상된 항목만 정산)\n※ 사회보험: 납입 확인서 검토, 원가계산서에 계상된 금액보다 납입액이 부족 할 경우 감액, 과다 납입의 경우 증액 없음\n※ 퇴직급여충당금: 1년 이상 근로자 대상, 실제 퇴직금 지급액이 원가계산 금액보다 적을경우 감액, 과다 지급 시 증액 없음","colSpan":1,"rowSpan":1,"column":1}],[{"text":"공사 계약 정산 항목","colSpan":1,"rowSpan":1,"column":0},{"text":"국민건강보험료, 산업안전보건관리비 등(2024. 계약실무편람 148p ~ 153p 참고)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"준공 시 징구 서류 목록(공사)","colSpan":1,"rowSpan":1,"column":0},{"text":"준공계, 준공사진 등(2024. 계약실무편람 158p 참고)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"완수 시 징구 서류 목록(용역)","colSpan":1,"rowSpan":1,"column":0},{"text":"완수계, 결과보고서 등(2024. 계약실무편람 330p 참고)","colSpan":1,"rowSpan":1,"column":1}]],"widths":[31.97,68.03],"lineStart":0,"lineCount":6}]},{"id":"c17-w01-b37","title":"TIP","body":"▪ 정산 제외 대상(지방자치단체 입찰 및 계약집행기준 제1장 제9절)\n순 / 정산 제외 대상\n1 / 계약기간이 1개월 미만인 계약(단, 계약기간이 1개월 미만의 계약이 1개월 이상으로 계약이행기간이 변경된 경우, 변경계약을 할 때 계약당사자가 협의하여 보험료 사후정산에 대한 내용 반영 가능)\n2 / 보험료 산정이 되지 않는 계약\n3 / 원가계산 기준에서 보험료 비목이 없는 경우\n4 / 원가계산 기준에서 인건비 등(또는 노임 단가)에 사후정산 대상 보험료가 포함되어 있고 별도로 보험료 정산이 안되는 경우\n5 / 그 외 계약담당자가 보험료 반영 및 정산 업무가 불가능하다고 판단하는 경우"},{"id":"c17-w01-b38","title":"8. 준공(납품,완수) 지체시: 지연 배상금 징수","body":"‣지연배상금 = 계약금액 * 지연배상금률 * 지연일수\n구분 지연배상금징수율\n공사 0.5 / 1000\n물품의 제조 · 구매 0.8 / 1000\n물품의 수리 · 가공 · 대여, 용역, 그 밖의 계약 1.3 / 1000\n운송 · 보관 및 양곡가공 2.5 / 1000","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"지연배상금징수율","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"공사","colSpan":1,"rowSpan":1,"column":0},{"text":"0.5 / 1000","colSpan":1,"rowSpan":1,"column":1}],[{"text":"물품의 제조 · 구매","colSpan":1,"rowSpan":1,"column":0},{"text":"0.8 / 1000","colSpan":1,"rowSpan":1,"column":1}],[{"text":"물품의 수리 · 가공 · 대여, 용역, 그 밖의 계약","colSpan":1,"rowSpan":1,"column":0},{"text":"1.3 / 1000","colSpan":1,"rowSpan":1,"column":1}],[{"text":"운송 · 보관 및 양곡가공","colSpan":1,"rowSpan":1,"column":0},{"text":"2.5 / 1000","colSpan":1,"rowSpan":1,"column":1}]],"widths":[52.2,47.8],"lineStart":1,"lineCount":5}]},{"id":"c17-w01-b39","title":"9. 하자보수(하자보수보증금 납부서[서식 8] or 하자보수보증서 징구)","body":"‣하자담보 시작일(지방계약법 시행령 제69조)\n- 공사계약: 전체 목적물 인수일과 준공검사완료일 중 먼저 도래한 날\n- 물품,용역계약: 전체 목적물 인수일과 검사를 완료날 중 먼저 도래한 날\n‣공종별 하자담보기간(지방계약법 시행규칙 제68조)\n공사별 세부공종별 책임기간 비고\n상․하수도 ①철근콘크리트·철골구조부 7년 건설산업 기본법\n②관로 매설·기기설치 3년\n조경 ①조경시설물 또는 조경식재 2년\n건축 ①대형 공공성 건축물의 기둥 및 내력벽 10년\n②대형공공성 건축물 중 기둥 및 내력벽 외의 구조상 주요부분과 ① 외의 건축물 중 구조상 주요부분 5년\n③건축물 중 ①·②와 전문공사를 제외한 기타 부분 1년\n전문공사 ①실내건축\n③미장·타일\n⑤도장\n⑦창호설치\n⑨판금\n⑭보일러 설치\n⑮⑫·⑭외의 건물 내 설비\n⑰보링\n⑱건축물조립(건축물의 기둥 및 내력벽의 조립을 제외하며, 이는 건축에 따름)\n②토공 2년\n공사별 세부공종별 책임기간 비고\n전문공사 ⑥석공사․조적 2년 건설산업 기본법\n⑩철물(교량,터널,철도,공항·삭도,항만·사방간척,도로,댐,상·하수도, 관개수로·매립, 부지정지, 조경, 발전·가스 및 산업설비, 기타토목공사에 해당하는 철골은 제외)\n⑫급배수,공동구,지하저수조,냉난방,환기,공기조환,자동제어,가스,배연설비\n⑯아스팔트 포장\n⑲온실설치\n④방수 3년\n⑧지붕\n⑪철근콘크리트(교량,터널,철도,공항·삭도,항만·사방간척,도로,댐,상·하수도, 관개수로·매립, 부지정지, 조경, 발전·가스 및 산업설비, 기타토목공사에 해당하는 철근콘크리트는 제외) 및 콘크리트 포장\n⑬승강기 및 인양기기 설비\n전기 배전설비 철탑공사 3년 전기 공사업법\n배전설비 철탑공사 외의 배전설비공사 2년\n그 밖의 전기설비공사 1년\n통신 그 밖의 통신공사 1년 정보통신 공사업법\n소방 피난기구, 유도등, 유도표지, 비상경보설비, 비상조명등, 비상방송설비 및 무선통신보조설비 2년 소방시설 공사업법\n자동식소화기, 옥내소화전설비, 스프링클러설비, 소방시설공사업법 간이스프링클러설비, 물분무등소화설비, 옥외소화전설비, 자동화재탐지설비, 상수도소화용수설비 및 소화활동설비(무선통신보조설비는 제외) 3년\n물품 물품 제조 및 구매 지방계약법상 규정되어 있지 않음 (물품 성질 및 실정에 맞게 기간 설정)\n용역 용역\n‣공종별 하자보수보증금율\n공종구분 하자보수 보증금률\n철도, 댐, 터널, 철강교설치, 발전설비, 교량, 상하수도구조물 등 중요 구조물 공사 및 조경공사 5%\n공항, 항만, 삭도설치, 방파제, 사방, 간척 등 공사 4%\n관개수로, 도로(포장공사를 포함한다), 매립, 상하수도관로, 하천, 일반건축 등 공사 3%\n제1호부터 제3호까지의 공사 외의 공사 2%\n물품의 제조 3%\n수리, 가공, 구매, 용역 2%\n‣하자검사(지방자치단체 입찰 및 계약집행기준 제9장 11절)\n- 하자담보 책임기간 중 연 2회 이상 정기검사\n- 하자담보 책임기간이 만료되기 14일 전부터 만료일까지의 기간 중에 최종검사\n※ 하자검사조서[서식 10], 하자보수관리부[서식 11] 작성 비치\n- 하자보수의 이행\n※ 하자보수착공신고서 제출: 하자보수 통보받은 7일 이내(설계서 첨부 및 공사이행 소요기간 명시)\n- 시급을 요하는 경우에는 즉시 하자공사 착공\n※ 하자검사조서 생략 가능: 계약금액 3천만 원 이하 공사(단, 하자보수보증급 지급각서[서식 9]는 반드시 징구)","tables":[{"headers":[{"text":"공사별","colSpan":1,"rowSpan":1,"column":0},{"text":"세부공종별","colSpan":1,"rowSpan":1,"column":1},{"text":"책임기간","colSpan":1,"rowSpan":1,"column":2},{"text":"비고","colSpan":1,"rowSpan":1,"column":3}],"rows":[[{"text":"상․하수도","colSpan":1,"rowSpan":2,"column":0},{"text":"①철근콘크리트·철골구조부","colSpan":1,"rowSpan":1,"column":1},{"text":"7년","colSpan":1,"rowSpan":1,"column":2},{"text":"건설산업\n기본법","colSpan":1,"rowSpan":16,"column":3}],[{"text":"②관로 매설·기기설치","colSpan":1,"rowSpan":1,"column":1},{"text":"3년","colSpan":1,"rowSpan":1,"column":2}],[{"text":"조경","colSpan":1,"rowSpan":1,"column":0},{"text":"①조경시설물 또는 조경식재","colSpan":1,"rowSpan":1,"column":1},{"text":"2년","colSpan":1,"rowSpan":1,"column":2}],[{"text":"건축","colSpan":1,"rowSpan":3,"column":0},{"text":"①대형 공공성 건축물의 기둥 및 내력벽","colSpan":1,"rowSpan":1,"column":1},{"text":"10년","colSpan":1,"rowSpan":1,"column":2}],[{"text":"②대형공공성 건축물 중 기둥 및 내력벽 외의 구조상 주요부분과 ① 외의 건축물 중 구조상 주요부분","colSpan":1,"rowSpan":1,"column":1},{"text":"5년","colSpan":1,"rowSpan":1,"column":2}],[{"text":"③건축물 중 ①·②와 전문공사를 제외한 기타 부분","colSpan":1,"rowSpan":1,"column":1},{"text":"1년","colSpan":1,"rowSpan":10,"column":2}],[{"text":"전문공사","colSpan":1,"rowSpan":10,"column":0},{"text":"①실내건축","colSpan":1,"rowSpan":1,"column":1}],[{"text":"③미장·타일","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑤도장","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑦창호설치","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑨판금","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑭보일러 설치","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑮⑫·⑭외의 건물 내 설비","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑰보링","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑱건축물조립(건축물의 기둥 및 내력벽의 조립을 제외하며, 이는 건축에 따름)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"②토공","colSpan":1,"rowSpan":1,"column":1},{"text":"2년","colSpan":1,"rowSpan":1,"column":2}]],"widths":[12.24,56.46,15.32,15.98],"lineStart":4,"lineCount":17},{"headers":[{"text":"공사별","colSpan":1,"rowSpan":1,"column":0},{"text":"세부공종별","colSpan":1,"rowSpan":1,"column":1},{"text":"책임기간","colSpan":1,"rowSpan":1,"column":2},{"text":"비고","colSpan":1,"rowSpan":1,"column":3}],"rows":[[{"text":"전문공사","colSpan":1,"rowSpan":9,"column":0},{"text":"⑥석공사․조적","colSpan":1,"rowSpan":1,"column":1},{"text":"2년","colSpan":1,"rowSpan":5,"column":2},{"text":"건설산업\n기본법","colSpan":1,"rowSpan":9,"column":3}],[{"text":"⑩철물(교량,터널,철도,공항·삭도,항만·사방간척,도로,댐,상·하수도, 관개수로·매립, 부지정지, 조경, 발전·가스 및 산업설비, 기타토목공사에 해당하는 철골은 제외)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑫급배수,공동구,지하저수조,냉난방,환기,공기조환,자동제어,가스,배연설비","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑯아스팔트 포장","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑲온실설치","colSpan":1,"rowSpan":1,"column":1}],[{"text":"④방수","colSpan":1,"rowSpan":1,"column":1},{"text":"3년","colSpan":1,"rowSpan":4,"column":2}],[{"text":"⑧지붕","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑪철근콘크리트(교량,터널,철도,공항·삭도,항만·사방간척,도로,댐,상·하수도, 관개수로·매립, 부지정지, 조경, 발전·가스 및 산업설비, 기타토목공사에 해당하는 철근콘크리트는 제외) 및 콘크리트 포장","colSpan":1,"rowSpan":1,"column":1}],[{"text":"⑬승강기 및 인양기기 설비","colSpan":1,"rowSpan":1,"column":1}],[{"text":"전기","colSpan":1,"rowSpan":3,"column":0},{"text":"배전설비 철탑공사","colSpan":1,"rowSpan":1,"column":1},{"text":"3년","colSpan":1,"rowSpan":1,"column":2},{"text":"전기\n공사업법","colSpan":1,"rowSpan":3,"column":3}],[{"text":"배전설비 철탑공사 외의 배전설비공사","colSpan":1,"rowSpan":1,"column":1},{"text":"2년","colSpan":1,"rowSpan":1,"column":2}],[{"text":"그 밖의 전기설비공사","colSpan":1,"rowSpan":1,"column":1},{"text":"1년","colSpan":1,"rowSpan":1,"column":2}],[{"text":"통신","colSpan":1,"rowSpan":1,"column":0},{"text":"그 밖의 통신공사","colSpan":1,"rowSpan":1,"column":1},{"text":"1년","colSpan":1,"rowSpan":1,"column":2},{"text":"정보통신\n공사업법","colSpan":1,"rowSpan":1,"column":3}],[{"text":"소방","colSpan":1,"rowSpan":2,"column":0},{"text":"피난기구, 유도등, 유도표지, 비상경보설비,\n비상조명등, 비상방송설비 및 무선통신보조설비","colSpan":1,"rowSpan":1,"column":1},{"text":"2년","colSpan":1,"rowSpan":1,"column":2},{"text":"소방시설\n공사업법","colSpan":1,"rowSpan":2,"column":3}],[{"text":"자동식소화기, 옥내소화전설비, 스프링클러설비, 소방시설공사업법\n간이스프링클러설비, 물분무등소화설비,\n옥외소화전설비, 자동화재탐지설비,\n상수도소화용수설비 및\n소화활동설비(무선통신보조설비는 제외)","colSpan":1,"rowSpan":1,"column":1},{"text":"3년","colSpan":1,"rowSpan":1,"column":2}],[{"text":"물품","colSpan":1,"rowSpan":1,"column":0},{"text":"물품 제조 및 구매","colSpan":1,"rowSpan":1,"column":1},{"text":"지방계약법상 규정되어 있지 않음\n(물품 성질 및 실정에 맞게 기간 설정)","colSpan":2,"rowSpan":2,"column":2}],[{"text":"용역","colSpan":1,"rowSpan":1,"column":0},{"text":"용역","colSpan":1,"rowSpan":1,"column":1}]],"widths":[12.24,57.08,14.7,15.98],"lineStart":21,"lineCount":18},{"headers":[{"text":"공종구분","colSpan":1,"rowSpan":1,"column":0},{"text":"하자보수\n보증금률","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"철도, 댐, 터널, 철강교설치, 발전설비, 교량, 상하수도구조물 등 중요 구조물 공사 및 조경공사","colSpan":1,"rowSpan":1,"column":0},{"text":"5%","colSpan":1,"rowSpan":1,"column":1}],[{"text":"공항, 항만, 삭도설치, 방파제, 사방, 간척 등 공사","colSpan":1,"rowSpan":1,"column":0},{"text":"4%","colSpan":1,"rowSpan":1,"column":1}],[{"text":"관개수로, 도로(포장공사를 포함한다), 매립, 상하수도관로, 하천, 일반건축 등 공사","colSpan":1,"rowSpan":1,"column":0},{"text":"3%","colSpan":1,"rowSpan":1,"column":1}],[{"text":"제1호부터 제3호까지의 공사 외의 공사","colSpan":1,"rowSpan":1,"column":0},{"text":"2%","colSpan":1,"rowSpan":1,"column":1}],[{"text":"물품의 제조","colSpan":1,"rowSpan":1,"column":0},{"text":"3%","colSpan":1,"rowSpan":1,"column":1}],[{"text":"수리, 가공, 구매, 용역","colSpan":1,"rowSpan":1,"column":0},{"text":"2%","colSpan":1,"rowSpan":1,"column":1}]],"widths":[88.56,11.44],"lineStart":40,"lineCount":7}]},{"id":"c17-w01-b40","title":"10. 청구 및 대가지급","body":"구분 내용\n대가 지급 기한 청구 후 5일 이내 지급 (공휴일 및 토요일 제외) ※ 지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시(2025.12.31.까지)에 따라 3일 이내 지급\n일반 대가 징구 서류 ◦세금계산서 ◦납세증명서 (국세 및 지방세) ※ [「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제25조제1항 각 호(같은 항 제7호가목은 제외한다)에 해당하는 수의계약에 따라 대금을 지급받는 경우(국세징수법 시행령 제91조, 지방세징수법 시행령 제5조) 납세증명서 징구 생략 가능] ◦4대보험 완납증명서 ※ 각 보험 미가입자는 미가입된 보험에 대한 보험료 납부증명 의무가 없으며 4대 사회보험료 완납증명서 상 체크박스()로 가입여부 확인 가능(4대보험 중 일부 가입된 경우), 4대보험 전체를 가입하지 않은 사업장의 경우 건강보험공단 지사에 ‘4대 사회보험료 납부여부 정보제공 동의서[서식 12]’를 제출하면, 실제 납세대상자가 없음을 확인하는 공문을 팩스로 받아 4대보험 완납증명서를 갈음함. ◦하자보증서 또는 하자보수보증금\n공사 대가 징구 서류 대금청구서, 하자보증서 등(2024. 계약실무편람 159p 참고)","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"대가 지급 기한","colSpan":1,"rowSpan":1,"column":0},{"text":"청구 후 5일 이내 지급 (공휴일 및 토요일 제외)\n※ 지방자치단체를 당사자로하는 계약에 관한 법률 시행령의 수의계약 등 한시적 특례 적용기간에 관한 고시(2025.12.31.까지)에 따라 3일 이내 지급","colSpan":1,"rowSpan":1,"column":1}],[{"text":"일반 대가\n징구 서류","colSpan":1,"rowSpan":1,"column":0},{"text":"◦세금계산서\n◦납세증명서 (국세 및 지방세)\n※ [「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제25조제1항 각 호(같은 항 제7호가목은 제외한다)에 해당하는 수의계약에 따라 대금을 지급받는 경우(국세징수법 시행령 제91조, 지방세징수법 시행령 제5조) 납세증명서 징구 생략 가능]\n◦4대보험 완납증명서\n※ 각 보험 미가입자는 미가입된 보험에 대한 보험료 납부증명 의무가 없으며 4대 사회보험료 완납증명서 상 체크박스()로 가입여부 확인 가능(4대보험 중 일부 가입된 경우), 4대보험 전체를 가입하지 않은 사업장의 경우 건강보험공단 지사에 ‘4대 사회보험료 납부여부 정보제공 동의서[서식 12]’를 제출하면, 실제 납세대상자가 없음을 확인하는 공문을 팩스로 받아 4대보험 완납증명서를 갈음함.\n◦하자보증서 또는 하자보수보증금","colSpan":1,"rowSpan":1,"column":1}],[{"text":"공사 대가\n징구 서류","colSpan":1,"rowSpan":1,"column":0},{"text":"대금청구서, 하자보증서 등(2024. 계약실무편람 159p 참고)","colSpan":1,"rowSpan":1,"column":1}]],"widths":[18.99,81.01],"lineStart":0,"lineCount":4}]}],"flowGroups":[]},{"id":"c17-w02","number":2,"title":"계약 심사","formIds":[],"faqCategories":[],"contentBlocks":[{"id":"c17-w02-b1","title":"세부내용 계약심사","body":""},{"id":"c17-w02-b2","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」\n• 「전북특별자치도교육청 계약심사업무 처리 규칙」"},{"id":"c17-w02-b3","title":"1. 계약심사 개념 및 목적","body":"구분 내용\n개념 「지방재정법」 제3조에 따라 지방자치단체 재정을 건전하고 효율적으로 운영하기 위해 입찰·계약의 기초금액, 예정가격, 설계변경 증감금액의 적정성을 심사·검토하는 제도\n목적 ◦예정가격 결정 시 원가 계산의 전문성을 활용하여 과다·과소 산정 등 예산 낭비 요소를 사전 제거 ◦계약 목적, 성질, 규모, 지역 특수성을 반영해 품질 향상 도모 ◦사후감사로 시정이 어려운 주요 사업의 행정적 낭비와 시행착오를 사전에 예방하여 건전하고 효율적인 재정 운영","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"개념","colSpan":1,"rowSpan":1,"column":0},{"text":"「지방재정법」 제3조에 따라 지방자치단체 재정을 건전하고 효율적으로 운영하기 위해 입찰·계약의 기초금액, 예정가격, 설계변경 증감금액의 적정성을 심사·검토하는 제도","colSpan":1,"rowSpan":1,"column":1}],[{"text":"목적","colSpan":1,"rowSpan":1,"column":0},{"text":"◦예정가격 결정 시 원가 계산의 전문성을 활용하여 과다·과소 산정 등 예산 낭비 요소를 사전 제거\n◦계약 목적, 성질, 규모, 지역 특수성을 반영해 품질 향상 도모\n◦사후감사로 시정이 어려운 주요 사업의 행정적 낭비와 시행착오를 사전에 예방하여 건전하고 효율적인 재정 운영","colSpan":1,"rowSpan":1,"column":1}]],"widths":[8.17,91.83],"lineStart":0,"lineCount":3}]},{"id":"c17-w02-b4","title":"2. 계약심사 흐름도","body":"설 계 (원가 계산) ⇒ 원가 산정의 적정성 심사 ⇒ 입 찰 ⇒ 계 약 ⇒ (설계변경 시) 설계변경 심사\n발주부서 심사부서 발주부서 발주부서 심사부서\n▪ 계약심사 의뢰 심사부서 ▪ 계약심사 (원가계산 등) ▪ 심사결과 작성\n발주부서 ▪ 집행내역 작성 (발주금액 산정) ▪ 발주금액 재산정 ▪ 심사결과 송부 ▪ 계약 의뢰 계약부서 ▪ 계약 체결","tables":[{"headers":[{"text":"설 계\n(원가 계산)","colSpan":1,"rowSpan":1,"column":0},{"text":"⇒","colSpan":1,"rowSpan":2,"column":1},{"text":"원가 산정의\n적정성 심사","colSpan":1,"rowSpan":1,"column":2},{"text":"⇒","colSpan":1,"rowSpan":2,"column":3},{"text":"입 찰","colSpan":1,"rowSpan":1,"column":4},{"text":"⇒","colSpan":1,"rowSpan":2,"column":5},{"text":"계 약","colSpan":1,"rowSpan":1,"column":6},{"text":"⇒","colSpan":1,"rowSpan":2,"column":7},{"text":"(설계변경 시)\n설계변경 심사","colSpan":1,"rowSpan":1,"column":8}],"rows":[[{"text":"발주부서","colSpan":1,"rowSpan":1,"column":0},{"text":"심사부서","colSpan":1,"rowSpan":1,"column":2},{"text":"발주부서","colSpan":1,"rowSpan":1,"column":4},{"text":"발주부서","colSpan":1,"rowSpan":1,"column":6},{"text":"심사부서","colSpan":1,"rowSpan":1,"column":8}]],"widths":[16.72,4.84,18.51,4.84,11.97,4.84,11.38,4.84,22.07],"lineStart":0,"lineCount":2},{"headers":[{"text":"▪ 계약심사 의뢰","colSpan":1,"rowSpan":1},{"text":"심사부서\n▪ 계약심사 (원가계산 등) ▪ 심사결과 작성","colSpan":1,"rowSpan":1},{"text":"","colSpan":1,"rowSpan":1}],"rows":[[{"text":"발주부서\n▪ 집행내역 작성 (발주금액 산정) ▪ 발주금액 재산정","colSpan":1,"rowSpan":1},{"text":"▪ 심사결과 송부\n▪ 계약 의뢰","colSpan":1,"rowSpan":1},{"text":"계약부서\n▪ 계약 체결","colSpan":1,"rowSpan":1}]],"lineStart":2,"lineCount":2}]},{"id":"c17-w02-b5","title":"3. 계약심사 대상","body":"구분 심사 기준 금액 및 대상 비고\n원가심사 대상 ◦공사: 추정금액 5억 원 이상 (종합공사가 아닌 경우 3억 원 이상) ◦용역: 추정금액 7천만 원 이상 ◦물품: 추정금액 2천만 원 이상 사립학교 공사계약은 계약심사 제외하고 이를 일상감사로 대체\n설계변경심사 대상 계약금액이 10% 이상 증가하는 경우","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"심사 기준 금액 및 대상","colSpan":1,"rowSpan":1,"column":1},{"text":"비고","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"원가심사 대상","colSpan":1,"rowSpan":1,"column":0},{"text":"◦공사: 추정금액 5억 원 이상\n(종합공사가 아닌 경우 3억 원 이상)\n◦용역: 추정금액 7천만 원 이상\n◦물품: 추정금액 2천만 원 이상","colSpan":1,"rowSpan":1,"column":1},{"text":"사립학교 공사계약은 계약심사 제외하고 이를 일상감사로 대체","colSpan":1,"rowSpan":1,"column":2}],[{"text":"설계변경심사 대상","colSpan":1,"rowSpan":1,"column":0},{"text":"계약금액이 10% 이상 증가하는 경우","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}]],"widths":[20.48,40.68,38.84],"lineStart":0,"lineCount":3}]},{"id":"c17-w02-b6","title":"4. 계약 심사 제외 대상","body":"분야 대상사업 제외사유\n공사 물가변동에 의한 설계변경 대상 사업 ◦물가변동에 따른 설계변경 금액 산정 시 행정기관, 한국은행 등이 조사 발표한 지수를 활용 산출하여 심사 실익 없음 ◦「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제73조(물가 변동으로 인한 계약금액의 조정)\n사회기반시설에 대한 민간 투자사업 ◦주무관청의 고시사업에 대하여 제안서 평가 및 협상에 의한 사업추진 방식으로 심사 실익 없음 ◦「사회기반시설에 대한 민간투자법」 제9조(민간부문의 사업제안 등)\n조달청 공사원가 사전검토 대상 사업 ◦조달청에서 사전 원가계산 하는 사업으로 심사 실익 없음 ◦「조달사업에 관한 법률 시행령」 제28조(지방자치단체 공사원가의 사전검토)\n용역 설계공모방식에 따른 발주 용역 ◦예산편성지침에 의하여 산출하고, 평가위원의 제안서 평가에 따른 사업추진 방식으로 심사 실익 없음 ◦「건축서비스산업 진흥법」 제21조(설계공모의 활성화 등)\n행사 용역 ◦공연․만찬․홍보 등 행사 용역은 출연자(초청가수 등)에 따라 가격이 상이하고, 홍보방법(TV, 신문, 라디오,인터넷 등) 및 횟수 등에 따라 가격이 결정되어 심사 곤란 ◦「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호\n디자인 개발 ◦창작 및 예술성을 기초로 하고 있어 계량화할 수 있는 관련 규정이 미비하여 적정가격 심사 곤란 ◦「지방자치단체 입찰 및 계약 집행기준」 제3장 계약심사 운영요령\n통학버스 임차 용역 ◦<통학버스 임차용역 원가계산 프로그램>에 의하여 원가를 산정하는 경우 심사 실익 없음 ◦2024년도 전세 통학버스 원가 산정 검토 및 표준원가구성(행정과, 2023. 10.) ◦계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호\n소프트웨어사업 과업 심의 대상 사업 ◦소프트웨어사업 과업심의위원회에서 원가계산 등 소요비용을 심의하므로 심사의 실익이 없음 ◦「소프트웨어 진흥법」 제50조(소프트웨어사업 과업심의 위원회) 및 「공공소프트웨어사업 과업심의 가이드」\n물품 공연, 예술품 및 전시모형 등제작 구매 ◦연출자의 구상이 반영되어야 하는 예술창작품 성격을 갖고 있어 적정가격 심사 곤란 ◦「지방자치단체 입찰 및 계약집행기준」 제3장 계약심사 운영요령\n조달청 제3자 단가계약 또는 다수공급자계약 2단계경쟁 대상 물품 구매 ◦조달청에서 제3자단가계약 또는 다수공급자계약 2단계경쟁 대상 물품 구매로 심사 불가 ◦「조달사업에 관한 법률 시행령」 제12조(제3자를 위한 단가 계약) 및 제13조(다수공급자계약) 제3항\n분야 대상사업 제외사유\n물품 방송‧장비 구축운영 지침에 의한 심의 대상 물품 구매 ◦발주기관의 제안 요청서 심의위원회에서 추정금액을 결정하는 사항으로 심사 실익 없음 ◦「공공기관 방송장비 구축‧운영 지침」(과학기술정보통신부 고시 제2024-27호, 2024. 7. 9.)\n유류(가스) 구매 ◦유류(가스)는 한국석유공사가 매주 변동 가격을 고시하여 심사 곤란 ◦「지방자치단체 입찰 및 계약 집행기준」 제3장 계약심사 운영요령\n상품권,종량제봉투 등 규격제품 구매 ◦지정 규격제품(완제품)에 대한 구입으로 심사 실익 없음 ◦「지방자치단체 입찰 및 계약 집행기준」 제3장 계약심사 운영요령\n농‧축‧수산물등 (급식 식재료 포함) 구매 ◦물품 특성 상 구매시기, 생산지, 신선도, 질적 차이 등에 따라 가격이 결정되어 심사 곤란 ※ 급식 식재료, 위탁급식 포함 ◦「지방자치단체 입찰 및 계약 집행기준」 제3장 계약심사 운영요령 ◦ 「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호\n동‧식물(화환 등 포함) 구매 ◦동․식물의 경우 건강이나 상태, 희소성 등에 따라 가격이 달라지므로 기준가격 설정 곤란 ◦「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제7조 및 제10호\n도서 구매 ◦도서 입찰 시 기초금액의 정가 입찰을 권고하고 있어 적정 금액 심사 곤란 ◦「출판문화산업 진흥법」 제22조(간행물 정가 표시 및 판매)\n공사 용역 물품 기타 계약심사의 실익이 없는 사업 ◦위 외 별도 부서(기관, 위원회 등)에서 원가심사에 준하는 규격 및 경비 등을 심사하거나, 지침‧고시 등에 의해 단가가 정해진 경우 심사의 실익이 없음 ◦「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호\n협상에 의한 계약체결 대상 사업 ◦협상에 의한 계약체결 대상 사업으로 제안서 평가 위원회에서 심사하여 적정금액 심사 곤란 ◦「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제43조(협상에 의한 계약체결)\n조달청의뢰 계약체결 대상 사업 ◦예산편성지침에 의하여 산출하고, 조달청에서 계약하는 사업으로 심사 실익 없음 ◦「조달사업에 관한 법률 시행령」 제27조(조달업무의 지원 및 대행)\n기타 규칙 제4조 제10호에 의한 사업 ◦사업의 성격이나 취지에 비추어 심사가 불필요하다고 전북특별자치도교육감이 인정하는 사업 ◦「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호","tables":[{"headers":[{"text":"분야","colSpan":1,"rowSpan":1,"column":0},{"text":"대상사업","colSpan":1,"rowSpan":1,"column":1},{"text":"제외사유","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"공사","colSpan":1,"rowSpan":3,"column":0},{"text":"물가변동에 의한 설계변경 대상 사업","colSpan":1,"rowSpan":1,"column":1},{"text":"◦물가변동에 따른 설계변경 금액 산정 시 행정기관, 한국은행 등이 조사 발표한 지수를 활용 산출하여 심사 실익 없음\n◦「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제73조(물가 변동으로 인한 계약금액의 조정)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"사회기반시설에 대한\n민간 투자사업","colSpan":1,"rowSpan":1,"column":1},{"text":"◦주무관청의 고시사업에 대하여 제안서 평가 및 협상에 의한 사업추진 방식으로 심사 실익 없음\n◦「사회기반시설에 대한 민간투자법」 제9조(민간부문의 사업제안 등)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"조달청 공사원가 사전검토 대상 사업","colSpan":1,"rowSpan":1,"column":1},{"text":"◦조달청에서 사전 원가계산 하는 사업으로 심사 실익 없음\n◦「조달사업에 관한 법률 시행령」 제28조(지방자치단체 공사원가의 사전검토)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"용역","colSpan":1,"rowSpan":5,"column":0},{"text":"설계공모방식에 따른 발주 용역","colSpan":1,"rowSpan":1,"column":1},{"text":"◦예산편성지침에 의하여 산출하고, 평가위원의 제안서 평가에 따른 사업추진 방식으로 심사 실익 없음\n◦「건축서비스산업 진흥법」 제21조(설계공모의 활성화 등)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"행사 용역","colSpan":1,"rowSpan":1,"column":1},{"text":"◦공연․만찬․홍보 등 행사 용역은 출연자(초청가수 등)에 따라 가격이 상이하고, 홍보방법(TV, 신문, 라디오,인터넷 등) 및 횟수 등에 따라 가격이 결정되어 심사 곤란\n◦「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호","colSpan":1,"rowSpan":1,"column":2}],[{"text":"디자인 개발","colSpan":1,"rowSpan":1,"column":1},{"text":"◦창작 및 예술성을 기초로 하고 있어 계량화할 수 있는 관련 규정이 미비하여 적정가격 심사 곤란\n◦「지방자치단체 입찰 및 계약 집행기준」 제3장 계약심사 운영요령","colSpan":1,"rowSpan":1,"column":2}],[{"text":"통학버스 임차 용역","colSpan":1,"rowSpan":1,"column":1},{"text":"◦<통학버스 임차용역 원가계산 프로그램>에 의하여 원가를 산정하는 경우 심사 실익 없음\n◦2024년도 전세 통학버스 원가 산정 검토 및 표준원가구성(행정과, 2023. 10.)\n◦계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호","colSpan":1,"rowSpan":1,"column":2}],[{"text":"소프트웨어사업\n과업 심의 대상 사업","colSpan":1,"rowSpan":1,"column":1},{"text":"◦소프트웨어사업 과업심의위원회에서 원가계산 등 소요비용을 심의하므로 심사의 실익이 없음\n◦「소프트웨어 진흥법」 제50조(소프트웨어사업 과업심의 위원회) 및 「공공소프트웨어사업 과업심의 가이드」","colSpan":1,"rowSpan":1,"column":2}],[{"text":"물품","colSpan":1,"rowSpan":2,"column":0},{"text":"공연, 예술품 및 전시모형 등제작 구매","colSpan":1,"rowSpan":1,"column":1},{"text":"◦연출자의 구상이 반영되어야 하는 예술창작품 성격을 갖고 있어 적정가격 심사 곤란\n◦「지방자치단체 입찰 및 계약집행기준」 제3장 계약심사 운영요령","colSpan":1,"rowSpan":1,"column":2}],[{"text":"조달청 제3자 단가계약 또는 다수공급자계약 2단계경쟁 대상 물품 구매","colSpan":1,"rowSpan":1,"column":1},{"text":"◦조달청에서 제3자단가계약 또는 다수공급자계약 2단계경쟁 대상 물품 구매로 심사 불가\n◦「조달사업에 관한 법률 시행령」 제12조(제3자를 위한 단가 계약) 및 제13조(다수공급자계약) 제3항","colSpan":1,"rowSpan":1,"column":2}]],"widths":[7.44,18.53,74.03],"lineStart":0,"lineCount":11},{"headers":[{"text":"분야","colSpan":1,"rowSpan":1,"column":0},{"text":"대상사업","colSpan":1,"rowSpan":1,"column":1},{"text":"제외사유","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"물품","colSpan":1,"rowSpan":6,"column":0},{"text":"방송‧장비 구축운영 지침에 의한 심의 대상 물품 구매","colSpan":1,"rowSpan":1,"column":1},{"text":"◦발주기관의 제안 요청서 심의위원회에서 추정금액을 결정하는 사항으로 심사 실익 없음\n◦「공공기관 방송장비 구축‧운영 지침」(과학기술정보통신부 고시 제2024-27호, 2024. 7. 9.)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"유류(가스) 구매","colSpan":1,"rowSpan":1,"column":1},{"text":"◦유류(가스)는 한국석유공사가 매주 변동 가격을 고시하여 심사 곤란\n◦「지방자치단체 입찰 및 계약 집행기준」 제3장 계약심사 운영요령","colSpan":1,"rowSpan":1,"column":2}],[{"text":"상품권,종량제봉투\n등 규격제품 구매","colSpan":1,"rowSpan":1,"column":1},{"text":"◦지정 규격제품(완제품)에 대한 구입으로 심사 실익 없음\n◦「지방자치단체 입찰 및 계약 집행기준」 제3장 계약심사 운영요령","colSpan":1,"rowSpan":1,"column":2}],[{"text":"농‧축‧수산물등\n(급식 식재료 포함) 구매","colSpan":1,"rowSpan":1,"column":1},{"text":"◦물품 특성 상 구매시기, 생산지, 신선도, 질적 차이 등에 따라 가격이 결정되어 심사 곤란\n※ 급식 식재료, 위탁급식 포함\n◦「지방자치단체 입찰 및 계약 집행기준」 제3장 계약심사 운영요령\n◦ 「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호","colSpan":1,"rowSpan":1,"column":2}],[{"text":"동‧식물(화환 등 포함) 구매","colSpan":1,"rowSpan":1,"column":1},{"text":"◦동․식물의 경우 건강이나 상태, 희소성 등에 따라 가격이 달라지므로 기준가격 설정 곤란\n◦「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제7조 및 제10호","colSpan":1,"rowSpan":1,"column":2}],[{"text":"도서 구매","colSpan":1,"rowSpan":1,"column":1},{"text":"◦도서 입찰 시 기초금액의 정가 입찰을 권고하고 있어 적정 금액 심사 곤란\n◦「출판문화산업 진흥법」 제22조(간행물 정가 표시 및 판매)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"공사\n용역\n물품","colSpan":1,"rowSpan":3,"column":0},{"text":"기타 계약심사의 실익이 없는 사업","colSpan":1,"rowSpan":1,"column":1},{"text":"◦위 외 별도 부서(기관, 위원회 등)에서 원가심사에 준하는 규격 및 경비 등을 심사하거나, 지침‧고시 등에 의해 단가가 정해진 경우 심사의 실익이 없음\n◦「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호","colSpan":1,"rowSpan":1,"column":2}],[{"text":"협상에 의한 계약체결 대상 사업","colSpan":1,"rowSpan":1,"column":1},{"text":"◦협상에 의한 계약체결 대상 사업으로 제안서 평가 위원회에서 심사하여 적정금액 심사 곤란\n◦「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제43조(협상에 의한 계약체결)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"조달청의뢰 계약체결 대상\n사업","colSpan":1,"rowSpan":1,"column":1},{"text":"◦예산편성지침에 의하여 산출하고, 조달청에서 계약하는 사업으로 심사 실익 없음\n◦「조달사업에 관한 법률 시행령」 제27조(조달업무의 지원 및 대행)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"기타","colSpan":1,"rowSpan":1,"column":0},{"text":"규칙 제4조\n제10호에 의한 사업","colSpan":1,"rowSpan":1,"column":1},{"text":"◦사업의 성격이나 취지에 비추어 심사가 불필요하다고 전북특별자치도교육감이 인정하는 사업\n◦「계약심사업무 처리 규칙」 제4조(계약심사 제외사업) 제10호","colSpan":1,"rowSpan":1,"column":2}]],"widths":[7.44,18.53,74.03],"lineStart":11,"lineCount":11}]},{"id":"c17-w02-b7","title":"5. 분야별 계약심사(원가) 서류 제출 목록","body":"‣공사\n구분 제출 서류 목록\n필수 ◦공사계약 심사 요청서 [서식 13] ◦설계도면, 공사설계 설명서(공사 시방서), 현장설명서, 과업내용서, 관급자재 현황 ◦설계 내역서 (비목별 기초계산서, 수량산출서, 노무비·기계경비 산출서, 일위대가표, 단가산출서, 견적서 등)\n기타 필요 ◦소프트웨어 자료 (엑셀 내역 파일, Auto CAD 도면 등) ※ 엑셀 파일은 연계 공종 간 링크된 형식으로 제출 ◦품셈과 표준시장단가를 동시에 적용하는 경우 품셈을 적용한 내역서와 표준시장단가를 적용한 내역서 ◦신기술·신공법 관련 자료 ◦방침서, 계획서, 기술 심사 조건, 내진 구조 성능 확인서 등 기타 심사에 필요한 자료\n‣용역\n구분 제출 서류 목록\n필수 ◦(기술, 일반, 학술) 용역 계약 심사 요청서 [서식 14] ◦과업 내용서 ◦설계 내역서 (비목별 기초계산서, 수량산출서, 노무비 산출근거, 일위대가표 및단가산출서, 견적서 등)\n기타 필요 ◦소프트웨어 참고자료 (엑셀 내역 파일 등) ◦방침서 (내부규정 문서) ◦계획서 등 기타 심사에 필요한 서류\n‣물품\n구분 제출 서류 목록\n필수 ◦물품 계약 심사요청서 서식 15 ◦산출 기초 조사서 ◦규격서 및 설명서 (사양서 등) ◦설계 내역서 (제조 원가계산서, 일위대가표 등)\n기타 필요 ◦과업내용서, 설계설명서 (시방서 등) ◦수입물품 관련 서류 (수입원, 수입물품 원가계산서 등) ◦수리 관련 서류 (수리 명세서, 수리단위별 내역서 등) ◦임차 관련 서류 (임차대상, 기간, 장소 및 임차조건 등) ◦시장재고, 유통여부, 견적서 등 기타 참고자료\n‣설계변경\n구분 제출 서류 목록\n필수 ◦설계변경 심사 요청서[서식 16] ◦설계도면, 공사 설계 설명서(공사시방서), 현장 설명서, 과업내용서 ◦설계내역서(비목별 기초계산서, 수량산출서, 노무비 산출 근거, 기계 경비 산출서, 일위대가표 및 단가산출서, 견적서, 계약내역서, 예정가격 산출내역서 등)\n기타 필요 소프트웨어 참고자료(엑셀 내역 파일, Auto Cad 도면)","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"제출 서류 목록","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"필수","colSpan":1,"rowSpan":1,"column":0},{"text":"◦공사계약 심사 요청서 [서식 13]\n◦설계도면, 공사설계 설명서(공사 시방서), 현장설명서, 과업내용서, 관급자재 현황\n◦설계 내역서 (비목별 기초계산서, 수량산출서, 노무비·기계경비 산출서, 일위대가표, 단가산출서, 견적서 등)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"기타 필요","colSpan":1,"rowSpan":1,"column":0},{"text":"◦소프트웨어 자료 (엑셀 내역 파일, Auto CAD 도면 등)\n※ 엑셀 파일은 연계 공종 간 링크된 형식으로 제출\n◦품셈과 표준시장단가를 동시에 적용하는 경우 품셈을 적용한 내역서와 표준시장단가를 적용한 내역서\n◦신기술·신공법 관련 자료\n◦방침서, 계획서, 기술 심사 조건, 내진 구조 성능 확인서 등 기타 심사에 필요한 자료","colSpan":1,"rowSpan":1,"column":1}]],"widths":[7.66,92.34],"lineStart":1,"lineCount":3},{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"제출 서류 목록","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"필수","colSpan":1,"rowSpan":1,"column":0},{"text":"◦(기술, 일반, 학술) 용역 계약 심사 요청서 [서식 14]\n◦과업 내용서\n◦설계 내역서 (비목별 기초계산서, 수량산출서, 노무비 산출근거, 일위대가표 및단가산출서, 견적서 등)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"기타 필요","colSpan":1,"rowSpan":1,"column":0},{"text":"◦소프트웨어 참고자료 (엑셀 내역 파일 등)\n◦방침서 (내부규정 문서)\n◦계획서 등 기타 심사에 필요한 서류","colSpan":1,"rowSpan":1,"column":1}]],"widths":[7.66,92.34],"lineStart":5,"lineCount":3},{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"제출 서류 목록","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"필수","colSpan":1,"rowSpan":1,"column":0},{"text":"◦물품 계약 심사요청서 서식 15\n◦산출 기초 조사서\n◦규격서 및 설명서 (사양서 등)\n◦설계 내역서 (제조 원가계산서, 일위대가표 등)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"기타 필요","colSpan":1,"rowSpan":1,"column":0},{"text":"◦과업내용서, 설계설명서 (시방서 등)\n◦수입물품 관련 서류 (수입원, 수입물품 원가계산서 등)\n◦수리 관련 서류 (수리 명세서, 수리단위별 내역서 등)\n◦임차 관련 서류 (임차대상, 기간, 장소 및 임차조건 등)\n◦시장재고, 유통여부, 견적서 등 기타 참고자료","colSpan":1,"rowSpan":1,"column":1}]],"widths":[7.66,92.34],"lineStart":9,"lineCount":3},{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"제출 서류 목록","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"필수","colSpan":1,"rowSpan":1,"column":0},{"text":"◦설계변경 심사 요청서[서식 16]\n◦설계도면, 공사 설계 설명서(공사시방서), 현장 설명서, 과업내용서\n◦설계내역서(비목별 기초계산서, 수량산출서, 노무비 산출 근거, 기계 경비 산출서, 일위대가표 및 단가산출서, 견적서, 계약내역서, 예정가격 산출내역서 등)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"기타 필요","colSpan":1,"rowSpan":1,"column":0},{"text":"소프트웨어 참고자료(엑셀 내역 파일, Auto Cad 도면)","colSpan":1,"rowSpan":1,"column":1}]],"widths":[7.66,92.34],"lineStart":13,"lineCount":3}]},{"id":"c17-w02-b8","title":"9. 심사결과 통보","body":"‣계약심사요청을 받은 날로부터 10일(토요일 및 공휴일 제외)\n※ 예정가격결정(조서작성)을 생략한다는 것이지 예정가격 조사를 생략하는 것은 아님"},{"id":"c17-w02-b9","title":"10. 이의제기","body":"‣계약심사결과에 이의가 있거나 수용하기 곤란한 특별한 사유가 있는 경우 소명서를 첨부하여 재심사 요청 가능"},{"id":"c17-w02-b10","title":"11. 재심사 결과 통보","body":"‣재심사 요청을 받은 날로부터 5일 이내(토요일 및 공휴일 제외)\n※ 단, 원가분석자문단 심의를 받는 경우 10일(토요일 및 공휴일 제외) 이내"}],"flowGroups":[]},{"id":"c17-w03","number":3,"title":"계약의 유형","formIds":[],"faqCategories":[],"contentBlocks":[{"id":"c17-w03-b1","title":"세부내용 1. (목적물별) 계약의 유형","body":""},{"id":"c17-w03-b2","title":"관련법규 및 참고자료","body":"• 「건설산업기본법 시행령」, 「전기공사업법」, 「정보통신공사업법」, 「소방시설공사업법」\n• 「중소기업제품 구매촉진 및 판로지원에 관한 법률」"},{"id":"c17-w03-b3","title":"","body":"계약구분 내 용\n공사 계약 건설공사 (건설산업기본법 시행령) 종합공사 토목, 건축, 토목・건축, 산업・환경설비, 조경공사업 총 5종의 공사 계약\n전문 공사 지반조성・포장공사, 실내건축공사, 금속창호・지붕건축물조립공사, 도장・습식・방수・석공사, 조경식재・시설물공사, 철근・콘크리트공사, 구조물해체・비계 공사, 상・하수도설비공사, 철도・궤도공사, 철강구조물공사, 수중・준설공사, 승강기・삭도공사, 기계가스설비공사, 가스난방공사 등 총 14종의 공사 계약\n전기공사 (전기공사업법) ◦전기공사업법에 따른 계약 ◦전기공사는 전기공사업자가 아니면 도급받거나 시공 불가 ※ 전기공사업법 제3조에 명시된 공사는 예외적으로 전기공사업자가 아니더라도 시공 가능 ◦건설공사와 분리 발주 대상(같은 법 제11조)\n정보통신공사 (정보통신공사업법) ◦정보통신공사업법에 따른 계약 ◦정보통신공사는 정보통신공사업자가 아니면 도급받거나 시공 불가 ※ 정보통신공사업법 제3조에 명시된 공사는 예외적으로 정보통신공사업자가 아니더라도 시공 가능 ◦정보통신공사의 종류 - 통신설비, 방송설비, 정보설비, 기타설비(정보통신전용 전기시설설비) ◦건설공사와 분리발주 대상(같은 법 제25조)\n소방시설공사 (소방시설공사업법) ◦소방시설공사업법에 따른 계약 ◦소방시설공사업의 종류 - 전문소방시설공사업(모든 특정시설공사) - 일반소방시설공사업[연면적 1만㎡ 미만 특정소방대상에 설치되는(기계분야 ․ 전기분야)] - 소방공사감리업(소방공사의 품질 ․ 시공 관리에 대한 기술지도 ) - 방염처리업(화재예방, 소방시설 설치 및 관리에 관한 법률 제20조에 따른 방염대상물품에 대하여 방염처리 하는 영업) - 전문소방시설설계업(모든 특정소방대상물 소방시설의 설계) - 일반소방시설설계업[연면적 3만㎡ 미만 특정소방대상물 소방설계(기계분야 ․ 전기분야)] ◦건설공사와 분리발주 대상(같은 법 제21조)\n기타공사 문화재공사, 환경 관련 시설물 공사 계약 등\n물 품 계 약 구매, 제조구매 등 ◦구매계약: 시중 유통품을 구입하는 계약 ◦제조구매계약: 발주자의 요구에 따라 제조된 물품을 구매하는 계약 - 정부지원 특정법률 준수의무: 중소기업제품구매 촉진 및 판로지원에 관한 법률, 중증장애인생산품 우선구매 특별법, 여성기업지원에 관한 법률 등\n용 역 계 약 기술용역 건설기술용역, 엔지니어링사업, 건설사업관리, 공사설계・감리・측량용역 계약\n학술연구용역 정책의 개발 및 연구, 수요・공급의 예측 용역 계약\n일반용역 정보통신관련용역, 폐기물처리용역, 시설물관리・청소・경비 용역, 육상운송용역, 학술용역, 광고 및 디자인용역, 장비유지보수용역 등(기술용역과 학술연구용역을 제외한 나머지 용역)","tables":[{"headers":[{"text":"계약구분","colSpan":3,"rowSpan":1,"column":0},{"text":"내 용","colSpan":1,"rowSpan":1,"column":3}],"rows":[[{"text":"공사\n계약","colSpan":1,"rowSpan":6,"column":0},{"text":"건설공사\n(건설산업기본법 시행령)","colSpan":1,"rowSpan":2,"column":1},{"text":"종합공사","colSpan":1,"rowSpan":1,"column":2},{"text":"토목, 건축, 토목・건축, 산업・환경설비, 조경공사업 총 5종의 공사 계약","colSpan":1,"rowSpan":1,"column":3}],[{"text":"전문\n공사","colSpan":1,"rowSpan":1,"column":2},{"text":"지반조성・포장공사, 실내건축공사, 금속창호・지붕건축물조립공사, 도장・습식・방수・석공사, 조경식재・시설물공사, 철근・콘크리트공사, 구조물해체・비계 공사, 상・하수도설비공사, 철도・궤도공사, 철강구조물공사, 수중・준설공사, 승강기・삭도공사, 기계가스설비공사, 가스난방공사 등 총 14종의 공사 계약","colSpan":1,"rowSpan":1,"column":3}],[{"text":"전기공사\n(전기공사업법)","colSpan":2,"rowSpan":1,"column":1},{"text":"◦전기공사업법에 따른 계약\n◦전기공사는 전기공사업자가 아니면 도급받거나 시공 불가\n※ 전기공사업법 제3조에 명시된 공사는 예외적으로 전기공사업자가 아니더라도 시공 가능\n◦건설공사와 분리 발주 대상(같은 법 제11조)","colSpan":1,"rowSpan":1,"column":3}],[{"text":"정보통신공사\n(정보통신공사업법)","colSpan":2,"rowSpan":1,"column":1},{"text":"◦정보통신공사업법에 따른 계약\n◦정보통신공사는 정보통신공사업자가 아니면 도급받거나 시공 불가\n※ 정보통신공사업법 제3조에 명시된 공사는 예외적으로 정보통신공사업자가 아니더라도 시공 가능\n◦정보통신공사의 종류\n- 통신설비, 방송설비, 정보설비, 기타설비(정보통신전용 전기시설설비)\n◦건설공사와 분리발주 대상(같은 법 제25조)","colSpan":1,"rowSpan":1,"column":3}],[{"text":"소방시설공사\n(소방시설공사업법)","colSpan":2,"rowSpan":1,"column":1},{"text":"◦소방시설공사업법에 따른 계약\n◦소방시설공사업의 종류\n- 전문소방시설공사업(모든 특정시설공사)\n- 일반소방시설공사업[연면적 1만㎡ 미만 특정소방대상에 설치되는(기계분야 ․ 전기분야)]\n- 소방공사감리업(소방공사의 품질 ․ 시공 관리에 대한 기술지도 )\n- 방염처리업(화재예방, 소방시설 설치 및 관리에 관한 법률 제20조에 따른 방염대상물품에 대하여 방염처리 하는 영업)\n- 전문소방시설설계업(모든 특정소방대상물 소방시설의 설계)\n- 일반소방시설설계업[연면적 3만㎡ 미만 특정소방대상물 소방설계(기계분야 ․ 전기분야)]\n◦건설공사와 분리발주 대상(같은 법 제21조)","colSpan":1,"rowSpan":1,"column":3}],[{"text":"기타공사","colSpan":2,"rowSpan":1,"column":1},{"text":"문화재공사, 환경 관련 시설물 공사 계약 등","colSpan":1,"rowSpan":1,"column":3}],[{"text":"물\n품\n계\n약","colSpan":1,"rowSpan":1,"column":0},{"text":"구매, 제조구매 등","colSpan":2,"rowSpan":1,"column":1},{"text":"◦구매계약: 시중 유통품을 구입하는 계약\n◦제조구매계약: 발주자의 요구에 따라 제조된 물품을 구매하는 계약\n- 정부지원 특정법률 준수의무: 중소기업제품구매 촉진 및 판로지원에 관한 법률, 중증장애인생산품 우선구매 특별법, 여성기업지원에 관한 법률 등","colSpan":1,"rowSpan":1,"column":3}],[{"text":"용\n역\n계\n약","colSpan":1,"rowSpan":3,"column":0},{"text":"기술용역","colSpan":2,"rowSpan":1,"column":1},{"text":"건설기술용역, 엔지니어링사업, 건설사업관리, 공사설계・감리・측량용역 계약","colSpan":1,"rowSpan":1,"column":3}],[{"text":"학술연구용역","colSpan":2,"rowSpan":1,"column":1},{"text":"정책의 개발 및 연구, 수요・공급의 예측 용역 계약","colSpan":1,"rowSpan":1,"column":3}],[{"text":"일반용역","colSpan":2,"rowSpan":1,"column":1},{"text":"정보통신관련용역, 폐기물처리용역, 시설물관리・청소・경비 용역, 육상운송용역, 학술용역, 광고 및 디자인용역, 장비유지보수용역 등(기술용역과 학술연구용역을 제외한 나머지 용역)","colSpan":1,"rowSpan":1,"column":3}]],"widths":[3.05,10.37,6.1,80.49],"lineStart":0,"lineCount":11}]},{"id":"c17-w03-b4","title":"TIP","body":"▪ 건설면허 없이 가능한 경미한 공사(건설산업기본법 시행령 제8조)\n순 / 분야 / 기준\n1 / 종합공사 / 공사 예정금액 5천만원 미만인 공사\n2 / 전문공사 / 공사 예정금액 1천 5백만원 미만인 공사 (가스시설공사, 철강구조물공사, 삭도설치공사, 승강기설치공사, 철도·궤도공사, 난방공사는 제외)\n3 / 조립해체 이동이 용이한 기계설비 등을 제작・공급하는 자가 직접 설치하는공사 / 금액기준없음\n4 / 전기공사 / 전기공사업법 시행령 제5조에 따른 경미한 공사\n5 / 통신공사 / 정보통신공사업법 시행령 제4조에 따른 경미한 공사"},{"id":"c17-w03-b5","title":"세부내용 2. (체결형태별) 계약의 유형","body":""},{"id":"c17-w03-b6","title":"관련법규 및 참고자료","body":"•「지방자치단체를 당사자로 하는 계약에 관한 법률」 제24조, 제25조, 제29조"},{"id":"c17-w03-b7","title":"","body":"계약구분 내용\n계약이행기간 단년도계약 이행기간이 해당 연도 내에 있으며, 해당 연도의 예산 범위 내에서 체결하는 계약\n장기계속계약 ◦수년간 계속하여 존속할 필요가 있거나 그 이행에 수년을 요하는 경우 체결하는 계약 - 공사이행에 수년을 요하며, 설계서 등에 전체의 공사내용이 확정된 공사 ▷ 해당 연도 분 예산확보(장기간 총사업비 예산 미확보) ▷ 같은 회계연도 내에서 차수 계약 실시 ▷ 입찰공고 시 총 사업 기간 및 금액을 부기하며, 매년 예산범위 내에서 계약체결 및 계약 이행함\n계속비 계약 ◦완성에 수년을 요하는 공사, 제조 및 연구개발 시 체결하는 계약\n- 학교신설, 청사이전 등 계속비 예산으로 편성된 사업\n▷ 총사업비 예산 확보 ▷ 입찰공고 시 총 사업 기간 및 금액을 부기하며, 총 사업 금액으로 계약체결 및 계약 이행함\n총액 / 단가여부 총액계약 해당 계약목적물 전체에 대하여 총액으로 체결하는 계약\n단가계약 일정기간 계속 계약을 체결할 필요가 있을 때 해당 연도 예산범위 안에서 단가에 대해 체결하는 계약(지방계약법 제25조)\n금액 확정 여부 확정계약 계약금액 확정 후 체결하는 계약\n개산계약 계약금액을 확정하지 않고 개산 가격으로 체결하는 계약으로, 사후정산 필요(지방계약법 제27조)\n계약자수 단독계약 계약상대자를 1인으로 하여 체결하는 계약\n공동계약 ◦계약상대자를 2인 이상으로 결성된 공동수급체와 체결하는 계약(지방계약법 제29조) - 계약이행책임방식: 분담이행방식(각자), 공동이행방식(공동), 주계약자관리방식 (1차, 주계약자) ※ 입찰공고 시, 공동계약 이행방식과 구성원 자격제한사항을 명시하며 구성원 일부 또는 모두가 입찰참가자격을 각각 구비하도록 제한해서는 안됨 ※ 지역의무 공동도급제도: 건설업 등의 균형발전을 위하여 필요하다고 인정하는 공사의 경우에는 공사현장을 관할하는 특별시·광역시 및 도에 주된 영업소가 있는 자 중 일정 비율 이상을 수급체로 구성해야 하는 제도","tables":[{"headers":[{"text":"계약구분","colSpan":2,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"계약이행기간","colSpan":1,"rowSpan":5,"column":0},{"text":"단년도계약","colSpan":1,"rowSpan":1,"column":1},{"text":"이행기간이 해당 연도 내에 있으며, 해당 연도의 예산 범위 내에서 체결하는 계약","colSpan":1,"rowSpan":1,"column":2}],[{"text":"장기계속계약","colSpan":1,"rowSpan":1,"column":1},{"text":"◦수년간 계속하여 존속할 필요가 있거나 그 이행에 수년을 요하는 경우 체결하는 계약\n- 공사이행에 수년을 요하며, 설계서 등에 전체의 공사내용이 확정된 공사\n▷ 해당 연도 분 예산확보(장기간 총사업비 예산 미확보)\n▷ 같은 회계연도 내에서 차수 계약 실시\n▷ 입찰공고 시 총 사업 기간 및 금액을 부기하며, 매년 예산범위 내에서 계약체결 및 계약 이행함","colSpan":1,"rowSpan":1,"column":2}],[{"text":"계속비\n계약","colSpan":1,"rowSpan":3,"column":1},{"text":"◦완성에 수년을 요하는 공사, 제조 및 연구개발 시 체결하는 계약","colSpan":1,"rowSpan":1,"column":2}],[{"text":"- 학교신설, 청사이전 등 계속비 예산으로 편성된 사업","colSpan":1,"rowSpan":1,"column":2}],[{"text":"▷ 총사업비 예산 확보\n▷ 입찰공고 시 총 사업 기간 및 금액을 부기하며, 총 사업 금액으로 계약체결 및 계약 이행함","colSpan":1,"rowSpan":1,"column":2}],[{"text":"총액 / 단가여부","colSpan":1,"rowSpan":2,"column":0},{"text":"총액계약","colSpan":1,"rowSpan":1,"column":1},{"text":"해당 계약목적물 전체에 대하여 총액으로 체결하는 계약","colSpan":1,"rowSpan":1,"column":2}],[{"text":"단가계약","colSpan":1,"rowSpan":1,"column":1},{"text":"일정기간 계속 계약을 체결할 필요가 있을 때 해당 연도 예산범위 안에서 단가에 대해 체결하는 계약(지방계약법 제25조)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"금액\n확정\n여부","colSpan":1,"rowSpan":2,"column":0},{"text":"확정계약","colSpan":1,"rowSpan":1,"column":1},{"text":"계약금액 확정 후 체결하는 계약","colSpan":1,"rowSpan":1,"column":2}],[{"text":"개산계약","colSpan":1,"rowSpan":1,"column":1},{"text":"계약금액을 확정하지 않고 개산 가격으로 체결하는 계약으로, 사후정산 필요(지방계약법 제27조)","colSpan":1,"rowSpan":1,"column":2}],[{"text":"계약자수","colSpan":1,"rowSpan":2,"column":0},{"text":"단독계약","colSpan":1,"rowSpan":1,"column":1},{"text":"계약상대자를 1인으로 하여 체결하는 계약","colSpan":1,"rowSpan":1,"column":2}],[{"text":"공동계약","colSpan":1,"rowSpan":1,"column":1},{"text":"◦계약상대자를 2인 이상으로 결성된 공동수급체와 체결하는 계약(지방계약법 제29조)\n- 계약이행책임방식: 분담이행방식(각자), 공동이행방식(공동), 주계약자관리방식 (1차, 주계약자)\n※ 입찰공고 시, 공동계약 이행방식과 구성원 자격제한사항을 명시하며 구성원 일부 또는 모두가 입찰참가자격을 각각 구비하도록 제한해서는 안됨\n※ 지역의무 공동도급제도: 건설업 등의 균형발전을 위하여 필요하다고 인정하는 공사의 경우에는 공사현장을 관할하는 특별시·광역시 및 도에 주된 영업소가 있는 자 중 일정 비율 이상을 수급체로 구성해야 하는 제도","colSpan":1,"rowSpan":1,"column":2}]],"widths":[6.78,11.07,82.15],"lineStart":0,"lineCount":12}]},{"id":"c17-w03-b8","title":"TIP","body":"▪ 장기계속 계약과 계속비 계약 비교\n▸공통점\n- 공사이행에 여러 해가 소요\n- 설계서 등에 의하여 전체 사업내용 확정 후 체결\n▸차이점\n- 장기계속 계약: 총 사업비 예산 중 해당 연도분만 확보\n- 계속비 계약: 총 사업비 예산 전체를 확보"},{"id":"c17-w03-b9","title":"세부내용 3. (경쟁형태별) 계약의 유형","body":""},{"id":"c17-w03-b10","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률」 제9조, 제20조, 제21조\n• 「지방자치단체 입찰 및 계약집행기준(행정안전부 예규)」 \n• 물품 다수공급자계약 업무처리규정"},{"id":"c17-w03-b11","title":"","body":"계약구분 내용\n입찰계약 일반입찰 ◦계약내용을 공고하여 일정한 자격을 갖춘 불특정 다수를 대상으로 한 입찰 ◦입찰참가자의 자격 - 다른 법령에 따른 자격요건(허가·면허·등록 등) - 보안측정 등 조사가 필요한 경우에 관계기관의 적합 판정 - 사업자등록증 교부 또는 납세번호를 부여받은 자\n제한입찰 계약의 목적을 효과적으로 달성하기 위해 실적, 소재지 등으로 자격을 제한한 입찰\n지명입찰 특수한 설비·기술·자재 또는 실적을 가진 자를 지명하여 실시하는 입찰\n조달계약 제3자 단가 계약 수요기관과 공급처 간 거래에 있어 조달청이 적절한 단가를 결정하고 단가등록을 통해 조달청을 거쳐 구입하는 계약\n다수공급자계약 2단계경쟁 품질, 성능, 효율 등이 동등하거나 유사한 제품 중 수요기관이 선택할 수 있도록, 일정 기준을 충족한 2인 이상을 대상으로 가격협상을 통해 체결하는 계약 ※ 중소기업자간경쟁제품이 아닌 경우: 1회 납품요구대상 구매예산이 5천만 원 이상 시 다수공급자계약 이용 ※ 중소기업간경쟁물품 또는 중소기업 제조 품목: 1회 납품요구대상 구매예산이 1억 원 이상 시 다수공급자계약 이용\n수 의 계 약 2인 이상 견적제출 수의계약 수의계약 안내공고를 통해 2인 이상의 견적 참여자로부터 견적을 제출받아 계약상대자를 결정하는 계약 ※ 일정한 경우를 제외하고는 지정정보처리장치 이용이 원칙\n1인 견적 제출가능 수의계약 ◦1인으로부터 견적을 제출받아 견적가격을 거래실례가격 등과 비교·검토하고 품질 등을 고려하여 계약상대자를 결정하는 계약 - 1인 견적 계약가능 대상 ▷ 용역 / 공사: 추정가격 2천만 원 이하 ▷ 물품제조·구매: 추정가격 2천만 원 이하 - 추정가격 5천만 원 이하 1인 견적 가능한 경우 ▷ 여성기업(여성기업지원에 관한 법률 제2조 제1호) ▷ 장애인기업(장애인기업활동 촉진법 제2조 제2호)\n계약구분 내용\n수 의 계 약 1인 견적 제출가능 수의계약 ▷ 취약계층 고용비율 30% 이상인 아래 제시된 사회적경제기업 ※ 사회적기업(사회적기업 육성법 제2조 제1호) ※ 사회적협동조합(협동조합 기본법 제2조 제3호) ※ 자활기업(국민기초생활 보장법 제18조) ※ 마을기업(도시재생 활성화 및 지원에 관한 특별법 제2조 제1항 제9호) ※ 3의 경우 취약계층 고용비율 확인서를 발급받아 증빙자료로 첨부하고 이때 취약계층 고용비율은 30% 이상[취약계층 고용비율 고시(행정안전부 고시 제2018-49호)] ▷ 청년창업기업(중소기업창업 지원법 제2조제11호)","tables":[{"headers":[{"text":"계약구분","colSpan":2,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"입찰계약","colSpan":1,"rowSpan":3,"column":0},{"text":"일반입찰","colSpan":1,"rowSpan":1,"column":1},{"text":"◦계약내용을 공고하여 일정한 자격을 갖춘 불특정 다수를 대상으로 한 입찰\n◦입찰참가자의 자격\n- 다른 법령에 따른 자격요건(허가·면허·등록 등)\n- 보안측정 등 조사가 필요한 경우에 관계기관의 적합 판정\n- 사업자등록증 교부 또는 납세번호를 부여받은 자","colSpan":1,"rowSpan":1,"column":2}],[{"text":"제한입찰","colSpan":1,"rowSpan":1,"column":1},{"text":"계약의 목적을 효과적으로 달성하기 위해 실적, 소재지 등으로 자격을 제한한 입찰","colSpan":1,"rowSpan":1,"column":2}],[{"text":"지명입찰","colSpan":1,"rowSpan":1,"column":1},{"text":"특수한 설비·기술·자재 또는 실적을 가진 자를 지명하여 실시하는 입찰","colSpan":1,"rowSpan":1,"column":2}],[{"text":"조달계약","colSpan":1,"rowSpan":2,"column":0},{"text":"제3자\n단가 계약","colSpan":1,"rowSpan":1,"column":1},{"text":"수요기관과 공급처 간 거래에 있어 조달청이 적절한 단가를 결정하고 단가등록을 통해 조달청을 거쳐 구입하는 계약","colSpan":1,"rowSpan":1,"column":2}],[{"text":"다수공급자계약\n2단계경쟁","colSpan":1,"rowSpan":1,"column":1},{"text":"품질, 성능, 효율 등이 동등하거나 유사한 제품 중 수요기관이 선택할 수 있도록, 일정 기준을 충족한 2인 이상을 대상으로 가격협상을 통해 체결하는 계약\n※ 중소기업자간경쟁제품이 아닌 경우: 1회 납품요구대상 구매예산이 5천만 원 이상 시 다수공급자계약 이용\n※ 중소기업간경쟁물품 또는 중소기업 제조 품목: 1회 납품요구대상 구매예산이 1억 원 이상 시 다수공급자계약 이용","colSpan":1,"rowSpan":1,"column":2}],[{"text":"수\n의\n계\n약","colSpan":1,"rowSpan":2,"column":0},{"text":"2인 이상 견적제출 수의계약","colSpan":1,"rowSpan":1,"column":1},{"text":"수의계약 안내공고를 통해 2인 이상의 견적 참여자로부터 견적을 제출받아 계약상대자를 결정하는 계약\n※ 일정한 경우를 제외하고는 지정정보처리장치 이용이 원칙","colSpan":1,"rowSpan":1,"column":2}],[{"text":"1인 견적\n제출가능 수의계약","colSpan":1,"rowSpan":1,"column":1},{"text":"◦1인으로부터 견적을 제출받아 견적가격을 거래실례가격 등과 비교·검토하고 품질 등을 고려하여 계약상대자를 결정하는 계약\n- 1인 견적 계약가능 대상\n▷ 용역 / 공사: 추정가격 2천만 원 이하\n▷ 물품제조·구매: 추정가격 2천만 원 이하\n- 추정가격 5천만 원 이하 1인 견적 가능한 경우\n▷ 여성기업(여성기업지원에 관한 법률 제2조 제1호)\n▷ 장애인기업(장애인기업활동 촉진법 제2조 제2호)","colSpan":1,"rowSpan":1,"column":2}]],"widths":[3.72,11.07,85.21],"lineStart":0,"lineCount":8},{"headers":[{"text":"계약구분","colSpan":2,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"수\n의\n계\n약","colSpan":1,"rowSpan":1,"column":0},{"text":"1인 견적\n제출가능 수의계약","colSpan":1,"rowSpan":1,"column":1},{"text":"▷ 취약계층 고용비율 30% 이상인 아래 제시된 사회적경제기업\n※ 사회적기업(사회적기업 육성법 제2조 제1호)\n※ 사회적협동조합(협동조합 기본법 제2조 제3호)\n※ 자활기업(국민기초생활 보장법 제18조)\n※ 마을기업(도시재생 활성화 및 지원에 관한 특별법 제2조 제1항 제9호)\n※ 3의 경우 취약계층 고용비율 확인서를 발급받아 증빙자료로 첨부하고 이때 취약계층 고용비율은 30% 이상[취약계층 고용비율 고시(행정안전부 고시 제2018-49호)]\n▷ 청년창업기업(중소기업창업 지원법 제2조제11호)","colSpan":1,"rowSpan":1,"column":2}]],"widths":[3.79,10.7,85.51],"lineStart":8,"lineCount":2}]},{"id":"c17-w03-b12","title":"TIP","body":"▪ 입찰 시 지역제한 가능 금액(지방자치단체 입찰 및 계약 집행기준 제4장 제한입찰 운영요령)\n순 / 분야 / 기준 / 입찰 시 제한 가능 범위\n1 / 종합공사 / 추정가격 100억 미만 / 광역지방자치단체 ※ 지역제한 입찰을 하는 경우에는 납품지가 소재하는 시,도의 관할 구역 안에 법인등기부등본상 본점이 있는 자로 입찰참가 자격 제한(개인사업자의 경우 사업자등록증이나 관련법령에 따른 허가,인가,면허,등록,신고 등 관련서류의 사업자 소재지)\n2 / 전문공사 및 그밖의 공사 / 추정가격 10억원 미만\n3 / 물품,용역 / 추정가격 5억원 미만\n4 / 건설기술용역, 설계 및 공사 감리용역, 엔지니어링 기술 용역 / 추정가격 3.3억원 미만\n5 / 안전점검 및 정밀안전진단용역 / 추정가격 5억원 미만"},{"id":"c17-w03-b13","title":"세부내용 4. (낙찰자결정별) 계약의 유형","body":""},{"id":"c17-w03-b14","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률」 제11조, 제13조\n• 「같은 법 시행령」 제8조, 제10조, 제24조, 제41조~제48조\n• 「지방자치단체 입찰 및 계약집행기준」 제2장 예정가격 작성요령"},{"id":"c17-w03-b15","title":"1. 낙찰자 결정방법","body":"낙찰방법 결정 방법\n적격심사 예정가격이하 최저가 입찰자 순 이행능력 심사 이상인 자로 낙찰자 결정\n2인견적 수의계약 ◦공사계약 : 예정가격 대비 낙찰하한율(89.745%) 이상 최저가 견적자 낙찰자 결정 ◦물품·용역 계약 - 추정가격 2천만 원 이하: 예정가격 대비 낙찰하한율(90%) 이상 최저가 견적자 낙찰자 결정 - 추정가격 2천만 원 초과 ~ 1억원 이하: 예정가격 대비 낙찰하한율(88%) 이상 최저가 견적자 낙찰자 결정 - 간행물 구입 계약: 가격에 상관없이 예정가격 대비 90% 이상 최저가 견적자 낙찰\n희망수량 입찰 희망수량에 따라 최저가(최고가) 입찰자부터 순차적으로 수량에 달할 때까지의 입찰자를 낙찰자로 결정\n유사물품 복수입찰 유사종류 물품 중 일정수준 이상인 물품을 구매할 때 예정가격에 대한 입찰 금액의 비율이 가장 낮은 자를 결정\n구 분 내 용\n2단계 입찰 (규격 · 가격 분리) 1단계로 규격(기술)입찰서 제출, 심사 후 규격 적격자에 한해 2단계 가격입찰서를 제출시켜 예정가격 이하로서 최저가격으로 입찰한 자를 낙찰자로 결정\n2단계 입찰 (규격 · 가격 동시) 규격과 가격입찰서를 동시에 제출시켜 규격적격자를 대상으로 가격 개찰하여 예정가격 이하로서 최저가격으로 입찰한 자를 낙찰자로 적격자 선정\n협상에 의한 계약 물품(단순 물품 구매 제외) ․ 용역(청소․경비 등 단순한 노무를 제공하는 용역 제외) 계약에 있어 다수의 공급자들에게 제안을 제출받아 평가기준을 정하여 평가한 후 협상절차를 통하여 발주기관에 가장 유리하다고 인정된 업체와 계약","tables":[{"headers":[{"text":"낙찰방법","colSpan":1,"rowSpan":1,"column":0},{"text":"결정 방법","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"적격심사","colSpan":1,"rowSpan":1,"column":0},{"text":"예정가격이하 최저가 입찰자 순 이행능력 심사 이상인 자로 낙찰자 결정","colSpan":1,"rowSpan":1,"column":1}],[{"text":"2인견적\n수의계약","colSpan":1,"rowSpan":1,"column":0},{"text":"◦공사계약 : 예정가격 대비 낙찰하한율(89.745%) 이상 최저가 견적자 낙찰자 결정\n◦물품·용역 계약\n- 추정가격 2천만 원 이하: 예정가격 대비 낙찰하한율(90%) 이상 최저가 견적자 낙찰자 결정\n- 추정가격 2천만 원 초과 ~ 1억원 이하: 예정가격 대비 낙찰하한율(88%) 이상 최저가 견적자 낙찰자 결정\n- 간행물 구입 계약: 가격에 상관없이 예정가격 대비 90% 이상 최저가 견적자 낙찰","colSpan":1,"rowSpan":1,"column":1}],[{"text":"희망수량 입찰","colSpan":1,"rowSpan":1,"column":0},{"text":"희망수량에 따라 최저가(최고가) 입찰자부터 순차적으로 수량에 달할 때까지의 입찰자를 낙찰자로 결정","colSpan":1,"rowSpan":1,"column":1}],[{"text":"유사물품 복수입찰","colSpan":1,"rowSpan":1,"column":0},{"text":"유사종류 물품 중 일정수준 이상인 물품을 구매할 때 예정가격에 대한 입찰 금액의 비율이 가장 낮은 자를 결정","colSpan":1,"rowSpan":1,"column":1}]],"widths":[13.19,86.81],"lineStart":0,"lineCount":5},{"headers":[{"text":"구 분","colSpan":1,"rowSpan":1,"column":0},{"text":"내 용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"2단계 입찰\n(규격 · 가격 분리)","colSpan":1,"rowSpan":1,"column":0},{"text":"1단계로 규격(기술)입찰서 제출, 심사 후 규격 적격자에 한해 2단계 가격입찰서를 제출시켜 예정가격 이하로서 최저가격으로 입찰한 자를 낙찰자로 결정","colSpan":1,"rowSpan":1,"column":1}],[{"text":"2단계 입찰\n(규격 · 가격 동시)","colSpan":1,"rowSpan":1,"column":0},{"text":"규격과 가격입찰서를 동시에 제출시켜 규격적격자를 대상으로 가격 개찰하여 예정가격 이하로서 최저가격으로 입찰한 자를 낙찰자로 적격자 선정","colSpan":1,"rowSpan":1,"column":1}],[{"text":"협상에 의한 계약","colSpan":1,"rowSpan":1,"column":0},{"text":"물품(단순 물품 구매 제외) ․ 용역(청소․경비 등 단순한 노무를 제공하는 용역 제외) 계약에 있어 다수의 공급자들에게 제안을 제출받아 평가기준을 정하여 평가한 후 협상절차를 통하여 발주기관에 가장 유리하다고 인정된 업체와 계약","colSpan":1,"rowSpan":1,"column":1}]],"widths":[13.19,86.81],"lineStart":5,"lineCount":4}]},{"id":"c17-w03-b16","title":"2. 추정가격에 따른 계약 방법","body":"구분 수의계약 입찰(G2B)\n1인 수의 2인 이상 견적제출 <소액수의> 제한입찰(지역) 일반입찰\n종합 공사 추정가격 2천만 원 이하 2천만 원 초과~4억 원 이하 4억 원 초과~100억 미만 100억 이상\n방법 단일견적 공사 낙찰하한율 89.745%* 적격심사\n전문 공사 추정가격 2천만 원 이하 2천만 원 초과~2억 원 이하 2억 원 초과~10억 미만 10억 이상\n방법 단일견적 공사 낙찰하한율 89.745%* 적격심사\n전기 통신 소방 공사 추정가격 2천만 원 이하 2천만 원 초과~1억6천만 원 이하 1억6천만 원 초과~10억 미만 5억 이상\n방법 단일견적 공사 낙찰하한율 89.745%* 적격심사\n물품 제조 구매 추정가격 2천만 원 이하 2천만 원 초과~1억 원 이하 1억 원 초과~5억 미만 5억 이상\n방법 단일견적 낙찰하한율 88% (2천만 원이하 90% or 간행물 90%) 적격심사\n용역 추정가격 2천만 원 이하 2천만 원 초과~1억 원 이하 1억 원 초과 ~ 5억 원 미만 (안전진단용역 1.5억 원 미만, 건설기술‧설계 및 공사감리‧엔지니어링 기술 용역 3.3억 원 미만) 5억 이상\n방법 단일견적 낙찰하한율 88% (2천만 원 이하 90%) 적격심사","tables":[{"headers":[{"text":"구분","colSpan":2,"rowSpan":2,"column":0},{"text":"수의계약","colSpan":2,"rowSpan":1,"column":2},{"text":"입찰(G2B)","colSpan":2,"rowSpan":1,"column":4}],"rows":[[{"text":"1인 수의","colSpan":1,"rowSpan":1,"column":2},{"text":"2인 이상 견적제출\n<소액수의>","colSpan":1,"rowSpan":1,"column":3},{"text":"제한입찰(지역)","colSpan":1,"rowSpan":1,"column":4},{"text":"일반입찰","colSpan":1,"rowSpan":1,"column":5}],[{"text":"종합\n공사","colSpan":1,"rowSpan":2,"column":0},{"text":"추정가격","colSpan":1,"rowSpan":1,"column":1},{"text":"2천만 원 이하","colSpan":1,"rowSpan":1,"column":2},{"text":"2천만 원 초과~4억 원 이하","colSpan":1,"rowSpan":1,"column":3},{"text":"4억 원 초과~100억 미만","colSpan":1,"rowSpan":1,"column":4},{"text":"100억\n이상","colSpan":1,"rowSpan":1,"column":5}],[{"text":"방법","colSpan":1,"rowSpan":1,"column":1},{"text":"단일견적","colSpan":1,"rowSpan":1,"column":2},{"text":"공사 낙찰하한율 89.745%*","colSpan":1,"rowSpan":1,"column":3},{"text":"적격심사","colSpan":2,"rowSpan":1,"column":4}],[{"text":"전문\n공사","colSpan":1,"rowSpan":2,"column":0},{"text":"추정가격","colSpan":1,"rowSpan":1,"column":1},{"text":"2천만 원 이하","colSpan":1,"rowSpan":1,"column":2},{"text":"2천만 원 초과~2억 원 이하","colSpan":1,"rowSpan":1,"column":3},{"text":"2억 원 초과~10억 미만","colSpan":1,"rowSpan":1,"column":4},{"text":"10억 이상","colSpan":1,"rowSpan":1,"column":5}],[{"text":"방법","colSpan":1,"rowSpan":1,"column":1},{"text":"단일견적","colSpan":1,"rowSpan":1,"column":2},{"text":"공사 낙찰하한율 89.745%*","colSpan":1,"rowSpan":1,"column":3},{"text":"적격심사","colSpan":2,"rowSpan":1,"column":4}],[{"text":"전기\n통신\n소방\n공사","colSpan":1,"rowSpan":2,"column":0},{"text":"추정가격","colSpan":1,"rowSpan":1,"column":1},{"text":"2천만 원 이하","colSpan":1,"rowSpan":1,"column":2},{"text":"2천만 원 초과~1억6천만 원 이하","colSpan":1,"rowSpan":1,"column":3},{"text":"1억6천만 원 초과~10억 미만","colSpan":1,"rowSpan":1,"column":4},{"text":"5억 이상","colSpan":1,"rowSpan":1,"column":5}],[{"text":"방법","colSpan":1,"rowSpan":1,"column":1},{"text":"단일견적","colSpan":1,"rowSpan":1,"column":2},{"text":"공사 낙찰하한율 89.745%*","colSpan":1,"rowSpan":1,"column":3},{"text":"적격심사","colSpan":2,"rowSpan":1,"column":4}],[{"text":"물품\n제조\n구매","colSpan":1,"rowSpan":2,"column":0},{"text":"추정가격","colSpan":1,"rowSpan":1,"column":1},{"text":"2천만 원 이하","colSpan":1,"rowSpan":1,"column":2},{"text":"2천만 원 초과~1억 원 이하","colSpan":1,"rowSpan":1,"column":3},{"text":"1억 원 초과~5억 미만","colSpan":1,"rowSpan":1,"column":4},{"text":"5억 이상","colSpan":1,"rowSpan":1,"column":5}],[{"text":"방법","colSpan":1,"rowSpan":1,"column":1},{"text":"단일견적","colSpan":1,"rowSpan":1,"column":2},{"text":"낙찰하한율 88%\n(2천만 원이하 90% or 간행물 90%)","colSpan":1,"rowSpan":1,"column":3},{"text":"적격심사","colSpan":2,"rowSpan":1,"column":4}],[{"text":"용역","colSpan":1,"rowSpan":2,"column":0},{"text":"추정가격","colSpan":1,"rowSpan":1,"column":1},{"text":"2천만 원 이하","colSpan":1,"rowSpan":1,"column":2},{"text":"2천만 원 초과~1억 원 이하","colSpan":1,"rowSpan":1,"column":3},{"text":"1억 원 초과 ~ 5억 원 미만\n(안전진단용역 1.5억 원 미만, 건설기술‧설계 및 공사감리‧엔지니어링 기술 용역 3.3억 원 미만)","colSpan":1,"rowSpan":1,"column":4},{"text":"5억 이상","colSpan":1,"rowSpan":1,"column":5}],[{"text":"방법","colSpan":1,"rowSpan":1,"column":1},{"text":"단일견적","colSpan":1,"rowSpan":1,"column":2},{"text":"낙찰하한율 88%\n(2천만 원 이하 90%)","colSpan":1,"rowSpan":1,"column":3},{"text":"적격심사","colSpan":2,"rowSpan":1,"column":4}]],"widths":[7.87,11.64,15.44,29.22,25.16,10.67],"lineStart":0,"lineCount":12}]},{"id":"c17-w03-b17","title":"TIP","body":"▪ 공사 2인 이상 수의 견적제출 시 세부 낙찰 하한율 규정\n순 / 분야 / 기준\n1 / 종합공사 / 예정가격에서 국민연금보험료, 국민건강보험료, 퇴직공제부금비, 노인장기요양보험료, 산업안전보건관리비, 안전관리비, 품질관리비(이하 “국민연금보험료 등”)의 합산액을 감액한 금액 대비 견적가격에서 국민연금 보험료 등 합산액을 감액한 금액이 89.745% 이상으로 제출한 자(지방자치단체 입찰 및 계약 집행기준 제5장 3절)\n2 / 전문공사\n3 / 전기,통신,소방공사"}],"flowGroups":[]},{"id":"c17-w04","number":4,"title":"계약 방법","formIds":[],"faqCategories":[],"contentBlocks":[{"id":"c17-w04-b1","title":"세부내용 1. 입찰","body":""},{"id":"c17-w04-b2","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제15조, 제16조, 제20조"},{"id":"c17-w04-b3","title":"","body":"업무순서 세부사항\n예산 집행 품의(사업계획서) 해당 사업부서에서 작성 및 품의\n발주계획 등록 ◦등록대상: 입찰 대상 물품·용역·공사 계약 ◦등록방법: 나라장터 → 발주 → 발주목록 → 신규 → 발주계획(예산액, 입찰방법 등 입력)\n구매규격 사전공개 ◦공개대상: 추정가격 5천만 원 이상 물품·용역 (공사 제외) ◦공개일수: 일반 5일 / 긴급입찰 3일 ◦공개방법: 나라장터 → 발주 → 발주목록 → 신규 → 사전규격공개 ◦공개서류: 과업지시서, 특수조건 등 규격 관련 서류(공고문 제외)\n예정가격 작성을 위한 기초금액 작성 ◦기초금액 작성: 조사한 가격 또는 설계가격의 적정성 검토 후 작성 ◦최종 예정가격조서 작성 (☞ 관련 절차는 예정가격의 정의 및 작성절차 참고)\n사업 내부결재 및 공고문 작성 ◦시설공사: [계약방법결정] OOOOO 공사 집행[예시 3, 4참고] ◦용역계약: [계약방법결정] OOOOO 위탁 용역[예시 3, 4참고] ※ 예시 공고문은 계약 방식에 따라 참고자료로만 활용\n입찰 공고 ◦공고방법: 나라장터 → 입찰 → 입찰공고목록 → 신규 → 공고문 입력 및 게시 ◦정정공고 시: 잔여일수에 5일 이상 가산 해야함","tables":[{"headers":[{"text":"업무순서","colSpan":1,"rowSpan":1,"column":0},{"text":"세부사항","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"예산 집행 품의(사업계획서)","colSpan":1,"rowSpan":1,"column":0},{"text":"해당 사업부서에서 작성 및 품의","colSpan":1,"rowSpan":1,"column":1}],[{"text":"발주계획 등록","colSpan":1,"rowSpan":1,"column":0},{"text":"◦등록대상: 입찰 대상 물품·용역·공사 계약\n◦등록방법: 나라장터 → 발주 → 발주목록 → 신규 → 발주계획(예산액, 입찰방법 등 입력)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"구매규격\n사전공개","colSpan":1,"rowSpan":1,"column":0},{"text":"◦공개대상: 추정가격 5천만 원 이상 물품·용역 (공사 제외)\n◦공개일수: 일반 5일 / 긴급입찰 3일\n◦공개방법: 나라장터 → 발주 → 발주목록 → 신규 → 사전규격공개\n◦공개서류: 과업지시서, 특수조건 등 규격 관련 서류(공고문 제외)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"예정가격 작성을 위한 기초금액 작성","colSpan":1,"rowSpan":1,"column":0},{"text":"◦기초금액 작성: 조사한 가격 또는 설계가격의 적정성 검토 후 작성\n◦최종 예정가격조서 작성 (☞ 관련 절차는 예정가격의 정의 및 작성절차 참고)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"사업 내부결재 및 공고문 작성","colSpan":1,"rowSpan":1,"column":0},{"text":"◦시설공사: [계약방법결정] OOOOO 공사 집행[예시 3, 4참고]\n◦용역계약: [계약방법결정] OOOOO 위탁 용역[예시 3, 4참고]\n※ 예시 공고문은 계약 방식에 따라 참고자료로만 활용","colSpan":1,"rowSpan":1,"column":1}],[{"text":"입찰 공고","colSpan":1,"rowSpan":1,"column":0},{"text":"◦공고방법: 나라장터 → 입찰 → 입찰공고목록 → 신규 → 공고문 입력 및 게시\n◦정정공고 시: 잔여일수에 5일 이상 가산 해야함","colSpan":1,"rowSpan":1,"column":1}]],"widths":[28.55,71.45],"lineStart":0,"lineCount":7}]},{"id":"c17-w04-b4","title":"TIP","body":"▪ 입찰공고의 종류\n공고명 / 설명\n재입찰 / 유찰 후 공고절차를 생략하고 재차 입찰, 재입찰 기간만 추가 (새로운 입찰로 보지 아니하며, 재입찰 횟수의 제한이 없음)\n재공고 / 유찰 또는 낙찰자가 계약 체결을 하지 않은 경우 (기한을 제외하고는 최초 입찰에 부칠 때에 정한 가격과 그밖의 조건 변경 불가)\n정정공고 / 입찰 공고 내용에 단순 법규위반 사항 포함 또는 관련법령 등을 잘못 표기하는 등 경미한 하자가 있는 경우 정정하여 올리는 공고 (해당 입찰 공고기간의 남은 일수에 5일 이상을 가산하여 공고)\n새로공고 / 사업내용, 예정가격, 입찰참가자격, 입찰 및 계약의 조건 등 입찰공고 내용에 중대한 착오·오류가 있는 경우에는 해당 입찰공고를 취소하고 새로 공고해야 함"},{"id":"c17-w04-b5","title":"","body":"업무 순서 세부사항\n기초금액 및 A값 입력 (A값은 공사계약시 입력) ◦대상 항목: 국민연금, 건강보험, 노인장기요양보험, 퇴직공제부금, 산업안전보건관리비, 안전관리비, 품질관리비의 합산액 = A값 ◦입력 경로: 나라장터 → 입찰 → 입찰공고목록 → 공고처리상태(게시) → 공고명 클릭 → 기초금액(수요기관) → A값 입력 후 저장 ◦공개 시점: 입찰서 제출 마감일 5일 전까지 지정정보처리장치에 공개\n현장설명 실시 (공사 관련 현장설명회를 하는 경우에만 해당) ◦조서 작성: 현장(품)설명 청취조서 [서식 17] 작성 ◦의무사항: 추정가격 300억 원 이상 공사의 경우\n예정가격 결정 지정정보처리장치(G2B 등)가 정한 기준 및 절차에 따라 기초금액 기준 ±3% 범위 내에서 작성된 15개의 예비가격 중 입찰에 참여하는 업체가 추첨(2개씩 선택)한 번호 중 가장 많이 선택된 4개의 복수예비가격을 산술평균한 금액을 예정가격으로 결정 ※ 1원 미만 절상 (단가입찰 제외)\n개찰 ◦공고 선택 → 개찰시작 → 사전판정 → 예정가격 확인 및 저장 → 개찰 진행 → 낙찰하한율 비교 ◦개찰결과보고시 출력 자료 - 개찰결과보고서 - 낙찰예정자 등록자료 - 개찰조서 - 예정가 추첨조서 - 예비가격 추첨 현황 등\n적격심사 ◦물품: 「지방자치단체 입찰 시 낙찰자 결정기준」 제2장의3 물품 적격심사 세부기준 등 ◦기술·학술연구용역: 「지방자치단체 입찰 시 낙찰자 결정기준」 제2장의2 세부기준 등 ◦일반용역: 조달청 일반용역 적격심사 세부기준 등 ◦시설공사: 「지방자치단체 입찰 시 낙찰자 결정기준」 제2장의1 시설공사 적격심사 세부기준 등\n계약상대자 결정 및 계약체결 낙찰자와 계약 체결, 이행, 대가지급 절차 이행 ※ 참고: 계약체결·이행·대가지급","tables":[{"headers":[{"text":"업무 순서","colSpan":1,"rowSpan":1,"column":0},{"text":"세부사항","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"기초금액 및 A값 입력\n(A값은 공사계약시 입력)","colSpan":1,"rowSpan":1,"column":0},{"text":"◦대상 항목: 국민연금, 건강보험, 노인장기요양보험, 퇴직공제부금, 산업안전보건관리비, 안전관리비, 품질관리비의 합산액 = A값\n◦입력 경로: 나라장터 → 입찰 → 입찰공고목록 → 공고처리상태(게시) → 공고명 클릭 → 기초금액(수요기관) → A값 입력 후 저장\n◦공개 시점: 입찰서 제출 마감일 5일 전까지 지정정보처리장치에 공개","colSpan":1,"rowSpan":1,"column":1}],[{"text":"현장설명 실시\n(공사 관련 현장설명회를 하는 경우에만 해당)","colSpan":1,"rowSpan":1,"column":0},{"text":"◦조서 작성: 현장(품)설명 청취조서 [서식 17] 작성\n◦의무사항: 추정가격 300억 원 이상 공사의 경우","colSpan":1,"rowSpan":1,"column":1}],[{"text":"예정가격 결정","colSpan":1,"rowSpan":1,"column":0},{"text":"지정정보처리장치(G2B 등)가 정한 기준 및 절차에 따라 기초금액 기준 ±3% 범위 내에서 작성된 15개의 예비가격 중 입찰에 참여하는 업체가 추첨(2개씩 선택)한 번호 중 가장 많이 선택된 4개의 복수예비가격을 산술평균한 금액을 예정가격으로 결정\n※ 1원 미만 절상 (단가입찰 제외)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"개찰","colSpan":1,"rowSpan":1,"column":0},{"text":"◦공고 선택 → 개찰시작 → 사전판정 → 예정가격 확인 및 저장 → 개찰 진행 → 낙찰하한율 비교\n◦개찰결과보고시 출력 자료\n- 개찰결과보고서\n- 낙찰예정자 등록자료\n- 개찰조서\n- 예정가 추첨조서\n- 예비가격 추첨 현황 등","colSpan":1,"rowSpan":1,"column":1}],[{"text":"적격심사","colSpan":1,"rowSpan":1,"column":0},{"text":"◦물품: 「지방자치단체 입찰 시 낙찰자 결정기준」 제2장의3 물품 적격심사 세부기준 등\n◦기술·학술연구용역: 「지방자치단체 입찰 시 낙찰자 결정기준」 제2장의2 세부기준 등\n◦일반용역: 조달청 일반용역 적격심사 세부기준 등\n◦시설공사: 「지방자치단체 입찰 시 낙찰자 결정기준」 제2장의1 시설공사 적격심사 세부기준 등","colSpan":1,"rowSpan":1,"column":1}],[{"text":"계약상대자 결정 및 계약체결","colSpan":1,"rowSpan":1,"column":0},{"text":"낙찰자와 계약 체결, 이행, 대가지급 절차 이행\n※ 참고: 계약체결·이행·대가지급","colSpan":1,"rowSpan":1,"column":1}]],"widths":[26.26,73.74],"lineStart":0,"lineCount":7}]},{"id":"c17-w04-b6","title":"TIP","body":"▪ 2인 이상 수의견적과 입찰의 구분\n구분 / 2인 이상 수의견적 / 입찰\n적용대상 / ◦공사: 추정가격 2천만 원 초과 ~ 4억 원 이하(종합 / 2억 원 이하(전문) / 1억 6천만 원 이하(전기 등 그 밖의 공사) ◦물품 / 용역: 추정가격 2천만원 초과 ~ 1억 원 이하 / ◦물품 / 용역: 추정가격 1억 원 초과 ◦공사: 추정가격 4억 원 초과(종합) / 2억 원 초과(전문) / 1억 6천만 원 초과(전기 등 그 밖의 공사)\n공고방법 / 지정정보처리장치 / 지정정보처리장치\n공고명 / ○○건 수의계약 안내공고 / ○○건 입찰공고\n공고기간 / 3일 이상(토요일 및 공휴일 제외) / 7일(긴급 및 재공고는 5일) 이상\n입찰보증금 / 납부하지 않음 / 납부\n계약상대자 결정 / ◦공사: 예정가격에서 국민연금보험료, 국민건강보험료, 퇴직공제부금비, 노인장기요양보험료, 산업안전보건관리비, 안전관리비, 품질관리비(이하 “국민연금보험료 등”)의 합산액을 감액한 금액의 89.745%이상 견적한 자 중 최저가를 견적하고 수의계약 배제사유에 해당하지 않는 자 ◦물품 ․ 용역 - 추정가격 2천만 원 이하: 예정가격 대비 90% 이상 견적한 자 중 최저가를 견적하고 수의계약 배제사유에 해당하지 않는 자 - 추정가격 2천만 원 초과 ~ 1억원 이하: 예정가격 대비 88% 이상 견적한 자 중 최저가를 견적하고 수의계약 배제사유에 해당하지 않는 자 - 간행물 구입 계약: 가격에 상관없이 예정가격 대비 90% 이상 견적한 자 중 최저가를 견적하고 수의계약 배제사유에 해당 하지 않는 자 / ◦물품: 적격심사 / 계약이행능력심사 ◦용역: 적격심사 ◦공사: 적격심사 ※ 세부기준별 적격통과 점수 및 낙찰하한율 확인\n지역제한 / ◦공사현장·납품소재지를 관할하는 시 ․ 군, 인접 시 ․ 군, 시 ․ 도, 인접 시 ․ 도 제한 가능 ◦지역제한과 실적제한 중복 제한 가능함 / ◦본점소재지(법인) 또는 사업장 소재지(개인사업자)가 관할 시 ․ 도내에 있는 업체 ※ 시 ․ 군으로 제한 불가 ◦물품 ․ 용역 입찰 시 지역과 실적 중복 제한 불가\n부정당업자 제재 조치 / ◦계약상대자 결정 후 계약 체결하지 않을 경우 수의계약배제사유로 3개월간 수의계약 제한 ◦계약체결 후 이행을 하지 않을 경우 계약보증금 세입 조치와 부정당업자 제재 조치 / 낙찰자결정 후 계약을 체결하지 않거나 계약체결 후 계약이행을 하지 아니한 경우, 입찰 ․ 계약보증금 세입 조치 및 부정당업자 제재 조치\n근거법령 / 지방자치단체 입찰 및 계약 집행기준 제5장 수의계약 운영요령 / 지방계약법, 시행령, 시행규칙"},{"id":"c17-w04-b7","title":"세부내용 2. 수의계약(2인이상 수의견적)","body":""},{"id":"c17-w04-b8","title":"관련법규 및 참고자료","body":"• 「지방자치단체 입찰 및 계약집행기준」 제5장 수의계약 운영요령"},{"id":"c17-w04-b9","title":"","body":"단계 업무내용 세부사항\n1 예산 집행 품의 (사업계획서) 사업부서에서 작성\n2 예정가격 작성을 위한 기초금액 작성 참고: 예정가격의 의의 및 작성 절차\n3 사업 내부결재 및 공고문 작성 ◦시설공사: [계약방법결정] OOOOO 공사 집행 ◦물품·용역: [계약방법결정] OOOOO 물품 구입 ※ 참고: 예시 3, 예시 4\n4 수의계약 안내 공고 및 기초금액 입력 G2B 시스템에 안내 공고 및 기초금액 입력 참고 ※ 참고: 입찰\n5 복수예비가격 작성 복수예비가격 산정 절차 진행 ※ 참고: 입찰\n6 개찰 ◦개찰 후 낙찰자 선정 전 입찰자 자격 확인 ◦부정당업자 및 수의계약 참가제한 여부 조회 - G2B → 공통 → 조달업체정보조회 → 부정당업자 조회 - K에듀파인 → 계약관리 → 계약업체관리 → 수의계약배제업체관리 ◦배제여부 심사: 지방자치단체 입찰 및 계약집행기준 제5장 참고 ◦부적격 시 차순위자 검토 가능 (계약포기서 제출 포함) ※ 참고: 입찰\n7 계약상대자 결정 및 계약체결 낙찰자와 계약 체결, 이행, 대가지급 절차 이행 ※ 참고: 계약체결·이행·대가지급","tables":[{"headers":[{"text":"단계","colSpan":1,"rowSpan":1,"column":0},{"text":"업무내용","colSpan":1,"rowSpan":1,"column":1},{"text":"세부사항","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"1","colSpan":1,"rowSpan":1,"column":0},{"text":"예산 집행 품의 (사업계획서)","colSpan":1,"rowSpan":1,"column":1},{"text":"사업부서에서 작성","colSpan":1,"rowSpan":1,"column":2}],[{"text":"2","colSpan":1,"rowSpan":1,"column":0},{"text":"예정가격 작성을 위한 기초금액 작성","colSpan":1,"rowSpan":1,"column":1},{"text":"참고: 예정가격의 의의 및 작성 절차","colSpan":1,"rowSpan":1,"column":2}],[{"text":"3","colSpan":1,"rowSpan":1,"column":0},{"text":"사업 내부결재 및 공고문 작성","colSpan":1,"rowSpan":1,"column":1},{"text":"◦시설공사: [계약방법결정] OOOOO 공사 집행\n◦물품·용역: [계약방법결정] OOOOO 물품 구입\n※ 참고: 예시 3, 예시 4","colSpan":1,"rowSpan":1,"column":2}],[{"text":"4","colSpan":1,"rowSpan":1,"column":0},{"text":"수의계약 안내 공고 및 기초금액 입력","colSpan":1,"rowSpan":1,"column":1},{"text":"G2B 시스템에 안내 공고 및 기초금액 입력 참고\n※ 참고: 입찰","colSpan":1,"rowSpan":1,"column":2}],[{"text":"5","colSpan":1,"rowSpan":1,"column":0},{"text":"복수예비가격 작성","colSpan":1,"rowSpan":1,"column":1},{"text":"복수예비가격 산정 절차 진행\n※ 참고: 입찰","colSpan":1,"rowSpan":1,"column":2}],[{"text":"6","colSpan":1,"rowSpan":1,"column":0},{"text":"개찰","colSpan":1,"rowSpan":1,"column":1},{"text":"◦개찰 후 낙찰자 선정 전 입찰자 자격 확인\n◦부정당업자 및 수의계약 참가제한 여부 조회\n- G2B → 공통 → 조달업체정보조회 → 부정당업자 조회\n- K에듀파인 → 계약관리 → 계약업체관리 → 수의계약배제업체관리\n◦배제여부 심사: 지방자치단체 입찰 및 계약집행기준 제5장 참고\n◦부적격 시 차순위자 검토 가능 (계약포기서 제출 포함)\n※ 참고: 입찰","colSpan":1,"rowSpan":1,"column":2}],[{"text":"7","colSpan":1,"rowSpan":1,"column":0},{"text":"계약상대자 결정 및 계약체결","colSpan":1,"rowSpan":1,"column":1},{"text":"낙찰자와 계약 체결, 이행, 대가지급 절차 이행\n※ 참고: 계약체결·이행·대가지급","colSpan":1,"rowSpan":1,"column":2}]],"widths":[7.52,33.39,59.09],"lineStart":0,"lineCount":8}]},{"id":"c17-w04-b10","title":"세부내용 3. 수의계약(1인견적)","body":""},{"id":"c17-w04-b11","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제8조, 제25조, 제30조, 제49조, 제67조, 제124조"},{"id":"c17-w04-b12","title":"","body":"1. 1인견적 수의계약 순서\n단계 업무내용 세부사항 및 참고자료\n1 예산 집행 품의 (사업계획서) ◦해당 사업부서에서 작성 ◦시방서, 도면, 사양서 등 첨부\n2 예정가격 조사 참고: 예정가격의 의의 및 작성 절차\n3 견적서 제출 요청 ◦수의계약 대상 업체에 견적 요청 ◦견적서는 계약상대자 결정의 기초자료로 활용\n4 사업 내부결재 견적 결과, 예정가격 등을 반영한 내부결재 진행\n5 계약상대자 결정 ◦거래실례가격, 통계자료, 감정가격, 유사 실례가격과 비교 ◦품질, 납품기한, 사후관리 등을 종합 고려 ◦계약상대자의 면허·등록·부정당업자 제재 여부 확인 필수\n단계 업무내용 세부사항 및 참고자료\n6 계약체결 및 검수 계약 체결 후 이행 및 물품·용역 검수 절차 진행 ※ 참고: 계약체결·이행·대가지급\n7 계약과정 정보공개 ◦공개 대상: 교육행정기관 및 각급학교 ◦공개 항목: 발주계획, 입찰공고, 개찰결과, 계약내용, 감리·검사, 대가지급현황 등 ◦공개 시기: 매월 다음 달 5일까지 ◦공개 기간: 계약이행 완료일로부터 5년 이상 ◦학교는 100만 원 이상 수의계약부터 공개 대상 ※ K에듀파인 시스템과 연계되어 정보가 자동공개됨\n2. 1인견적 수의계약 사유\n구분 1인 견적에 의한 수의계약 사유\n일정금액이하 (추정가격) 기타사유\n공사 종합공사 2천만 원 이하 ◦하자 구분 곤란, 혼잡, 마감공사 및 특허공법 등에 따른 수의계약(시행령 제25조제1항제4호 가,나,다,마목) ◦천재지변, 작전상의 병력이동, 긴급한 행사, 감염병 발생 및 유행 등 입찰에 부칠 여유가 없는 경우 등(시행령 제25조제1항제1호~제3호, 제4호 라, 바~하목, 제6호~제8호) ◦계약을 해제·해지 경우(시행령 제27조) ◦재공고입찰 결과 입찰이 성립하지 아니 하거나 낙찰자가 없는 경우(시행령 제26조제1항) ◦시행령 제95조제1항제4호에 따른 대안입찰, 같은 항 제5호에 따른 일괄입찰 또는 제127조제2호, 제3호에 따른 기술제안입찰로 발주되었으나 재공고입찰 결과 입찰자가 1인 뿐인 경우 ◦지정정보처리장치를 이용하여 견적서를 제출 받았으나 견적서 제출자가 1인 뿐인 경우로서 다시 견적서를 제출 받더라도 견적서 제출자가 1인 뿐일 것으로 명백히 예상되는 경우(시행령 제30조제1항제3호) ◦(금액기준 예외) 추정가격 5천만 원 이하 1인 견적 가능한 경우 - 여성기업(여성기업지원에 관한 법률 제2조제1호) - 장애인기업(장애인기업활동 촉진법 제2조제2호) - 취약계층 고용비율 30% 이상 아래 사회적경제기업 ▷ 사회적기업(사회적기업 육성법 제2조제1호) ▷ 사회적협동조합(협동조합 기본법 제2조제3호) ▷ 자활기업(국민기초생활 보장법 제18조) ▷ 마을기업(도시재생 활성화 및 지원에 관한 특별법 제2조제1항제9호) ※ 취약계층 고용비율 확인서 발급기준은 지방자치단체 입찰 및 계약 집행기준 제5장 수의계약 운영요령 [별표 3] 확인 - 청년창업기업(중소기업창업 지원법 제2조제11호)\n전문공사 2천만 원 이하\n전기소방 통신 2천만 원 이하\n물품제조·구매 2천만 원 이하\n용역· 기타 2천만 원 이하","tables":[{"headers":[{"text":"단계","colSpan":1,"rowSpan":1,"column":0},{"text":"업무내용","colSpan":1,"rowSpan":1,"column":1},{"text":"세부사항 및 참고자료","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"1","colSpan":1,"rowSpan":1,"column":0},{"text":"예산 집행 품의\n(사업계획서)","colSpan":1,"rowSpan":1,"column":1},{"text":"◦해당 사업부서에서 작성\n◦시방서, 도면, 사양서 등 첨부","colSpan":1,"rowSpan":1,"column":2}],[{"text":"2","colSpan":1,"rowSpan":1,"column":0},{"text":"예정가격 조사","colSpan":1,"rowSpan":1,"column":1},{"text":"참고: 예정가격의 의의 및 작성 절차","colSpan":1,"rowSpan":1,"column":2}],[{"text":"3","colSpan":1,"rowSpan":1,"column":0},{"text":"견적서 제출 요청","colSpan":1,"rowSpan":1,"column":1},{"text":"◦수의계약 대상 업체에 견적 요청\n◦견적서는 계약상대자 결정의 기초자료로 활용","colSpan":1,"rowSpan":1,"column":2}],[{"text":"4","colSpan":1,"rowSpan":1,"column":0},{"text":"사업 내부결재","colSpan":1,"rowSpan":1,"column":1},{"text":"견적 결과, 예정가격 등을 반영한 내부결재 진행","colSpan":1,"rowSpan":1,"column":2}],[{"text":"5","colSpan":1,"rowSpan":1,"column":0},{"text":"계약상대자 결정","colSpan":1,"rowSpan":1,"column":1},{"text":"◦거래실례가격, 통계자료, 감정가격, 유사 실례가격과 비교\n◦품질, 납품기한, 사후관리 등을 종합 고려\n◦계약상대자의 면허·등록·부정당업자 제재 여부 확인 필수","colSpan":1,"rowSpan":1,"column":2}]],"widths":[7.71,29.21,63.08],"lineStart":1,"lineCount":6},{"headers":[{"text":"단계","colSpan":1,"rowSpan":1,"column":0},{"text":"업무내용","colSpan":1,"rowSpan":1,"column":1},{"text":"세부사항 및 참고자료","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"6","colSpan":1,"rowSpan":1,"column":0},{"text":"계약체결 및 검수","colSpan":1,"rowSpan":1,"column":1},{"text":"계약 체결 후 이행 및 물품·용역 검수 절차 진행\n※ 참고: 계약체결·이행·대가지급","colSpan":1,"rowSpan":1,"column":2}],[{"text":"7","colSpan":1,"rowSpan":1,"column":0},{"text":"계약과정 정보공개","colSpan":1,"rowSpan":1,"column":1},{"text":"◦공개 대상: 교육행정기관 및 각급학교\n◦공개 항목: 발주계획, 입찰공고, 개찰결과, 계약내용, 감리·검사, 대가지급현황 등\n◦공개 시기: 매월 다음 달 5일까지\n◦공개 기간: 계약이행 완료일로부터 5년 이상\n◦학교는 100만 원 이상 수의계약부터 공개 대상\n※ K에듀파인 시스템과 연계되어 정보가 자동공개됨","colSpan":1,"rowSpan":1,"column":2}]],"widths":[7.71,29.21,63.08],"lineStart":7,"lineCount":3},{"headers":[{"text":"구분","colSpan":2,"rowSpan":2,"column":0},{"text":"1인 견적에 의한 수의계약 사유","colSpan":2,"rowSpan":1,"column":2}],"rows":[[{"text":"일정금액이하\n(추정가격)","colSpan":1,"rowSpan":1,"column":2},{"text":"기타사유","colSpan":1,"rowSpan":1,"column":3}],[{"text":"공사","colSpan":1,"rowSpan":3,"column":0},{"text":"종합공사","colSpan":1,"rowSpan":1,"column":1},{"text":"2천만 원\n이하","colSpan":1,"rowSpan":1,"column":2},{"text":"◦하자 구분 곤란, 혼잡, 마감공사 및 특허공법 등에 따른 수의계약(시행령 제25조제1항제4호 가,나,다,마목)\n◦천재지변, 작전상의 병력이동, 긴급한 행사, 감염병 발생 및 유행 등 입찰에 부칠 여유가 없는 경우 등(시행령 제25조제1항제1호~제3호, 제4호 라, 바~하목, 제6호~제8호)\n◦계약을 해제·해지 경우(시행령 제27조)\n◦재공고입찰 결과 입찰이 성립하지 아니 하거나 낙찰자가 없는 경우(시행령 제26조제1항)\n◦시행령 제95조제1항제4호에 따른 대안입찰, 같은 항 제5호에 따른 일괄입찰 또는 제127조제2호, 제3호에 따른 기술제안입찰로 발주되었으나 재공고입찰 결과 입찰자가 1인 뿐인 경우\n◦지정정보처리장치를 이용하여 견적서를 제출 받았으나 견적서 제출자가 1인 뿐인 경우로서 다시 견적서를 제출 받더라도 견적서 제출자가 1인 뿐일 것으로 명백히 예상되는 경우(시행령 제30조제1항제3호)\n◦(금액기준 예외) 추정가격 5천만 원 이하 1인 견적 가능한 경우\n- 여성기업(여성기업지원에 관한 법률 제2조제1호)\n- 장애인기업(장애인기업활동 촉진법 제2조제2호)\n- 취약계층 고용비율 30% 이상 아래 사회적경제기업\n▷ 사회적기업(사회적기업 육성법 제2조제1호)\n▷ 사회적협동조합(협동조합 기본법 제2조제3호)\n▷ 자활기업(국민기초생활 보장법 제18조)\n▷ 마을기업(도시재생 활성화 및 지원에 관한 특별법 제2조제1항제9호)\n※ 취약계층 고용비율 확인서 발급기준은 지방자치단체 입찰 및 계약 집행기준 제5장 수의계약 운영요령 [별표 3] 확인\n- 청년창업기업(중소기업창업 지원법 제2조제11호)","colSpan":1,"rowSpan":5,"column":3}],[{"text":"전문공사","colSpan":1,"rowSpan":1,"column":1},{"text":"2천만 원\n이하","colSpan":1,"rowSpan":1,"column":2}],[{"text":"전기소방\n통신","colSpan":1,"rowSpan":1,"column":1},{"text":"2천만 원\n이하","colSpan":1,"rowSpan":1,"column":2}],[{"text":"물품제조·구매","colSpan":2,"rowSpan":1,"column":0},{"text":"2천만 원\n이하","colSpan":1,"rowSpan":1,"column":2}],[{"text":"용역·\n기타","colSpan":2,"rowSpan":1,"column":0},{"text":"2천만 원\n이하","colSpan":1,"rowSpan":1,"column":2}]],"widths":[3.7,6.53,13.54,76.23],"lineStart":11,"lineCount":7}]},{"id":"c17-w04-b13","title":"TIP","body":"▪ 견적서를 생략 가능한 경우(지방계약법 시행규칙 제33조)\n순 / 견적서를 생략 가능한 경우\n1 / 전기 ․ 가스 ․ 수도 등의 계약\n2 / 추정가격이 200만 원 미만인 물품의 제조 ․ 구매 ․ 임차 및 용역계약\n3 / 추정가격이 200만 원 미만인 물품을 신용카드로 구매하는 경우\n4 / 국가 및 다른 지방자치단체와 수의계약"},{"id":"c17-w04-b14","title":"세부내용 4. 중앙조달요청","body":""},{"id":"c17-w04-b15","title":"관련법규 및 참고자료","body":"• 「조달사업에 관한 법률 시행령」 제11조, 제19조"},{"id":"c17-w04-b16","title":"","body":"단계 업무내용 세부사항 및 처리 방법\n1 조달계약요청서 작성 및 송신 ◦G2B 시스템 사용 - 공사 계약 요청: G2B → 발주 → 발주목록 → 중앙조달요청(검색유형) → 신규입력 → 업무구분(공사) → 계약요청서 등록 - 물품 / 용역 계약 요청: G2B → 발주 → 발주목록 → 중앙조달요청(검색유형) → 신규입력 → 업무구분(물품, 용역) → 계약요청서 등록\n2 계약요청응답서 접수 ◦계약요청 후 약 10일 이상 소요 ◦조달청에서 내역서 검토 후 계약체결 공문 및 응답서 송부\n3 낙찰자 선정 통보서 및 계약체결 알림 접수 ◦계약요청응답서 접수 후 15~60일 소요 ◦조달청이 사전규격공개, 입찰공고, 계약체결 등을 공문으로 안내 ◦지방계약법 제7조 제2항 적용\n4 공사 또는 용역 이행 (감독) ◦조달청은 계약체결까지만 수행 ◦착공계(공사) 또는 착수계(용역)는 학교에서 직접 접수·관리\n5 검수(검사) ◦물품 납품 후 영수증 작성 ◦준공검사조서 작성 등 검수 절차 수행\n6 하자보수보증금(서) 징구 및 준공사진 접수 준공 완료 후 하자보수보증금 및 관련 서류, 준공사진 등 접수\n7 청구서 접수 및 대가 지급 대금 지급은 조달요청서 작성 시 선택한 지급 방식(대지급 또는 직접지급)에 따라 지급","tables":[{"headers":[{"text":"단계","colSpan":1,"rowSpan":1,"column":0},{"text":"업무내용","colSpan":1,"rowSpan":1,"column":1},{"text":"세부사항 및 처리 방법","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"1","colSpan":1,"rowSpan":1,"column":0},{"text":"조달계약요청서\n작성 및 송신","colSpan":1,"rowSpan":1,"column":1},{"text":"◦G2B 시스템 사용\n- 공사 계약 요청: G2B → 발주 → 발주목록 → 중앙조달요청(검색유형) → 신규입력 → 업무구분(공사) → 계약요청서 등록\n- 물품 / 용역 계약 요청: G2B → 발주 → 발주목록 → 중앙조달요청(검색유형) → 신규입력 → 업무구분(물품, 용역) → 계약요청서 등록","colSpan":1,"rowSpan":1,"column":2}],[{"text":"2","colSpan":1,"rowSpan":1,"column":0},{"text":"계약요청응답서 접수","colSpan":1,"rowSpan":1,"column":1},{"text":"◦계약요청 후 약 10일 이상 소요\n◦조달청에서 내역서 검토 후 계약체결 공문 및 응답서 송부","colSpan":1,"rowSpan":1,"column":2}],[{"text":"3","colSpan":1,"rowSpan":1,"column":0},{"text":"낙찰자 선정 통보서 및 계약체결 알림 접수","colSpan":1,"rowSpan":1,"column":1},{"text":"◦계약요청응답서 접수 후 15~60일 소요\n◦조달청이 사전규격공개, 입찰공고, 계약체결 등을 공문으로 안내\n◦지방계약법 제7조 제2항 적용","colSpan":1,"rowSpan":1,"column":2}],[{"text":"4","colSpan":1,"rowSpan":1,"column":0},{"text":"공사 또는 용역 이행 (감독)","colSpan":1,"rowSpan":1,"column":1},{"text":"◦조달청은 계약체결까지만 수행\n◦착공계(공사) 또는 착수계(용역)는 학교에서 직접 접수·관리","colSpan":1,"rowSpan":1,"column":2}],[{"text":"5","colSpan":1,"rowSpan":1,"column":0},{"text":"검수(검사)","colSpan":1,"rowSpan":1,"column":1},{"text":"◦물품 납품 후 영수증 작성\n◦준공검사조서 작성 등 검수 절차 수행","colSpan":1,"rowSpan":1,"column":2}],[{"text":"6","colSpan":1,"rowSpan":1,"column":0},{"text":"하자보수보증금(서) 징구 및 준공사진 접수","colSpan":1,"rowSpan":1,"column":1},{"text":"준공 완료 후 하자보수보증금 및 관련 서류, 준공사진 등 접수","colSpan":1,"rowSpan":1,"column":2}],[{"text":"7","colSpan":1,"rowSpan":1,"column":0},{"text":"청구서 접수 및 대가 지급","colSpan":1,"rowSpan":1,"column":1},{"text":"대금 지급은 조달요청서 작성 시 선택한 지급 방식(대지급 또는 직접지급)에 따라 지급","colSpan":1,"rowSpan":1,"column":2}]],"widths":[7.71,22.31,69.98],"lineStart":0,"lineCount":8}]},{"id":"c17-w04-b17","title":"세부내용 5. 다수공급자계약","body":""},{"id":"c17-w04-b18","title":"관련법규 및 참고자료","body":"• 물품 다수공급자계약 업무처리규정\n• 용역 다수공급자계약 업무처리규정"},{"id":"c17-w04-b19","title":"","body":"항목 내용 비고\nMAS(다수공급자계약) 개념 조달청이 품질·성능·효율 등에서 유사한 물품을 공급 가능한 자 2인 이상과 단가계약을 체결하고, 수요기관이 나라장터 종합쇼핑몰에서 자유롭게 선택하여 구매하는 제도 나라장터 종합쇼핑몰 이용\n적용 대상 및 기준 ◦일반 물품(모든 기관): 5천만 원 이상 ◦중소기업 제조 물품: 1억원 이상 ※ 5천만원 이상의 경우에도 다수공급자계약 가능 ◦중기간 경쟁물품: 1억 원 이상 1회 납품요구 기준 (세부품명 및 업체 구분 없이 총합금액 기준) ※ 설치비 제외\n항목 내용 비고\n분할발주 제한 조건 G2B 시스템 자동 차단 조건: 동일 업체, 동일 세부품명 기준 최근 30일 이내 분할 발주 시 시스템 자동 차단 적용\n계약상대자 2인 미만 시 처리 수요기관 구매희망 규격을 충족하면서 예산 범위 내 계약대상자가 2인 미만일 경우, 아래 방식으로 2단계 경쟁 실시 - 구매 희망 규격 내 세부품명이 2개 이상이면서 해당 세부품명의 물품분류번호 상위 2자리(대분류번호)가 모두 동일한 경우 → 공동수급체 구성 또는 제안공고 - 그 외 → 제안공고 방식 적용 물품 다수공급자계약 업무처리규정 제52조 제7항\n다수공급자계약 2단계 경쟁 업무처리 절차 ◦제안요청 (5억 원 이하) - 수요기관 제안요청 - 업체 제안서 제출 - 제안서 평가 - 납품요구 및 납품 - 대금지급 ◦대상업체 5개사 이상 선정 ◦종합평가방식 또는 표준평가방식 적용\n◦제안공고 (5억 원 이상) - 수요기관 제안공고 - 업체 제안서 제출 - 제안서 평가 - 납품요구 및 납품 - 대금지급 규격·수량·예산·평가 방법 공고\n예산 집행 품의 ◦사업계획서에 상세 규격 명시 ◦물품선정위원회를 통해 5개 이상 업체 사전 선정\n내부결재 및 공고문 작성 ◦공고문 작성 시 공동수급체 등록 마감일은 공고일 기준 최소 5일 이후로 설정 ◦공동수급체 구성 시 - 각 구성원 1개 이상 세부품명 등록 - 같은 세부품명 중복 등록 불가 [예시 9] 참고\n유의사항 제안서 제출 마감일은 공휴일 및 토요일 제외, 제안요청일 또는 제안공고일 기준 만 5일 이후로 설정\n제안요청 ◦5개사 이상 납품 대상업체 선정 ※ 예산범위 내에서 2인 이상 5인 미만일 경우, 사유서[서식 18] 제출 시 경쟁 가능 ◦물품분류번호(8자리)와 세부품명 동일 (옵션 제외) ◦설치비가 옵션품목으로 계약된 경우 제안요청 대상에서 제외\n제안요청 취소 가능 사유 - 제안요청서 입력 오류 등 자체 과실 - 사업 변경으로 인해 제안요청 결과로 목적 달성 불가능 - 계속 진행이 불합리하다고 판단되는 경우 ※ 예산감소로 인한 취소는 당초예산 변경 시만 가능 ※ 계약상대자에게 취소사유서[서식 19] 통보 필요 물품 다수공급자계약 업무처리규정 제56조\n항목 내용 비고\n제안서 제출 (계약희망업체) ◦제안가격은 나라장터 계약단가 이하로 가능 ◦계약가격의 90% 미만으로 제안 불가(중소기업자간 경쟁물품인 경우에 한함) ◦할인율이 10% 초과하는 경우에도 90%로 평가 ◦할인행사 또는 다량납품 요건 중 높은 할인율 기준으로 제안\n◦제안서 제출 거부 시 나라장터 계약조건으로 제안 간주 ◦제안서 취소 가능 여부 - 마감 전: 취소 가능하나 재제출 불가 ※ 물품: 취소시 쇼핑몰 가격으로 제출한 것으로 간주 ※ 용역: 취소시 평가대상에서 제외 - 마감 후 ▷ 물품: 취소 불가 ▷ 용역: 제안가격 오류시 가능(조건부) ◦제안서 보완: - 일부 서류 누락 또는 불명확 시 3일 이내 보완 가능 - 기한 내 미제출 시 기존 서류 + 나라장터 계약조건으로 평가 물품 다수공급자계약 업무처리규정 제54조의2 용역 다수공급자계약 업무처리규정 제29조 물품 다수공급자계약 업무처리규정 제54조 용역 다수공급자계약 업무처리규정 제30조\n납품대상업체 선정기준 제안서 평가 종합점수 기준 - 물품: 2단계 경쟁 종합평가 또는 표준평가방식에 따라 최고 점수 제안자 선정 - 용역: 2단계 경쟁 종합평가방식에 따라 최고 점수 제안자 선정 물품 다수공급자계약 업무처리규정 용역 다수공급자계약 업무처리규정\n동점자 처리 ◦물품: 물품 다수공급자계약 업무처리규정 제53조 참고 ◦용역: 용역 다수공급자계약 업무처리규정 제24조 참고\n납품요구 ◦제안 유효기간 내 납품요구 가능 (유효기간 경과 시 납품요구 불가) ◦계약 수정 시 유효기간 내 업체 동의 얻으면 납품요구 가능 (계약 종료 후 불가) ◦납품요구량 변경 시 납품대상업체 동의 필요 ◦제안가격 변경 시 상호 협의된 가격 반영","tables":[{"headers":[{"text":"항목","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1},{"text":"비고","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"MAS(다수공급자계약)\n개념","colSpan":1,"rowSpan":1,"column":0},{"text":"조달청이 품질·성능·효율 등에서 유사한 물품을 공급 가능한 자 2인 이상과 단가계약을 체결하고, 수요기관이 나라장터 종합쇼핑몰에서 자유롭게 선택하여 구매하는 제도","colSpan":1,"rowSpan":1,"column":1},{"text":"나라장터 종합쇼핑몰 이용","colSpan":1,"rowSpan":1,"column":2}],[{"text":"적용 대상 및 기준","colSpan":1,"rowSpan":1,"column":0},{"text":"◦일반 물품(모든 기관): 5천만 원 이상\n◦중소기업 제조 물품: 1억원 이상\n※ 5천만원 이상의 경우에도 다수공급자계약 가능\n◦중기간 경쟁물품: 1억 원 이상","colSpan":1,"rowSpan":1,"column":1},{"text":"1회 납품요구 기준\n(세부품명 및 업체 구분 없이 총합금액 기준)\n※ 설치비 제외","colSpan":1,"rowSpan":1,"column":2}]],"widths":[19.88,55.76,24.36],"lineStart":0,"lineCount":3},{"headers":[{"text":"항목","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1},{"text":"비고","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"분할발주 제한 조건","colSpan":1,"rowSpan":1,"column":0},{"text":"G2B 시스템 자동 차단 조건: 동일 업체, 동일 세부품명 기준 최근 30일 이내 분할 발주 시","colSpan":1,"rowSpan":1,"column":1},{"text":"시스템 자동 차단 적용","colSpan":1,"rowSpan":1,"column":2}],[{"text":"계약상대자\n2인 미만 시\n처리","colSpan":1,"rowSpan":1,"column":0},{"text":"수요기관 구매희망 규격을 충족하면서 예산 범위 내 계약대상자가 2인 미만일 경우, 아래 방식으로 2단계 경쟁 실시\n- 구매 희망 규격 내 세부품명이 2개 이상이면서 해당 세부품명의 물품분류번호 상위 2자리(대분류번호)가 모두 동일한 경우 → 공동수급체 구성 또는 제안공고\n- 그 외 → 제안공고 방식 적용","colSpan":1,"rowSpan":1,"column":1},{"text":"물품 다수공급자계약 업무처리규정 제52조 제7항","colSpan":1,"rowSpan":1,"column":2}],[{"text":"다수공급자계약\n2단계 경쟁\n업무처리 절차","colSpan":1,"rowSpan":2,"column":0},{"text":"◦제안요청 (5억 원 이하)\n- 수요기관 제안요청\n- 업체 제안서 제출\n- 제안서 평가\n- 납품요구 및 납품\n- 대금지급","colSpan":1,"rowSpan":1,"column":1},{"text":"◦대상업체 5개사 이상 선정\n◦종합평가방식 또는 표준평가방식 적용","colSpan":1,"rowSpan":1,"column":2}],[{"text":"◦제안공고 (5억 원 이상)\n- 수요기관 제안공고\n- 업체 제안서 제출\n- 제안서 평가\n- 납품요구 및 납품\n- 대금지급","colSpan":1,"rowSpan":1,"column":1},{"text":"규격·수량·예산·평가 방법 공고","colSpan":1,"rowSpan":1,"column":2}],[{"text":"예산 집행 품의","colSpan":1,"rowSpan":1,"column":0},{"text":"◦사업계획서에 상세 규격 명시\n◦물품선정위원회를 통해 5개 이상 업체 사전 선정","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"내부결재 및 공고문 작성","colSpan":1,"rowSpan":1,"column":0},{"text":"◦공고문 작성 시 공동수급체 등록 마감일은 공고일 기준 최소 5일 이후로 설정\n◦공동수급체 구성 시\n- 각 구성원 1개 이상 세부품명 등록\n- 같은 세부품명 중복 등록 불가","colSpan":1,"rowSpan":1,"column":1},{"text":"[예시 9] 참고","colSpan":1,"rowSpan":1,"column":2}],[{"text":"유의사항","colSpan":1,"rowSpan":1,"column":0},{"text":"제안서 제출 마감일은 공휴일 및 토요일 제외, 제안요청일 또는 제안공고일 기준 만 5일 이후로 설정","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"제안요청","colSpan":1,"rowSpan":2,"column":0},{"text":"◦5개사 이상 납품 대상업체 선정\n※ 예산범위 내에서 2인 이상 5인 미만일 경우, 사유서[서식 18] 제출 시 경쟁 가능\n◦물품분류번호(8자리)와 세부품명 동일 (옵션 제외)\n◦설치비가 옵션품목으로 계약된 경우 제안요청 대상에서 제외","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"제안요청 취소 가능 사유\n- 제안요청서 입력 오류 등 자체 과실\n- 사업 변경으로 인해 제안요청 결과로 목적 달성 불가능\n- 계속 진행이 불합리하다고 판단되는 경우\n※ 예산감소로 인한 취소는 당초예산 변경 시만 가능\n※ 계약상대자에게 취소사유서[서식 19] 통보 필요","colSpan":1,"rowSpan":1,"column":1},{"text":"물품 다수공급자계약 업무처리규정 제56조","colSpan":1,"rowSpan":1,"column":2}]],"widths":[19.88,55.76,24.36],"lineStart":3,"lineCount":10},{"headers":[{"text":"항목","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1},{"text":"비고","colSpan":1,"rowSpan":1,"column":2}],"rows":[[{"text":"제안서 제출\n(계약희망업체)","colSpan":1,"rowSpan":2,"column":0},{"text":"◦제안가격은 나라장터 계약단가 이하로 가능\n◦계약가격의 90% 미만으로 제안 불가(중소기업자간 경쟁물품인 경우에 한함)\n◦할인율이 10% 초과하는 경우에도 90%로 평가\n◦할인행사 또는 다량납품 요건 중 높은 할인율 기준으로 제안","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"◦제안서 제출 거부 시 나라장터 계약조건으로 제안 간주\n◦제안서 취소 가능 여부\n- 마감 전: 취소 가능하나 재제출 불가\n※ 물품: 취소시 쇼핑몰 가격으로 제출한 것으로 간주\n※ 용역: 취소시 평가대상에서 제외\n- 마감 후\n▷ 물품: 취소 불가\n▷ 용역: 제안가격 오류시 가능(조건부)\n◦제안서 보완:\n- 일부 서류 누락 또는 불명확 시 3일 이내 보완 가능\n- 기한 내 미제출 시 기존 서류 + 나라장터 계약조건으로 평가","colSpan":1,"rowSpan":1,"column":1},{"text":"물품 다수공급자계약 업무처리규정 제54조의2\n용역 다수공급자계약 업무처리규정 제29조\n물품 다수공급자계약 업무처리규정 제54조\n용역 다수공급자계약 업무처리규정 제30조","colSpan":1,"rowSpan":1,"column":2}],[{"text":"납품대상업체 선정기준","colSpan":1,"rowSpan":1,"column":0},{"text":"제안서 평가 종합점수 기준\n- 물품: 2단계 경쟁 종합평가 또는 표준평가방식에 따라 최고 점수 제안자 선정\n- 용역: 2단계 경쟁 종합평가방식에 따라 최고 점수 제안자 선정","colSpan":1,"rowSpan":1,"column":1},{"text":"물품 다수공급자계약 업무처리규정\n용역 다수공급자계약 업무처리규정","colSpan":1,"rowSpan":1,"column":2}],[{"text":"동점자 처리","colSpan":1,"rowSpan":1,"column":0},{"text":"◦물품: 물품 다수공급자계약 업무처리규정 제53조 참고\n◦용역: 용역 다수공급자계약 업무처리규정 제24조 참고","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}],[{"text":"납품요구","colSpan":1,"rowSpan":1,"column":0},{"text":"◦제안 유효기간 내 납품요구 가능\n(유효기간 경과 시 납품요구 불가)\n◦계약 수정 시 유효기간 내 업체 동의 얻으면 납품요구 가능 (계약 종료 후 불가)\n◦납품요구량 변경 시 납품대상업체 동의 필요\n◦제안가격 변경 시 상호 협의된 가격 반영","colSpan":1,"rowSpan":1,"column":1},{"text":"","colSpan":1,"rowSpan":1,"column":2}]],"widths":[19.88,55.76,24.36],"lineStart":13,"lineCount":6}]}],"flowGroups":[]},{"id":"c17-w05","number":5,"title":"부정당업자 제재","formIds":[],"faqCategories":[],"contentBlocks":[{"id":"c17-w05-b1","title":"세부내용 1. 부정당업자 제재 개념","body":""},{"id":"c17-w05-b2","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률」 제31조\n• 「같은 법 시행령」 제92조, 「같은 법 시행규칙」 제76조\n• 「행정절차법」 제21조, 제22조"},{"id":"c17-w05-b3","title":"","body":"구분 내용\n제재 주체 각 중앙관서의 장 (지방자치단체의 장)\n제재 대상 ◦개인사업자: 해당 개인사업자 ◦법인(단체): 법인(단체) 및 대표자 (업무 관장 대표자) ◦조합 등 기타단체: 해당 조합 및 원인 직접 야기 조합원 ◦공동도급계약: 입찰참가제한 사유 직접 야기자에 한함\n제재 시기 및 기간 ◦제재 시기: 입찰참가자격 제한 사실 인지 후 지체 없이 시행 ◦제재 기간: 1월 이상 2년 이하 (사유별 발생원인, 고의성 등 종합 고려) ◦경감: 위반 경미 시 최대 6개월 ※ 제한기간을 경감하는 경우에도 그 제한기간이 1개월 이상 되도록 해야함 ◦가중: 처분일로부터 자격 제한 종료 후 6개월 내 재발 시 2배까지 가중 가능\n제재 사유 ◦계약 이행 부실, 조잡, 부당, 부정 행위 ◦정당한 이유 없이 낙찰 후 계약 미체결 또는 계약 불이행, 계약 조건 위반 ◦입찰·계약 서류 위조, 변조, 부정 행사 또는 거짓서류 제출 ◦고의 무효 입찰 ◦기타 관련 법령(지방계약법 제31조 등) 참조\n▸계약체결 전: 수의계약 참가제한(정당한 이유 없이 계약에 응하지 아니하거나 포기서를 제출할 경우)\n▸계약체결 후: 부정당 제재처분(정당한 사유 없이 계약을 이행하지 아니할 경우)\n2인 이상수의계약 견적서 제출공고 계약포기의 경우","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"제재 주체","colSpan":1,"rowSpan":1,"column":0},{"text":"각 중앙관서의 장 (지방자치단체의 장)","colSpan":1,"rowSpan":1,"column":1}],[{"text":"제재 대상","colSpan":1,"rowSpan":1,"column":0},{"text":"◦개인사업자: 해당 개인사업자\n◦법인(단체): 법인(단체) 및 대표자 (업무 관장 대표자)\n◦조합 등 기타단체: 해당 조합 및 원인 직접 야기 조합원\n◦공동도급계약: 입찰참가제한 사유 직접 야기자에 한함","colSpan":1,"rowSpan":1,"column":1}],[{"text":"제재 시기 및 기간","colSpan":1,"rowSpan":1,"column":0},{"text":"◦제재 시기: 입찰참가자격 제한 사실 인지 후 지체 없이 시행\n◦제재 기간: 1월 이상 2년 이하 (사유별 발생원인, 고의성 등 종합 고려)\n◦경감: 위반 경미 시 최대 6개월\n※ 제한기간을 경감하는 경우에도 그 제한기간이 1개월 이상 되도록 해야함\n◦가중: 처분일로부터 자격 제한 종료 후 6개월 내 재발 시 2배까지 가중 가능","colSpan":1,"rowSpan":1,"column":1}],[{"text":"제재 사유","colSpan":1,"rowSpan":1,"column":0},{"text":"◦계약 이행 부실, 조잡, 부당, 부정 행위\n◦정당한 이유 없이 낙찰 후 계약 미체결 또는 계약 불이행, 계약 조건 위반\n◦입찰·계약 서류 위조, 변조, 부정 행사 또는 거짓서류 제출\n◦고의 무효 입찰\n◦기타 관련 법령(지방계약법 제31조 등) 참조","colSpan":1,"rowSpan":1,"column":1}]],"widths":[21.32,78.68],"lineStart":0,"lineCount":5}]},{"id":"c17-w05-b4","title":"세부내용 2. 부정당업자 제재 절차","body":""},{"id":"c17-w05-b5","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제92조\n• 「같은 법 시행규칙」 제76조"},{"id":"c17-w05-b6","title":"","body":"<부정당업자 제재절차>\n제재절차 세부사항\n계약체결요구 또는 계약진행 물품 · 용역 · 시설공사 계약에 있어 계약상대자가 - 계약을 체결(또는 계약을 이행)하지 않거나 - 계약조건을 위반한 경우 발생\n계약이행(계약체결) 촉구 계약이행 촉구 또는 계약위반에 대한 시정요구 공문발송 (내용증명, 2~3차례) - 부정당업자 제재처분 가능하다는 내용 반드시 명시\n부정당업자제재 사유 발생 ◦업체의 계약포기서 제출 - 계약 체결 포기 또는 계약 이행 포기(경영상태 악화 등) ◦계약조건 위반에 따른 시정 촉구를 받고도 이에 응하지 않는 경우 등 부정당업자 제재 사유 발생\n처분사전통지 및 의견청취 ◦부정당업자 제재처분을 하고자 하는 경우에는 처분사항을 사전에 통지하고, 대상자에게 의견 진술의 기회를 부여 ⇒ 내용증명 발송 ◦[공사]부정당업자 제재 처분[예시10] ◦사전통지 내용 - 처분의 제목 - 당사자의 성명 또는 명칭과 주소 - 처분하고자 하는 원인이 되는 사실과 처분의 내용 및 법적 근거(부정당업자 제재 ○개월 처분) - 위에 대한 의견을 제출할 수 있다는 뜻과 의견제출기한 내에 의견을 제출하지 아니하는 경우에는 의견이 없는 것으로 간주함을 명시 - 의견 제출 기관의 명칭과 주소 - 의견 제출 기한: 의견 제출에 필요한 상당한 기간을 고려하여 산정(통상 10일 이상) - 기타 필요한 사항\n부정당업자 제재 처분 요청 ◦부정당업자 제재 처분 요청 - 초 ․ 중학교 → 교육지원청 → 전북특별자치도교육청(재무과) - 그 외 기관 → 전북특별자치도교육청(재무과) ◦제출서류 - 부정당업자 제재 심의요청서(제재 요청기간 명시) - 계약심의위원회 심의 보충 자료 - 제재 대상자가 제출한 의견서 - 기타 관련서류 사본(법인인 경우 등기부등본 등)\n제재절차 세부사항\n도교육청 처리사항 시행 ◦처분검토 - 부정당업자 제재사유 타당여부 검토 - 부정당업자 제재기간 검토 - 의견제출내용과 제재사유가 부족할 경우 재청문 실시 ◦계약심의위원회 심의 및 제재조치 ◦제재내용 통보 - 부정당업자의 제재는 당사자에게 문서로 통지(송달) - 처분의 고지내용 ▷ 처분의 근거와 이유 ▷ 처분행정청, 담당자의 소속, 성명, 전화번호 ▷ 처분에 대한 행정심판을 제기할 수 있는지 여부 ▷ 불복절차 및 청구기간 - 국가종합전자조달시스템 상에 게시(관보게재 폐지) ▷ 업체(상호)명, 주소, 성명(법인인 경우 대표자), 주민등록번호(법인등록번호), 사업자등록번호, 관계법령상 면허 또는 등록번호 ▷ 입찰참가자격 제한기간 ▷ 입찰참가자격을 제한하는 구체적인 사유","tables":[{"headers":[{"text":"제재절차","colSpan":1,"rowSpan":1,"column":0},{"text":"세부사항","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"계약체결요구 또는 계약진행","colSpan":1,"rowSpan":1,"column":0},{"text":"물품 · 용역 · 시설공사 계약에 있어 계약상대자가\n- 계약을 체결(또는 계약을 이행)하지 않거나\n- 계약조건을 위반한 경우 발생","colSpan":1,"rowSpan":1,"column":1}],[{"text":"계약이행(계약체결) 촉구","colSpan":1,"rowSpan":1,"column":0},{"text":"계약이행 촉구 또는 계약위반에 대한 시정요구 공문발송\n(내용증명, 2~3차례)\n- 부정당업자 제재처분 가능하다는 내용 반드시 명시","colSpan":1,"rowSpan":1,"column":1}],[{"text":"부정당업자제재 사유 발생","colSpan":1,"rowSpan":1,"column":0},{"text":"◦업체의 계약포기서 제출\n- 계약 체결 포기 또는 계약 이행 포기(경영상태 악화 등)\n◦계약조건 위반에 따른 시정 촉구를 받고도 이에 응하지 않는 경우 등 부정당업자 제재 사유 발생","colSpan":1,"rowSpan":1,"column":1}],[{"text":"처분사전통지 및 의견청취","colSpan":1,"rowSpan":1,"column":0},{"text":"◦부정당업자 제재처분을 하고자 하는 경우에는 처분사항을 사전에 통지하고, 대상자에게 의견 진술의 기회를 부여 ⇒ 내용증명 발송\n◦[공사]부정당업자 제재 처분[예시10]\n◦사전통지 내용\n- 처분의 제목\n- 당사자의 성명 또는 명칭과 주소\n- 처분하고자 하는 원인이 되는 사실과 처분의 내용 및 법적 근거(부정당업자 제재 ○개월 처분)\n- 위에 대한 의견을 제출할 수 있다는 뜻과 의견제출기한 내에 의견을 제출하지 아니하는 경우에는 의견이 없는 것으로 간주함을 명시\n- 의견 제출 기관의 명칭과 주소\n- 의견 제출 기한: 의견 제출에 필요한 상당한 기간을 고려하여 산정(통상 10일 이상)\n- 기타 필요한 사항","colSpan":1,"rowSpan":1,"column":1}],[{"text":"부정당업자 제재 처분 요청","colSpan":1,"rowSpan":1,"column":0},{"text":"◦부정당업자 제재 처분 요청\n- 초 ․ 중학교 → 교육지원청 → 전북특별자치도교육청(재무과)\n- 그 외 기관 → 전북특별자치도교육청(재무과)\n◦제출서류\n- 부정당업자 제재 심의요청서(제재 요청기간 명시)\n- 계약심의위원회 심의 보충 자료\n- 제재 대상자가 제출한 의견서\n- 기타 관련서류 사본(법인인 경우 등기부등본 등)","colSpan":1,"rowSpan":1,"column":1}]],"widths":[27.28,72.72],"lineStart":1,"lineCount":6},{"headers":[{"text":"제재절차","colSpan":1,"rowSpan":1,"column":0},{"text":"세부사항","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"도교육청 처리사항 시행","colSpan":1,"rowSpan":1,"column":0},{"text":"◦처분검토\n- 부정당업자 제재사유 타당여부 검토\n- 부정당업자 제재기간 검토\n- 의견제출내용과 제재사유가 부족할 경우 재청문 실시\n◦계약심의위원회 심의 및 제재조치\n◦제재내용 통보\n- 부정당업자의 제재는 당사자에게 문서로 통지(송달)\n- 처분의 고지내용\n▷ 처분의 근거와 이유\n▷ 처분행정청, 담당자의 소속, 성명, 전화번호\n▷ 처분에 대한 행정심판을 제기할 수 있는지 여부\n▷ 불복절차 및 청구기간\n- 국가종합전자조달시스템 상에 게시(관보게재 폐지)\n▷ 업체(상호)명, 주소, 성명(법인인 경우 대표자), 주민등록번호(법인등록번호), 사업자등록번호, 관계법령상 면허 또는 등록번호\n▷ 입찰참가자격 제한기간\n▷ 입찰참가자격을 제한하는 구체적인 사유","colSpan":1,"rowSpan":1,"column":1}]],"widths":[30.4,69.6],"lineStart":7,"lineCount":2}]},{"id":"c17-w05-b7","title":"세부내용 3. 부정당업자 제재 효력","body":""},{"id":"c17-w05-b8","title":"관련법규 및 참고자료","body":"• 「지방자치단체를 당사자로 하는 계약에 관한 법률 시행령」 제92조"},{"id":"c17-w05-b9","title":"","body":"구분 내용\n제재효력 범위 경쟁입찰에 처분기간 동안 입찰참가자격 제한\n제재효력의 승계 ◦업체 및 대표자에게 효력 발생 ◦2개 이상의 면허를 보유한 법인은 모든 면허에 제재효과 미침 ◦법인 양도·양수 시 제재효력 승계 ◦법인 합병 시, 합병된 법인이 기존 부정당업자 제재를 받은 법인의 면허번호, 등록번호, 법인등록번호 등 주요 식별번호가 동일하거나 실질적으로 동일한 경우(즉, 두 법인이 실질적으로 동일한 법인으로 인정되는 경우)에 한해 제재효력이 승계됨 ◦제재 조치 이전에 체결하여 이행 중인 계약에는 원칙적으로 영향 없음","tables":[{"headers":[{"text":"구분","colSpan":1,"rowSpan":1,"column":0},{"text":"내용","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"제재효력 범위","colSpan":1,"rowSpan":1,"column":0},{"text":"경쟁입찰에 처분기간 동안 입찰참가자격 제한","colSpan":1,"rowSpan":1,"column":1}],[{"text":"제재효력의 승계","colSpan":1,"rowSpan":1,"column":0},{"text":"◦업체 및 대표자에게 효력 발생\n◦2개 이상의 면허를 보유한 법인은 모든 면허에 제재효과 미침\n◦법인 양도·양수 시 제재효력 승계\n◦법인 합병 시, 합병된 법인이 기존 부정당업자 제재를 받은 법인의 면허번호, 등록번호, 법인등록번호 등 주요 식별번호가 동일하거나 실질적으로 동일한 경우(즉, 두 법인이 실질적으로 동일한 법인으로 인정되는 경우)에 한해 제재효력이 승계됨\n◦제재 조치 이전에 체결하여 이행 중인 계약에는 원칙적으로 영향 없음","colSpan":1,"rowSpan":1,"column":1}]],"widths":[29.4,70.6],"lineStart":0,"lineCount":3}]},{"id":"c17-w05-b10","title":"TIP","body":"▸부정당업자 제재는 지방자치단체를 당사자로 하는 계약에 관한 법률 시행령 제92조에 열거된 제재사유를 명확히 해석하여 적용하여야 하며, 제재사유를 확대 해석하거나 유추 해석해서는 안됨\n▸부정당제재 효력은 부정당제재조치 이전에 계약을 체결하여 이행중인 계약에 대하여는 원칙적으로 아무런 영향을 미치지 아니함"}],"flowGroups":[]},{"id":"c17-w06","number":6,"title":"수의계약 배제업체 제재","formIds":[],"faqCategories":[],"contentBlocks":[{"id":"c17-w06-b1","title":"세부내용 수의계약 배제업체 개념 및 절차","body":""},{"id":"c17-w06-b2","title":"관련법규 및 참고자료","body":"• 「지방자치단체 입찰 및 계약집행기준」 제5장 수의계약 운영요령"},{"id":"c17-w06-b4","title":"2. 제재 사유","body":"‣입찰 ․ 계약 및 그 이행과 관련하여 10일 이상 지연배상금을 부과한 경우\n‣정당한 계약의 이행명령을 거부한 경우\n‣불법하도급 업체\n‣5회 이상 하자보수 또는 물의를 일으키는 등 신용이 떨어져 계약체결이 곤란하다고 판단되는 경우\n‣자세한 제재 사유는 지방자치단체 입찰 및 계약집행기준 제5장 수의계약 운영요령 [별표 1] 수의계약 배제사유 참고"},{"id":"c17-w06-b5","title":"TIP","body":"◦수의계약에 있어 정당한 이유 없이 계약을 체결하지 아니하는 경우는 수의계약 배제사유에 해당 되어 수의계약 참가 제한을 하는 것으로, 입찰참가 자격 제한(부정당업자 제재)에는 해당되지 아니함\n◦수의계약에 있어 계약을 체결한 이후 계약 이행을 아니하는 경우는 부정당업자 제재사유에 해당됨\n※ 수의계약 배제기간 동안 업체는 전북특별자치도교육청 소속 기관과 수의계약을 체결할 수 없음"},{"id":"c17-w06-b6","title":"3. 수의계약 배제업체 제재절차","body":"제재절차 세부사항\n계약체결 요구 계약상대자의 계약 미체결 발생\n계약체결 촉구 계약이행 촉구 공문발송(내용증명, 2~3차례) - 수의계약 배제업체 제재 가능하다는 내용 반드시 명시\n제재 사유 발생 업체의 계약포기서 제출\n배제업체 등록 및 공개 수의계약 배제업체 등록 및 공개 - K-에듀파인: 계약관리-계약업체관리-수의계약배제업체관리\n수의계약 배제업체 제재효력 발생 제재효력 - 제재기간 동안 수의계약 계약상대자 선정에서 배제","tables":[{"headers":[{"text":"제재절차","colSpan":1,"rowSpan":1,"column":0},{"text":"세부사항","colSpan":1,"rowSpan":1,"column":1}],"rows":[[{"text":"계약체결 요구","colSpan":1,"rowSpan":1,"column":0},{"text":"계약상대자의 계약 미체결 발생","colSpan":1,"rowSpan":1,"column":1}],[{"text":"계약체결 촉구","colSpan":1,"rowSpan":1,"column":0},{"text":"계약이행 촉구 공문발송(내용증명, 2~3차례)\n- 수의계약 배제업체 제재 가능하다는 내용 반드시 명시","colSpan":1,"rowSpan":1,"column":1}],[{"text":"제재 사유 발생","colSpan":1,"rowSpan":1,"column":0},{"text":"업체의 계약포기서 제출","colSpan":1,"rowSpan":1,"column":1}],[{"text":"배제업체 등록 및 공개","colSpan":1,"rowSpan":1,"column":0},{"text":"수의계약 배제업체 등록 및 공개\n- K-에듀파인: 계약관리-계약업체관리-수의계약배제업체관리","colSpan":1,"rowSpan":1,"column":1}],[{"text":"수의계약 배제업체 제재효력 발생","colSpan":1,"rowSpan":1,"column":0},{"text":"제재효력\n- 제재기간 동안 수의계약 계약상대자 선정에서 배제","colSpan":1,"rowSpan":1,"column":1}]],"widths":[36.48,63.52],"lineStart":0,"lineCount":6}]}],"flowGroups":[]}],"forms":[],"faqs":[],"downloads":{"hwpx":"downloads/manual/제17편 학교회계 계약_251107.hwpx"}};
